namespace spblas {

    enum class cnrProperty {
        default = 0,
        none = 0,
        cnr = 1,
        strict_cnr = 2
    };

    void set_cnr_property(cnrProperty prop); 

    cnrProperty get_cnr_property();

}
\end{minted}
\caption{Conditional Numerical Reproducibility properties in Sparse BLAS}
\end{listing}

