\section{AAoI of Unreliable M/M/1 Tandem Queues}
\label{sec3}
To model a tandem system with \( N = 2 \) unreliable Markovian nodes, we define an irreducible continuous-time Markov chain (CTMC), \( \mathcal{X}(t) = \{(X_0(t), X_1(t), X_2(t)) \mid t \geq 0\} \), where \( X_0(t) \) represents the global operational state of the tandem network, and \( X_1(t) \) and \( X_2(t) \) denote the number of packets at node 1 and node 2, respectively. The network is operational when \( X_0(t) \!=\! 0\) and under repair when \( X_0(t) \!=\! 1 \). The state transition probabilities are given as follows, with the corresponding states and balance equations given in Table~\ref{tab1}:
\begin{equation}
p_{i,n_1,n_2}(t) = \Pr[X_0(t) = i, X_1(t) = n_1, X_2(t) = n_2],  \\
%\lim_{t \to \infty} p_{i,n_1,n_2}(t) &=& q_i(n_1,n_2), \quad i = 0,1; \, n_1, n_2 \geq 0.
\end{equation}
such that $\lim_{t \to \infty} p_{i,n_1,n_2}(t) = q_i(n_1,n_2)$ for $i \in\{0,1\}$ and $n_1,n_2 \geq 0$. To solve the balance equations in Table~\ref{tab1}, along with the normalization condition \(\sum_{n_1,n_2} [q_0(n_1,n_2) + q_1(n_1,n_2)] = 1\), we employ the PGF approach defined below.
\begin{definition}
\label{def1}
%The PGF of the joint stationary queue length distribution is defined as follows, where $|z_1| < 1$ and $|z_2| < 1$:
Let $z_1$ and $z_2$ be auxiliary complex variables associated with the number of packets at node~1 and node~2, respectively. The PGF encodes the joint stationary queue length distribution defined as follows, where $|z_1| < 1$ and $|z_2| < 1$:
\begin{eqnarray}
\Pi_i(z_1, z_2) = \sum_{n=0}^{\infty} \sum_{k=0}^{\infty} q_i(n, k) z_1^n z_2^k, \quad i \in \{0,1\}. %\\
%|z_1| < 1, \ |z_2| < 1. \nonumber
\end{eqnarray}
\end{definition}

From Definition~\ref{def1} and the balance equations in Table~\ref{tab1}, we derive the following system of functional equations, where \( D(z_1, z_2) = z_1 z_2[\lambda(1-z_1) + \gamma] + \mu_1 z_2(z_1 - z_2) + \mu_2 z_1(z_2 - 1) \), \( A(z_1, z_2) = \mu_2 z_1(z_2 - 1) + \mu_1 z_2(z_2 - z_1) \), \( B(z_1, z_2) = -A(z_1, z_2) \), and \( C(z_1, z_2) = \mu_1 z_2(z_2 - z_1) + \mu_2 z_1(z_2 - 1) \):
\begin{subequations}
  \begin{empheq}[left=\empheqlbrace]{align}
    &D(z_1,z_2)\Pi_0(z_1,z_2) = A(z_1,z_2) \Pi_0 (z_1,0) \nonumber \\
    &\qquad\qquad\qquad\qquad\quad\,\, + B(z_1,z_2) \Pi_0(0,z_2) \nonumber \\
    &\qquad\qquad\qquad\qquad\quad\,\, + C(z_1,z_2) \Pi_0(0,0) \nonumber \\
    &\qquad\qquad\qquad\qquad\quad\,\, + \gamma z_1 z_2 \Pi_1(z_1,z_2), \label{eq3a}\\
    &\Pi_1(z_1,z_2) = \frac{\alpha}{\lambda(1-z_1) + \gamma}\Pi_0(z_1,z_2), \label{eq3b}
  \end{empheq}
  \label{eq3}
  \vspace{-0.1cm}
\end{subequations}
%\!\!where \( D(z_1, z_2) = z_1 z_2[\lambda(1-z_1) + \gamma] + \mu_1 z_2(z_1 - z_2) + \mu_2 z_1(z_2 - 1) \), \( A(z_1, z_2) = \mu_2 z_1(z_2 - 1) + \mu_1 z_2(z_2 - z_1) \), \( B(z_1, z_2) = -A(z_1, z_2) \), and \( C(z_1, z_2) = \mu_1 z_2(z_2 - z_1) + \mu_2 z_1(z_2 - 1) \). 
By substituting \eqref{eq3b} into \eqref{eq3a} and performing some algebraic manipulations, we obtain:
\begin{align}
    &\Pi_0(z_1,z_2) \left[\frac{\alpha D(z_1,z_2)}{\lambda(1-z_1)+\gamma}-\alpha \gamma z_1 z_2\right] 
    = \nonumber \\
    &\qquad \frac{\alpha}{\lambda(1-z_1)+\gamma} \left[ A(z_1,z_2) \Pi_0 (z_1,0) + B(z_1,z_2)\Pi_0(0,z_2) \right. \nonumber \\
    &\qquad \left. +\, C(z_1,z_2) \Pi_0(0,0) \right].
    \label{eq4}
\end{align}
\begin{theorem}
    The LST of the sojourn time distribution of the proposed system is given by:
    \begin{align}
        &W^*(s) = P\left(1 - \frac{s}{\lambda}\right)  \nonumber \\
           &= \frac{\frac{\alpha}{\lambda(1 - f(1 - \frac{s}{\lambda})) + \gamma} 
           \Big[ C\big(f(1 \!-\! \frac{s}{\lambda}), (1 \!-\! \frac{s}{\lambda})\big) \Pi_0(0,0) \Big]}
           {\frac{\alpha}{\lambda(1 - f(1 - \frac{s}{\lambda})) + \gamma} 
           D\big(f(1 \!-\! \frac{s}{\lambda}), (1 \!-\! \frac{s}{\lambda})\big) 
           \!- \alpha \gamma f(1 \!-\! \frac{s}{\lambda}) (1 \!-\! \frac{s}{\lambda})},\vspace{-0.2em}
    \end{align}
where $f\left(1 - \frac{s}{\lambda}\right) = \mu_1 (1 - \frac{s}{\lambda})^2/\left(\mu_1 + \mu_2 \left(\frac{s}{\lambda}\right)\right)$.
\end{theorem}
\begin{proof}
From \eqref{eq3b}, it is clear that $\Pi_0(1,1) + \Pi_1(1,1) = 1$. This implies that $\Pi_0(1,1) = \gamma/(\alpha+\gamma)$ and $\Pi_1(1,1) = \alpha/(\alpha+\gamma)$. Now, substituting $z_1 = f(z_2) = \mu_1 z_2^2 /\left(\mu_1 + \mu_2 (1 - z_2)\right)$ in \eqref{eq4} yields the marginal PGF of the stationary queue length distribution of node 2 as follows:
\begin{align}
    P(z_2) &= \Pi_0(f(z_2),z_2) \nonumber \\
    &= \frac{\frac{\alpha}{\lambda(1 - f(z_2)) + \gamma} 
    \big[C(f(z_2),z_2) \Pi_0(0,0)\big]}
    {\frac{\alpha}{\lambda(1 - f(z_2)) + \gamma} 
    D(f(z_2),z_2) - \alpha \gamma f(z_2)z_2}\, ,
    \label{eq6}
\end{align}
since \( A(z_1,z_2) \!= B(z_1,z_2) \!= 0 \). From \eqref{eq6}, as \( z_2 \to 1 \), we get:
\begin{equation}
    \Pi_0(0,0) = \frac{\gamma}{\alpha+\gamma} - \lambda \left[\frac{1}{\mu_1}+\frac{1}{\mu_2} \right].
    \label{eq7}
\end{equation}
Equation~\eqref{eq7} represents the stability condition of the unreliable two-node tandem queueing system as:
\begin{equation}
    \lambda \left[\frac{1}{\mu_1}+\frac{1}{\mu_2} \right] < \frac{\gamma}{\alpha+\gamma}.
\end{equation}
Finally, from \eqref{eq6}, the LST of the sojourn time distribution~of the system, as derived using~\cite{peter2006}, is \(  W^*(s) = P\left(1 - \frac{s}{\lambda} \right) \).
\end{proof}
\vspace{0.3em}

Using the invariant relation~\cite{ino2017} among the AoI, PAoI, and system delay distributions, the LST of the AoI distribution is derived to be:
\begin{equation}
    \Delta^*(s) = \frac{\lambda \big[ W^*(s) \!- W^*(s) h^*(s) \!+W^*(s \!+\! \lambda) \frac{s h^*(s)}{s+\lambda} \big]}{s},
    \label{eq9}
\end{equation}
where \( h^*(s) = \left(\frac{\alpha+\gamma}{\gamma}\right)\! \left(\frac{\mu_1}{s+\mu_1}\right) \!\left(\frac{\mu_2}{s+\mu_2}\right) \). Hence, the AAoI is:
\begin{equation}
    \Delta = -\frac{d \Delta^*(s)}{ds} \Big|_{s \to 0}\, .
    \label{eq10}
\end{equation}

Due to the complexity of deriving the sojourn time distribution in an \(N\)-node unreliable tandem queue, we numerically analyze its impact in our simulations. %\vspace{0.2cm}







