Denoting the LSTs of $p_{k,n}(x)$ and $p_{j,n}(x,y)$ by $p_{k,n}^*(\theta)$ and $p_{j,n}^*(\theta, s)$ for $k \in \{1,3\}$ and $j \in \{2,4\}$ respectively, the marginal PGFs can be expressed as:%\vspace{-0.1cm}
\begin{equation}
\begin{aligned}
    &\left\{
    \begin{aligned}
        &p_{k}^*(z,\theta) = \sum_{n=0}^{\infty} p_{k,n}^*(\theta) z^n, \\
        &p_{k}(z,0) = \sum_{n=0}^{\infty} p_{k,n}(0) z^n, \quad k=1,3, \\
        &p_{j}^*(z,\theta,s) = \sum_{n=0}^{\infty} p_{j,n}^*(\theta,s) z^n, \\
        &p_{j}(z,\theta,0) = \sum_{n=0}^{\infty} p_{j,n}(\theta,0) z^n, \quad j=2,4.
    \end{aligned}
    \right.
\end{aligned}
\end{equation}

Applying LST to both sides of \eqref{eq13} and after some algebraic manipulations, the PGF of the system size is obtained as:
\begin{equation}
    P(z) = \frac{h^*(\phi(0,z)) (1 - z) p_0}{h^*(\phi(0,z)) - z},
    \label{eq16}
\end{equation}
where \( \phi(s,z) = s + \lambda - \lambda z + \alpha - \alpha r^*(s+\lambda-\lambda z) \), \( h^*(s) = s_1^*(s) s_2^*(s) \), and \( p_0 = 1 - \lambda \left( 1 + \frac{\alpha}{\gamma} \right) \left( \frac{1}{\mu_1} + \frac{1}{\mu_2} \right) \) when \( r_1^*(s) = r_2^*(s) = r^*(s) \). Using~\eqref{eq16} and the approach in~\cite{peter2006}, the LST of the sojourn time distribution for an unreliable two-node tandem queueing system is given by \( W^*(s) \!=\! P\left(1-\frac{s}{\lambda}\right)\). In general, we have:
\begin{equation}
        W^*(s) = P\left(1 - \frac{s}{\lambda}\right) 
        = \frac{h^*\left(\phi\left(0, 1 - \frac{s}{\lambda}\right)\right)\left(\frac{s}{\lambda}\right)p_0}{h^*\left(\phi\left(0, 1 - \frac{s}{\lambda}\right)\right) - 1 + \frac{s}{\lambda}}\, ,
        \label{eq17}
    \end{equation}
where $h^*(s) = \prod_{i=1}^{k} f_{s_i}(s)$ and $f_{s_i}(s)$ is the \(i\)-th service time distribution. Using~\eqref{eq16}, the LST of the age distribution for \(N\) unreliable tandem queues is derived in the following theorem.
%Applying the invariant relation from~\cite{ino2017} between the AoI and system delay distributions, the LSTs of the AoI and the AAoI can be derived.
%\begin{note}
    %Using~\cite{peter2006}, the LST of the sojourn time distribution for the generalized unreliable tandem queueing network is:
    %\begin{equation}
        %W^*(s) = P\left(1 - \frac{s}{\lambda}\right) 
        %= \frac{h^*\left(\phi\left(0, 1 - \frac{s}{\lambda}\right)\right)\left(\frac{s}{\lambda}\right)p_0}{h^*\left(\phi\left(0, 1 - \frac{s}{\lambda}\right)\right) - 1 + \frac{s}{\lambda}}\, ,
        %\label{eq17}
    %\end{equation}
    %where $h^*(s) = \prod_{i=1}^{k} f_{s_i}(s)$ and $f_{s_i}(s)$ is the \(i\)-th service time distribution. Using~\eqref{eq16}, the LST of the age distribution for \(N\) unreliable tandem queues is derived in the following theorem.
%\end{note}
\begin{theorem}
    The LST of the age distribution at any node $i$ is:
    \begin{align}
        \Delta^*(s) = W^*(s) - \frac{s p_0 h^*(s)}{s + \lambda h^*(s+\lambda)}.
    %\Delta^*(s) = \frac{\lambda}{s} \bigg[ & W^*(s) - W^*(s) \prod_{i=1}^{k} f_{s_i}(s) \nonumber \\
    %& + W^*(s+\lambda) \frac{s \prod_{i=1}^{k} f_{s_i}(s)}{s + \lambda} \bigg].
    \label{eq18}
\end{align}
\end{theorem}
\begin{proof}
    Let \( Y_k \) denote the inter-arrival time between the \(k\)-th and \((k-1)\)-th packets, and \( T_{i,k} \) the transmission time of the \(k\)-th packet at node \(i\). The \(n\)-th packet, generated at time \(t_n\), is served at time \( t_n' \) at queue~1, with its age ending at \( t_n'' \). Here, we assume \(t_0 = 0\). The age reduction equals the difference between the ages of consecutive packets, which represents the inter-arrival time at queue 1. For $N=2$, the accumulated age is \( Y_1 \times T_1 \), where \( T_1 = t_1'' - t_1 \) is the system time at node 2. Node failures~occur at \( r_i \) during service at node \(i\), followed by repairs over \((r_i, r_i')\). Let \( \{A_t\}_{t \geq 0} \) be the AoI process. A sample path of this process is defined by \( \{(t_n, X_n)\}_{n \geq 0} \), where \( X_n = A_{t_n} \) is the AoI immediately after the \(n\)-th update. For $n \geq 1$ and \(t \in (t_{n-1}, t_n)\), \( A_t \triangleq X_{n-1} + (t - t_{n-1}) \). %is defined to be:
    %\begin{equation}
        %A_t = X_{n-1} + (t - t_{n-1}), \quad t \in (t_{n-1}, t_n).
    %\end{equation}
    Now, consider \( M_t = \sup\{n \in \{0,1,2,\ldots\} : t_n \leq t\} \). Using \( \lim_{n \to \infty} t_n/n = 1/\lambda, \lambda \in (0, \infty) \), the AoI density for \( x \geq 0 \) is calculated as follows:
    \begin{align}
        &A(x) = \lim_{T \to \infty} \frac{1}{T} \int_0^T \mathbf{1}_{A_t \leq x} \, dt 
             = \lim_{T\rightarrow \infty}\frac{1}{T}\sum_{n=0}^{M_T-1}T_n(x) \nonumber \\
        &=\lim_{T\rightarrow \infty}\frac{1}{T}\! \sum_{n=0}^{M_T-1}\!\! \int_0^x\! \textbf{1}_{X_n\leq u}du -\! \int_0^x\!\! \textbf{1}_{\max(X_{n-1},Y_n)+S_n\leq u} du \nonumber \\
        &= \lambda \left( W(x)-P_1(x) \right).
        \label{eq20}
    \end{align}
    where \(S_n\) denotes the service time of the \(n\)-th packet, \( W(x) \) is the density of the sojourn time distribution, and \( P_1(x) \) is~the density of the PAoI
    %where \(S_n\) denotes the service time of the \(n\)-th packet, \( W(x) \) is the density of the sojourn time distribution, and \( P_1(x) \) is~the density of the PAoI. 
    Applying LST to~\eqref{eq20} yields \eqref{eq18}, which completes the proof.
\end{proof}
Substituting~\eqref{eq18} into~\eqref{eq10} results in the AAoI at node \(i\) for the general case of unreliable M/G/1 queues in tandem.










