	\node[fill=gray, circle, draw=blue, scale=1] (0) {$0$};
	\node[fill=gray, circle, draw=blue, scale=1, right of = 0, xshift= 2cm] (1) {$1$};
    \node[fill=gray, circle, draw=blue, scale=1, right of = 1, xshift= 2cm] (2) {$2$};
	\draw
		(1) edge[-latex, above]  node{$a$} (0)
        (1) edge[-latex, bend left, above]  node{$b$} (2)
		(2) edge[-latex, bend left, below] node{$b$}(1)
		(0) edge[-latex, loop left, left, in =135, out = -135, distance = 30] node{$a,b$} (0)
