\noindent\textbf{Interpretation of Sources in a Data Integration System $DIS= \langle O,S,M,F \rangle$}.
\noindent Let $S$ be a set of sources $S=\{S_1,S_2,...,S_n\}$ in a data integration system $DIS= \langle O,S,M,F \rangle$. Let $I= \langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. The extension of the sources in $S$ according to $I$, a.k.a. $E(S,I)$, is defined as follows:  
\begin{inparaenum}

\item $E:P^S \times \overline{I} ->  P^{\overline{S}}$, where $\overline{I}$ is a set of interpretation structures of $DIS$; and $\overline{S}$ represents an infinite set of interpretations of source signatures from $S$ according to interpretation structures in $\overline{I}$. 

\item $E(S,I)=\{\sigma_S(S_1),\sigma_S(S_2),...,\sigma_S(S_n)\}$, i.e., $E(S,I)$ returns for each of the source signature $S_i$ in $S$, a set that corresponds to the interpretation of $S_i$ in $I$.
\end{inparaenum}
\\


\noindent\textbf{Evaluation of Mapping Assertions: Interpretation of \emph{term}s in mapping assertions}. Let $I= \langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. Let $t$ be a term in mapping assertion $m$ in $M$. Let $\mu(\overline{X})$ be an assignment of the variables in $t$. The evaluation of the term $t$ in $\mu(\overline{X})$ according to $I$,  a.k.a. $eval(t,\mu(\overline{X}))$, is defined inductively as follows:
\textbf{Base case:} a. The term $t$ is a constant, $eval(t,\mu(\overline{X})= \sigma_c(t)$ b. The term $t$ is a variable and $\mu(\overline{X})|t$ is the value of $t$ in $\mu(\overline{X})$, $eval(t,\mu(\overline{X})=\sigma_c(\mu(\overline{X})|t)$. 
\textbf{Inductive case:}
c. If $h$ is an n-ary function and $t_1, t_2,..., t_n$ are terms, and $t=h(t_1,t_2,...,t_n)$. Then, 
$eval(h(t_1,t_2,...,t_n),\mu(\overline{X})= \sigma_F(eval(t_1,\mu(\overline{X}), eval(t_2,\mu(\overline{X}),...,eval(t_n,\mu(\overline{X}))$
\\
\\
\noindent\textbf{Interpretation of a Concept Mapping Assertion}. \\
\noindent Let $S(\overline{X}):-C(f(t))$ be a concept mapping assertion in $M$, where $S(\overline{X})$ represents the conjunction of source signatures $S_1(\overline{X_1}),...,S_k(\overline{X_k})$, and $\overline{X}$ corresponds to the set of all the variables in the mapping assertion $m$, i.e., $\overline{X}$ is the union of $\overline{X_1},...,\overline{X_k}$. Let $I= \langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. Let $\mu(\overline{X})$ be an assignment of the variables in $\overline{X}$ to values in $D$, such that, each $S_i(\mu(\overline{X_i}))$ belongs to $\sigma_S(S_i)$ and the interpretation of $f(t)$ in $\mu(\overline{X})$, a.k.a. $eval(f(t),\mu(\overline{X}))$ belongs to $\sigma_F(f)$. Then, $eval(m,\mu(\overline{X}))=C(eval(f(t),\mu(\overline{X})))$. To simplify the perception, we illustrate the interpretation of a concept mapping assertion with an example shown in \autoref{fig:interpretation} in \textcolor[rgb]{0.98,0.89,0.003}{\textbf{yellow}}. As it is shown in \autoref{fig:interpretation}, given a concept mapping assertion as the $m$, the interpretation of $m$ given \verb|Att1|, i.e., $eval(m,\mu (Att1))$, provides an RDF triple representing an instance of the class \verb|C1| in $O$ with the value $f(Att1)$.     
\\
\\
\noindent\textbf{Interpretation of a Single-Role Mapping Assertion}.\\
\noindent Let $S(\overline{X}):-P(f_1(t_1),f_2(t_2))$ be a single-role mapping assertion in $M$, where $S(\overline{X})$ represents the conjunction of source signatures $S_{1}(\overline{X}_{1}), …,S_{k}(\overline{X}_{k})$, and $\overline{X}$ corresponds to the set of all the variables in the mapping assertion $m$, i.e., $\overline{X}$ is the union of $\overline{X}_{1},...,\overline{X}_{k}$. Let $I=\langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. Let $\mu(\overline{X})$ be an assignment of the variables in $\overline{X}$ the values in $D$, such that, each $S_{i}(\mu(\overline{X}_{i}))$ belongs to $\sigma_S(S_{})$ (for all $i$ in \{1,...,k\}) and the interpretation of $f_1(t_1)$ and $f_2(t_2)$ in $\mu(\overline{X})$, a.k.a. $eval(f_1(t_1),\mu(\overline{X}))$ and $eval(f_2(t_2),\mu(\overline{X}))$ belong to $\sigma_F(f)$. Then, $eval(m,\mu(\overline{X}))=
P(eval(f_1(t_1),\mu(\overline{X})),eval(f_2(t2),\mu(\overline{X})))$. In \autoref{fig:interpretation}, we demonstrate an example of the interpretation of a single-role mapping assertion given as $m$ in \textcolor[rgb]{0.30,0.34,0.56}{\textbf{purple}}. As it can be observed, the interpretation of $m$ given \verb|Att1| and \verb|Att2| of the same data source \verb|S1|, i.e., $eval(m,\mu(Att1,Att2))$, generates RDF triples representing the relation between the values of $f1(Att1)$ and $f2(Att2)$ defined by the predicate \verb|P1| of $O$.\\
\\
\noindent\textbf{Interpretation of a Referenced-Source Mapping Assertion}. \\
\noindent Let $S(\overline{X}_{1}), S^{MR}(\overline{X}_{2}):-P(f_1(t_1),f_2(t_2))$ be a reference-role mapping assertion in $M$ and
$MR$ is the referenced concept mapping assertion $S(\overline{X}_{2}):- C(f(t))$. The predicates $S(\overline{X}_{1})$ and $S^{MR}(\overline{X}_{2})$ represent the conjunction of source signatures $S_1(\overline{X}_{1,1}),...,S_k(\overline{X}_{1,k})$ and $S^{MR}_{1}(\overline{X}_{2,1}),...,S_k(\overline{X}_{k,2})$, respectively. Let $\overline{X}$ be the union of the variables in $\overline{X}_{1}$ and $\overline{X}_{2}$. Let $I= \langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. Let $\mu(\overline{X})$ be an assignment of the variables in $\overline{X}$ in $D$, such that, each $S_i(\mu(\overline{X}))$ belongs to $\sigma_S(S_i)$, and the interpretation of $f_1(t_1)$ and $f_2(t_2)$ in $\mu(\overline{X})$, a.k.a. $eval(f_j(t_j),\mu(\overline{X})$ belongs to $\sigma_F(f)$. Then, $eval(m,\mu(\overline{X}))=
P(eval(f_1(t_1),\mu(\overline{X})),eval(f_2(t2),\mu(\overline{X})))$. To clarify, an example of the interpretation of $m$ as a referenced-source mapping assertion is provided in \autoref{fig:interpretation} in \textcolor[rgb]{0.75,0.78,0.93}{\textbf{violet}}. The interpretation of $m$ given \verb|Attr1| and \verb|Attr3| of the same source \verb|S1|, generates RDF triples representing the relation between instances of two classes in $O$, i.e., \verb|C1| and \verb|C2| with the values in \verb|Attr1| and \verb|Attr3| respectively, considering the predicate \verb|P2| in $O$.\\
\\
\noindent\textbf{Interpretation of a Multi-Sources Role Mapping Assertion}.\\
\noindent Let $S(\overline{X}_{1}), S^{MJ}(\overline{X}_{2}):-P(f_1(t_1),f_2(t_2))$ be a reference-role mapping assertion in $M$ and
$MJ$ is the referenced concept mapping assertion $S^{MJ}(\overline{X}_{2}):- C_z(f(t))$. The predicates $S(\overline{X}_{1})$ and $S^{MJ}(\overline{X}_{2})$ represent the conjunction of source signatures $S_1(\overline{X}_{1,1}),...,S_k(\overline{X}_{1,k})$ and $S^{MJ}_{1}(\overline{X}_{2,1}),...,S_t(\overline{X}_{t,2})$, respectively. Let $\overline{X}$ be the union of the variables in $\overline{X}_{1}$ and $\overline{X}_{2}$. Let $I= \langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. Let $\mu(\overline{X})$ be an assignment of the variables in $\overline{X}$ in $D$, such that, each $S_i(\mu(\overline{X}))$ belongs to $\sigma_S(S_i)$, each a $S^{MJ}_{j}(\mu(\overline{X}))$ belongs to $\sigma_S(S^{MJ}_{j})$, and the interpretation of $f_1(t_1)$ and $f_2(t_2)$ in $\mu(\overline{X})$, a.k.a. $eval(f_j(t_j),\mu(\overline{X})$ belongs to $\sigma_F(f)$. Then, $eval(m,\mu(\overline{X}))=
P(eval(f_1(t_1),\mu(\overline{X}),$ $eval(f_2(t2),\mu(\overline{X})))$. An example of the interpretation of $m$ as a multi-sources role mapping assertion can be observed in \autoref{fig:interpretation} in \textcolor[rgb]{0.23,0.63,0.18}{\textbf{dark green}}. Similar to the interpretation of referenced-role mapping assertion, the interpretation of multi-sources role mapping assertion produce RDF triples representing the relation between instances of two classes in the $O$, i.e., \verb|C1|and \verb|C3|, using a predicate in the $O$, i.e., \verb|P3| in this example. What differentiate the two interpretations are the data sources which contribute in the creation of the instances of \verb|C1| and \verb|C3|. As it can be seen in \autoref{fig:interpretation}, \verb|Attr1| in the data source \verb|S1| provides the instantiation of the class \verb|C1|. However, the instances of the class \verb|C3| are provided by the values of \verb|Attr6| in the other data source, i.e., \verb|S2|. \\
\\
\noindent\textbf{Interpretation of an Attribute Mapping Assertion}.\\
\noindent Let $S(\overline{X}):-A(f_1(t_1),f_2(t_2))$ be an attribute mapping assertion in $M$, where $S(\overline{X})$ represents the conjunction of source signatures $S_{1}(\overline{X}_{1}), …,S_{k}(\overline{X}_{k})$, and $\overline{X}$ corresponds to the set of all the variables in the mapping assertion $m$, i.e., $\overline{X}$ is the union of $\overline{X}_{1},...,\overline{X}_{k}$. Let $I=\langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. Let $\mu(\overline{X})$ be an assignment of the variables in $\overline{X}$ the values in $D$, such that, each $S_{i}(\mu(\overline{X}_{i}))$ belongs to $\sigma_S(S_{})$ (for all $i$ in \{1,...,k \}) and the interpretation of $f_(t_1)$, a.k.a. $eval(f_1(t_1),\mu(\overline{X}))$, belongs to $\sigma_F(f)$ and the interpretation of $t_2$ in $\mu(\overline{X})$, a.k.a. $eval(t_2,\mu(\overline{X}))$, is true in $I$. Then, $eval(m,\mu(\overline{X}))=
P(eval(f_1(t_1),\mu(\overline{X})),eval(t2,\mu(\overline{X})))$. The RDF triples generated by the interpretation of attribute mapping assertions represent the relation between instances of a class in $O$ and a literal value extracted from an attribute in the same data source using a predicate in the $O$. In \autoref{fig:interpretation} an example of the interpretation of an attribute mapping assertion is provided in \textcolor[rgb]{0.18,0.95,0}{\textbf{green}}. It shows the relation between the instances of the class \verb|C3| and literal values extracted from the \verb|Att8| in \verb|S2| using the predicate \verb|P4|.\\
\\
\noindent 
\noindent\textbf{Evaluation of a Data Integration System in an Interpretation Structure.}
Let $DIS= \langle O,S,M,F \rangle$ be a data integration system. Let $I= \langle D,\sigma_c,\sigma_S,\sigma_F \rangle$ be an interpretation structure for $DIS$. The evaluation of $DIS$ in $I$, a.k.a. $evaluation(DIS,I)$, corresponds to the union of $eval(m,\mu(\overline{X}))$ for all the mapping assertions in $M$ and all the assignments $\mu(\overline{X})$ in $D$ of the variables $\overline{X}$ in $m$. The evaluation of $DIS$ in $I$, $evaluation(DIS,I)$ denotes the instances of knowledge graph $KG=(O,V,E)$. 

