\noindent\textbf{Source-based Projection.} The most generic transformation that Dragoman performs before executing the functions on any mapping assertion provided in $M$ is the projection of the attributes in sources of $S$ referred to by the mapping assertion in $M$. For each mapping assertion in $M$, independent of the type, Dragoman projects all the attributes needed by that mapping assertion into a new data source and removes the duplicated values. It should be noted that if a function in $F$ is referred to by a mapping assertion, then the attributes required are also projected into the new data source. In other words, this transformation pushes down the projection of required attributes and the duplicated values removal~\cite{jozashoori2019mapsdi}. Accordingly, the mapping assertion is transformed to use the new projected data source instead of the original one. To better understand, Figure \ref{fig:t1} shows an example of this transformation. As it can be seen in Figure \ref{fig:t1}, from the source $S1$ only two attributes $Att2$ and $Att5$ are utilized in the mapping assertions; $Att2$ as the value for \verb|rr:subjectMap| or the concept mapping assertion, and $Att5$ as the value of the \verb|rr:objectMap| or the single-role mapping assertion. Therefore, the transformed DIS (shown at the bottom of Figure \ref{fig:t1}) is comprised of the newly generated data source, including only $Att2$ and $Att5$, and the transformed mapping assertion which applies the later data source as the \verb|rr:logicalSource|. 

\noindent\textbf{Concept-based Transformation.} When the output of user-defined functions (\verb|fnml:FunctionTermMap|) is applied as the value of a concept mapping assertion or \verb|rr:subjectMap|, the concept-based transformation is performed on the given mapping assertions in $M$ and sources in $S$. Figure \ref{fig:t2} shows an example where the transformation of sources in $S$ is performed by joining the data sources consisting of the function's output, i.e., ``intermediate result'', and the outcome of the source-based projection on $S$. After the generation of the new data source, Dragoman, transforms the mapping assertion so that the old data source is replaced with the newly generated one, as shown at the bottom of Figure \ref{fig:t2}. Algorithm\ref{alg:algo_concept} provides a sketch of the concept-based Transformation rule and how to implement it. 

\begin{algorithm}[H]
\centering
\caption{Concept-based Transformation Algorithm}
\label{alg:algo_concept}
\begin{multicols}{2}
\begin{algorithmic}[1]
\Require $ma,\overline{TS}$
\Ensure $Concept\_Transformation(ma,\overline{TS})$
\State $NEW\_\overline{Tma}\gets\{ma\}$
\State $OLD\_\overline{Tma}\gets NEW\_\overline{Tma}$
\State suppose $ma: S(\overline{X}):-C(f(g(\overline{T})))$ 
\State where $g$ is a \emph{term} that is a user-defined 
\State function and receives $\overline{T}$, a set of \emph{term}s,
\State as arguments: $\overline{T}:\{t_1,...,t_m\}$, $\overline{Rma}$
\State is a set of $Rma_i$ defined as: 
\State $S_i(\overline{X}_{i,1}):-P(ma,f_2(t_2))$, $\overline{Ama}$
\State is a set of $Ama_i$ defined as:
\State $S_i(\overline{X}_{i,1}):-P(ma,t_2)$
\If {$g(.)=a(b(.))$}
\State $S_g(\overline{X}_g,b(\overline{T}))$ is defined for all \State the values of $b(\overline{T})$ such that
\State $eval(S_g(\overline{X}_g,b(\overline{T})))=True$
\State $ma':$
\State $S(\overline{X}),S_g(\overline{X}_g,b(\overline{T})):-C(f(t'))$
\State where $t'$ is a \emph{term}: $t' \in S_g$
\For{each $Rma:$ in $\overline{Rma}$}
\State $Rma':S_i(\overline{X}_{i,1}),$
\State $S_g(\overline{X}_g,b(\overline{T}):-P(ma',f_2(t_2))$
\State $\overline{Rma'}\gets \overline{Rma'}\cup Rma'$
\EndFor
\For{each $Ama:$ in $\overline{Ama}$}
\State $Ama':S_i(\overline{X}_{i,1}),$
\State $S_g(\overline{X}_g,b(\overline{T}):-P(ma',t_2)$
\State $\overline{Ama'}\gets \overline{Ama'}\cup Ama'$
\EndFor
\Else
\State $S_g(\overline{X}_g,\overline{T})$ is defined for all the
\State values of $t_i \in \overline{T}, 0<t_i<m+1$ 
\State such that $eval(S_g(\overline{X}_g,\overline{T}))=True$
\State $ma':$
\State $S(\overline{X}),S_g(\overline{X}_g,\overline{T}):-C(f(t'))$
\State where $t'$ is a \emph{term}: $t' \in S_g$
\For{each $Rma:$ in $\overline{Rma}$}
\State $Rma':S_i(\overline{X}_{i,1}),$
\State $S_g(\overline{X}_g,\overline{T}):-P(ma',f_2(t_2))$
\State $\overline{Rma'}\gets \overline{Rma'}\cup Rma'$
\EndFor
\For{each $Ama:$ in $\overline{Ama}$}
\State $Ama':\ S_i(\overline{X}_{i,1}),$
\State $S_g(\overline{X}_g,\overline{T}):-P(ma',t_2)$
\State $\overline{Ama'}\gets \overline{Ama'}\cup Ama'$
\EndFor
\EndIf
\State $NEW\_\overline{Tma}\gets \{ma'\}\cup{\overline{Rma}}\cup{\overline{Ama}}$
\State $\overline{TS}\gets\overline{TS}\cup{S_g}$\\
\Return $NEW\_\overline{Tma},\overline{TS}$
\end{algorithmic}
\end{multicols}
\end{algorithm}



