\noindent\textbf{Role-based Transformation.} Contrary to the previous transformation, role-based transformation is performed once the output of functions (\verb|fnml:Function|-\verb|TermMap|) are utilized to build the value of a role mapping assertion (\verb|rr:objectMap|). In contrast to concept-based transformation, role-based transformation forces the join between the data sources consisting of the output of the function and the outcome of the source-based projection, to the mapping assertions. In other words, the output of the function evaluation is stored in a separate new data source and the newly generated  data source by the source-based projection. Consequently, the role mapping assertion is transformed to multi-sources role mapping assertions to replace the old data source with two data sources, i.e., the data source, including the output of the functions and the data source generated as the result of the source-based projection. Figure \autoref{fig:t3} illustrates an example of role-based transformation. As shown in the right-hand side of the figure \autoref{fig:t3}, the transformed data sources include two newly generated data sources, and the role mapping assertion is transformed to a multi-sources mapping assertion, applying \verb|joinCondition|. An outline of the implementation of the role-based transformation rule is provided in Algorithm\ref{alg:alg_role}.





\begin{algorithm}[H]
\centering
\caption{Role-based Transformation Algorithm}
\label{alg:alg_role}
\begin{multicols}{2}
\begin{algorithmic}[1]
\Require $ma,\overline{TS}$
\Ensure $Role\_Transformation(ma,\overline{TS})$
\State $NEW\_\overline{Tma}\gets\{ma\}$
\State $OLD\_\overline{Tma}\gets NEW\_\overline{Tma}$
\State Suppose $ma:$
\State $S_i(\overline{X}_{i,1}):-P(f_1(t_1),f_2(g(\overline{T}_2)))$
\State where $g$ is a \emph{term} that is a user-defined 
\State function and receives $\overline{T}_2$, a set of \emph{term}s
\State as arguments: $\overline{T}_2:\{t_{2,1},...,t_{2,m}\}$
\If {$g(.)=a(b(.))$}
\State $S_g(\overline{X}_g,b(\overline{T}_2))$ is defined for all the values of 
\State $b(\overline{T}_2)$ such that $eval(S_g(\overline{X}_g,b(\overline{T}_2)))=True$
\State $ma':S_i(\overline{X}_{i,1}),S^{Cma'}_g(\overline{X}_g,b(\overline{T}_2)),\theta_g(\overline{X}_i,1,\overline{X}_g)$
\State $:-P(f_1(t_1),f_2(t'_2))$ where $t'_2$ is a term: $t' \in S_g$
\State $Cma':\ S_g(\overline{X}_g,b(\overline{T}_2)):-C'(f_2(t'_2))$
\Else
\State $S_g(\overline{X}_g,\overline{T}_2)$ is defined for all the values of $\overline{T}_2$ 
\State such that $eval(S_g(\overline{X}_g,\overline{T}_2))=True$
\State $ma': S_i(\overline{X}_{i,1}),S^{Cma'}_g(\overline{X}_g,\overline{T}_2),$ $\theta_g(\overline{X}_i,1,\overline{X}_g)$
\State $:-P(f_1(t_1),f_2(t'_2))$ where $t'_2$ is a term: $t' \in S_g$
\State $Cma':\ S_g(\overline{X}_g,\overline{T}_2):-C'(f_2(t'_2))$
\EndIf
\State $NEW\_\overline{Tma}\gets \{ma',Cma'\}$
\State $\overline{TS}\gets \overline{TS} \cup \{S_g\}$ \\
\Return $NEW\_\overline{Tma},\overline{TS}$
\end{algorithmic}
\end{multicols}
\end{algorithm}

\noindent\textbf{Attribute-based Transformation.} This transformation is required when the output of the user-defined function is used as the \emph{term} value of an Attribute mapping assertion. Similar to the concept-based transformation, data sources are transformed by joining the data sources consisting of the output of the function and the result of the source-based projection on $S$. Consequently, the mapping assertion is transformed to include the newly generated joined data source as the replacement for the original data source. As it can be observed in the example shown in figure \autoref{fig:t4} using the output of user-defined functions - \verb|fnml:FunctionTermMap|- as the \emph{term} value of both role and attribute mapping assertions are very similar in [R2]RML.; they are differentiated by the values \verb|rr:IRI| and \verb|rr:Literal| for \verb|termType| in case of role and attribute mapping assertions, respectively. The attribute-based transformation rule can be implemented following Algorithm\ref{alg:algo_att}. 

\begin{algorithm}[H]
\centering
\caption{Attribute-based Transformation Algorithm}
\label{alg:algo_att}
\begin{multicols}{2}
\begin{algorithmic}[1]
\Require $ma,\overline{TS}$
\Ensure $Attribute\_Transformation(ma,\overline{TS})$
\State $NEW\_\overline{Tma}\gets\{ma\}$
\State $OLD\_\overline{Tma}\gets NEW\_\overline{Tma}$
\State Suppose $ma: S_1(\overline{X}_{i,1}):-A(f(t_1),g(\overline{T}_2))$ and $Cma: S_1(\overline{X}_{1,1}):-C(F_1(t_1))$ where $g(.)$ is a term that is a user-defined function and receives $\overline{T}_2$, a set of \emph{term}s as arguments: $\overline{T}_2:\{t_{2,1},...,t_{2,m}\}$
\If {$g(.)=a(b(.))$}
\State $S_g(\overline{X}_g,\overline{T}_2)$ is defined for all the values of $b(\overline{T}_2)$ 
\State such that $eval(S_g(\overline{X}_g,b(\overline{T}_2)))=True$
\State $ma': S_1(\overline{X}_{i,1}),S_g(\overline{X}_g,\overline{T}_2):-A(f(t_1),t'_2)$ 
\State where $t'_2$ is a \emph{term}: $t'_2 \in S_g$
\State $Cma': S_1(\overline{X}_{1,1}),S_g(\overline{X}_g,b(\overline{T}_2)):-C(f(t_1))$
\Else
\State $S_g(\overline{X}_g,\overline{T}_2)$ is defined for all the values of $\overline{T}_2$ 
\State such that $eval(S_g(\overline{X}_g,b(\overline{T}_2)))=True$
\State $ma': S_1(\overline{X}_{i,1}),S_g(\overline{X}_g,b(\overline{T}_2)):-A(f(t_1),t'_2)$ 
\State where $t'_2$ is a \emph{term}: $t'_2 \in S_g$
\State $Cma': S_1(\overline{X}_{1,1}),S_g(\overline{X}_g,\overline{T}_2):-C(f(t_1))$
\EndIf
\State $NEW\_\overline{Tma}\gets \{ma',Cma'\}$
\State $\overline{TS}\gets \overline{TS} \cup \{S_g\}$\\
\Return $NEW\_\overline{Tma},\overline{TS}$
\end{algorithmic}
\end{multicols}
\end{algorithm}

\noindent\textbf{Composite-Function-based Transformation.} When the user-defined function is a composite function, i.e, the output of a \verb|fnml:FunctionTermMap| is an argument to another \verb|fnml:FunctionTermMap|, the same transformation is performed independent of the type of the mapping assertion that refers to the output of the function. composite-function-based transformation is similar to the concept-based transformation; data sources are transformed by joining the data source generated by the output of all functions involved in the composite function, and the data source result from the source-based projection. Accordingly, Dragoman starts executing the composite function from the inner function, i.e., the simple function. As illustrated in the example shown at the bottom of the Figure\ref{fig:t5}, after evaluating the inner function \verb|FunctionMap2|, the materialized join between the output and the input attributes of the inner function is provided. This join data source is given to the outer function \verb|FunctionMap1| as the input. After evaluating the outer function, the composite-function-based transformation is performed along with the source-based projection.

