\begin{lemma}[Telescoping Sampling~\cite{DBLP:conf/approx/Monemizadeh23}]\label{lem:telescoping}
    We can select a point of $P$ uniformly at random
    using $O(\log\Delta)$ range counting queries.
\end{lemma}

