\begin{restatable}{lemma}{cellsamplinglb}\label{lem:cell sampling lowerbound}
    Any algorithm that can perform $c$-approximate uniform sampling for non-empty cells requires $\Omega(\sqrt n/c)$ range counting queries for any parameter $c\geq 1$. %\eunjin{$\Omega(\sqrt n/c)$}
\end{restatable}
\begin{proof}
    Assume that we have a $c$-approximate uniform sampling algorithm $\mathcal A$.
    That is, the probability that each non-empty cell is chosen is in $[1/(cm), c/m]$, where $m$ is the number of non-empty cells. Consider the uniform instance $I$ and any non-uniform instance $I'$.
    Recall that the number of non-empty cells in $I$ is $\sqrt n/(4c)$, and the number of non-empty cells in $I'$ is at least $2c\sqrt n$. 
    Therefore, $\mathcal A$ must distinguish the two cases with probability at least $1/2$. 
    However, by Lemma~\ref{lem:sampling:distinguish},
    no such algorithm exists, which gives a contradiction. 
\end{proof}


