	\begin{bcolfr}[Theorems: Properties of atomic concurrency]
		\begin{sdef}{0.8}{atomiccommute}{Atomic\_commute}
			\hspace{2em}\bl{p $|||$ q} = \bl{q $|||$ p}
			\\ \hspace*{5em} -{}- Atomic concurrency is commutative.
