		% \begin{sdef}{0.8}{concsequence2}{Conc\_sequence2}
		%     \hspace{2em}\bl{p $|||$ (q; r$)$} $\subseteq$ \bl{q; (p $|||$ r$)$}
		% \end{sdef}
		% \begin{sdef}{0.8}{concsequence3}{Conc\_sequence3}
