\textbf{Algorithm for Tree Reduction:} The tree reduction algorithm employs a binary tree structure. Each core is assigned a subset of GEMMs, and the results are progressively aggregated using GEADD operations. Memory is allocated for intermediate results during tree reduction, and the final result is computed by combining all intermediate results hierarchically, see an illustration in Figure \ref{PA1SA2}. The details are outlined in Algorithm \ref{alg:tree_reduction}.

\begin{algorithm}
\caption{Tree Reduction for Parallel Cholesky Factorization}
\label{alg:tree_reduction}
\begin{algorithmic}
\State \textbf{Input:} Tiled matrix $A$, thread count: $num\_of\_cores$, GEMM index range $\{start\_range, end\_range\}$
\State \textbf{Output:} Reduced result $T_{final}$

\State Initialize an array of tiles, \texttt{T[ID]} for partial results, one per core
\State Initialize \texttt{core\_progress[ID]} $\gets 0$ for all threads
\For{\texttt{each thread ID} $= 0$ \textbf{to} \texttt{num\_of\_cores - 1}} \Comment{Parallel region}
    \For{\texttt{each GEMM with indices $\{k, m, n\}$}}
        \State \texttt{i $\gets$ determine\_mapping\_index($k, m, n$)}
        \If{\texttt{start\_range[ID]} $\leq$ \texttt{i} $<$ \texttt{end\_range[ID]}}
            \State Perform GEMM for assigned range:
            \State $T_\texttt{ID} \gets T_\texttt{ID} + $ \texttt{DGEMM($A_{kk}, A_{mk}$)} 
        \EndIf
    \EndFor
    \State \texttt{core\_progress[ID]} $\gets$ \texttt{1} \Comment{Mark thread completion}
\EndFor
\State \textbf{Synchronize all threads}
\State Perform hierarchical reduction of \texttt{T[ID]} using GEADD to compute $T_{final}$
\end{algorithmic}
\end{algorithm}


