        \begin{itemize}
            \item {A. Very Accurate}
            \item {B. Moderately Accurate}
            \item {C. Neither Accurate Nor Inaccurate}
            \item {D. Moderately Inaccurate}
            \item {E. Very Inaccurate}
        \end{itemize}

        Only answer using the letter of the option. Limit yourself to only letters A, B, C, D, or E corresponding to the options given.
    \end{tcolorbox}
