Every transition path from a nonterminal configuration $C_0, \sigma_0$ to a terminal configuration  has the form 
\begin{equation}
\label{eqn:terminal-path}
C_0,\sigma_0 \lTrans{L_0} C_1,\sigma_1  \lTrans{L_1}  \cdots\ C_{n-1},\sigma_{n-1} \lTrans{L_{n-1}} \tau \, ,
\end{equation}
for some $n \geq 1$, where each label $L_i$ is either empty or of the form $\pAssgn{n_i}{d_i}$. We call such 
paths \emph{terminal paths}.  The  \emph{probability} and the \emph{final state} of a terminal path $\pi$, of the form~\eqref{eqn:terminal-path}, are defined by
\begin{align}
\label{prob-pi}
\Prob(\pi) ~ := ~  & \prod_{i < n}  \begin{cases} d_i(n_i) & \text{if $L_i$ is $\pAssgn{n_i}{d_i}$} \\
1 & \text{if $L_i$ is empty\, ,}
\end{cases}
\\
\nonumber
\Final(\pi) ~ := ~  & \tau \, .
\end{align}
We write $\TP_{C, \sigma}$ for the set of all terminal paths from initial configuration $C,\sigma$.
%The \emph{final state} of 
The \emph{termination probability} for $C, \sigma$ is defined by
\[
\Prob[\text{$C,\sigma$ terminates}] ~ := ~ \sum_{\pi \, \in\, \TP_{C,\sigma}} \Prob(\pi)\, .
\]
We say that $C,\sigma$ is \emph{terminating} if $\Prob[\text{$C,\sigma$ terminates}] = 1$. This is the form of termination known as almost sure termination. We shall not concern ourselves with other forms of termination. A terminating configuration $C,\sigma$ determines a probability distribution on result states 
$p_{C,\Sigma} : \State \to [0,1]$, defined by:
\begin{equation}
\label{terminal-dist}
p_{C,\Sigma} (\tau) ~ := ~ \sum_{\pi \, \in\, \TP_{C,\sigma}} \Prob(\pi) \cdot \delta_{\tau,\, \Final(\pi)} \enspace ,
\end{equation}
where $\delta$ is the Kr\"onecker delta.

We consider \emph{divergence} to be the computational behaviour that follows an infinite path  of nonterminal configurations 
\begin{equation}
\label{eqn:infinite-path}
C_0,\sigma_0 \lTrans{L_0} C_1,\sigma_1  \lTrans{L_1}  \ C_{1},\sigma_{1} \lTrans{L_2} \cdots .
\end{equation}
We write $\IP_{C_0, \sigma_0}$ for the set of all such infinite paths from initial configuration $C_0,\sigma_0$.
We write $\RPath{\IP_{C_0, \sigma_0}}{n}$ for the set of $n$-length prefixes of paths in $\IP_{C_0, \sigma_0}$,
where the length is the number of transitions.
The \emph{divergence probability} for $C_0, \sigma_0$ is defined by
\begin{equation}
\label{eqn:divergence-prob}
\Prob[\text{$C_0,\sigma_0$ diverges}] ~ := ~ 
\lim_{n \to \infty} \sum_{\gamma\, \in \,\RPath{\IP_{C_0, \sigma_0}}{n}} \Prob(\gamma) \, ,
\end{equation}
where $\Prob(\gamma)$ is calculated analogously to~\eqref{prob-pi} above.
It is always the case that
\begin{equation}
\label{terminate-inequality}
\Prob[\text{$C_0,\sigma_0$ terminates}] + \Prob[\text{$C_0,\sigma_0$ diverges}] ~ \leq ~ 1 \, .
\end{equation}
The inequality is an equality precisely in the case that the configuration $C_0,\sigma_0$ is 
\emph{fault-free}, meaning that  it is 
not the case that $C,\sigma \dTrans^* \Fail$, where 
we write $\dTrans^*$ for the transitive-reflexive closure of the single-step transition relation, including both labelled and unlabelled transitions in the relation. Note that terminating configurations are \emph{a fortiori} fault-free.

%If a configuration is terminating then its execution cannot result in a fault.
% If $C_0,\sigma_0$ is fault free, then 

\section{Assertions}
\label{section:assertions}

%We aim to justify a simple probabilistic frame rule in a general setting. Accordingly, 
Rather than focusing on a specific  assertion logic, we work with a general semantic notion of assertion. To motivate this, we
give some examples of assertions that fit into the framework. A first example is
\[
X \sim d \, ,
\]
where $d$ is some probability distribution on $\Int$. This says that the value of the program variable $X$ is distributed probabilistically according to $d$. Another simple example is
\[
[X = Y] \, .
\]
Since the values of variables are in general randomly distributed, we interpret the above equality as stating that $X$ and $Y$ take the same value with probability $1$; that is, considered as random variables, $X$ and $Y$ are {almost surely equal}. 


In order to accommodate randomness in the semantics of assertions, 
our main satisfaction relation will have the form $\Sigma \models \Phi$, relating random states $\Sigma$ and 
semantic assertions $\Phi$. However, we add one further ingredient to the picture. 
We allow the truth value of the `relation' 
$\Sigma \models \Phi$ to be undefined for certain ineligible random states $\Sigma$. This possibility of undefinedness is included as  a natural mathematical
mechanism  for  dealing with the partiality of state. For example, we consider $\Sigma \models [X = Y]$ to be defined if and only if the random state $\Sigma$ assigns values to both $X$ and $Y$ with probability one; that is,
if $\Sigma$ is $\{X,Y\}$-total.
% ~\eqref{eqn:XeqY-defined} holds for $V := \{X,Y\}$. 
We write $(\Sigma \models \Phi)\Defined$ to mean that the value of the satisfaction relation 
$\Sigma \models \Phi$ is defined, in which case we either have
$(\Sigma \models \Phi) = \True$ or $(\Sigma \models \Phi) = \False$.
Again, in the case that $\Phi$ is the assertion $[X = Y]$, we have %, because of~\eqref{eqn:XeqY-defined}, 
 that 
$(\Sigma \models [X=Y])\Defined$ if and only  if
$\PState{\Sigma}{X}, \PState{\Sigma}{Y} : \Omega \to \Int$, as in~\eqref{eqn:Sigma-X}, are well-defined. 
Then $(\Sigma \models [X=Y]) = \True$ if and only if $\Prob[\Sigma_X = \Sigma_Y] = 1$, or equivalently,
because there are no zero-probability sample-space elements, 
if the functions $\PState{\Sigma}{X}$ and $\PState{\Sigma}{Y}$ are equal. Similarly, $(\Sigma \models [X=Y]) = \False$ if and only if $\Prob[\PState{\Sigma}{X} = \PState{\Sigma}{Y}] < 1$, or equivalently 
$\PState{\Sigma}{X} \neq \PState{\Sigma}{Y}$. This and many other similar examples illustrate that allowing undefinedness enables us to make a natural distinction between the property expressed by $\Phi$ not making sense in the context of $\Sigma$, in which case $\Sigma \models \Phi$ is undefined,
and the case in which the property does make sense, in which case  $\Sigma \models \Phi$
possesses an actual truth value. 

We now precisely define our semantic notion of  assertion. A \emph{semantic assertion} $\Phi$ is given by a \emph{partial} function from random states to the set of truth values  $\{\True,\False\}$.
We write this function as 
\[ \Sigma ~ \mapsto ~ (\Sigma \models \Phi) \, . \]
The function is required to satisfy three conditions. 
%Semantically, an assertion $\Phi$ is given by a set of 
\begin{description}
\item[(SA1)]
$\Sigma \sqleq \Sigma'$ and  $(\Sigma \models \Phi)\Defined$ implies 
$(\Sigma \models \Phi) = (\Sigma' \models \Phi)$.
(The $\sqleq$ relation is defined in~\eqref{eqn:random-state-order}.)

%\item
%If $(\Sigma \models \Phi) \in \{\True, \False\}$ then the set $\{\Sigma' \mid 
%\text{$\Sigma' \sqleq \Sigma$ and $(\Sigma' \models \Phi) = (\Sigma \models \Phi)$}\}$ has a minimum element under $\sqleq$.

\item[(SA2)] $\Phi$ has an associated finite set $\FV(\Phi) \subseteq \Var$, its \emph{footprint variables},%
\footnote{When assertions are given syntactically as formulas, $\FV(\Phi)$  can be understood as the 
\emph{free variables} of the formula $\Phi$. For semantic assertions, we use the more neutral terminology \emph{footprint variables}, which is motivated by thinking of $\FV(\Phi)$ as the memory footprint associated with $\Phi$.}
satisfying
\[
(\Sigma \models \Phi) \Defined ~~  \iff ~~ 
\text{$\Sigma$ is $\FV(\Phi)$-total.}
\]

\item[(SA3)] If $q : \Omega' \Epi \Omega$ is a morphism of sample spaces then
$(\Sigma \circ q \models \Phi) = (\Sigma \models \Phi)$.

\end{description}
One consequence of (SA2) is that it prevents the everywhere undefined function
$(\Sigma \mapsto \bot)$ from being a semantic assertion, which is no loss. %, as such an assertion would
%not be useful.  
Secondly, (SA2) determines $\FV(\Phi)$ uniquely. Indeed, suppose
we have two finite $U,V \subseteq \Var$ such that
$(\Sigma \models \Phi) \Defined$ iff $\Sigma$ is $U$-total iff $\Sigma$ is $V$-total.
Let $\Sigma$ be some random state such that $(\Sigma \models \Phi) \Defined$. (Such a state exists, by the 
first observation about (SA2) above.) Since $\Sigma$ is $U$-total, so is $\RState{\Sigma}{U}$, and hence
$(\RState{\Sigma}{U} \models \Phi) \Defined$. This means that $\RState{\Sigma}{U}$ is $V$-total, which entails 
$V \subseteq U$.  A symmetric argument establishes $U \subseteq V$. Hence $U = V$. 

In combination, (SA1) and (SA2) have the following simple consequence that we shall use frequently.
\begin{equation}
\label{eqn:SAA-SAB}
(\Sigma \models \Phi) \Defined ~~ \implies ~~
{(\RState{\Sigma}{\FV(\Phi)} \models \Phi)\Defined}~ \text{and}~  (\Sigma \models \Phi) = (\RState{\Sigma}{\FV(\Phi)} \models \Phi) \, .
\end{equation}
We remark also that (SA3) is equivalent to saying that, for any assertion $\Phi$,
the value of $\Sigma \models \Phi$ depends only on the probability distribution $p_\Sigma$. Thus
the logic could perfectly well be given an equivalent formulation in terms of distributions on $\State$ rather than random state, as has been the norm hitherto in the literature on probabilistic separation logic~\cite{BHL,BGHT}.

We give several examples of semantic assertions and constructions on them, to illustrate the broad scope of the notion. 
\begin{itemize}
%\item If $E_1,E_2$ are  integer expressions then the assertion $[E_1=E_2]$ is defined by
%\begin{gather*}
%\FV([E_1=E_2]) ~  := ~ \FV(E_1) \cup \FV(E_2) \\
%\Sigma \models {[E_1=E_2]} ~ \, {:\!\iff} ~ \Prob[\Sem{E_1}_\Sigma = \Sem{E_1}_\Sigma] = 1\, .
%\end{gather*}
%This definition illustrates the general style we shall follow below. The first clause specifies the set of frame variables, which determines when the value of $(\Sigma \models [E_1=E_2])$ is defined. The second clause,
%is then only considered in the case that $(\Sigma \models [E_1=E_2])\Defined$. 
%This second clause makes use of  standard 
% which utilises standard notation for random variables, specifies the truth value under the assumption that $\Sigma \models [E_1=E_2]$ is defined. 

\item If $B$ is a boolean expression then the assertion $[B]$ is defined by
\begin{gather*}
\FV([B]) ~  := ~ \Var(B)  \\
\Sigma \models {[B]} ~ \, {:\!\iff} ~ \Prob[\Sem{B}_\Sigma = \True] = 1\, .
\end{gather*}
This definition illustrates the general style we shall follow below. The first clause specifies the set of footprint variables, which determines when the value of $(\Sigma \models [B])$ is defined. The second clause,
is then only considered in the case that $(\Sigma \models [B])\Defined\,$. 

\item A special case of the above is the assertion $[E_1 = E_2]$, for integer expressions $E_1,E_2$.
% where 
%This second clause makes use of  standard 
% which utilises standard notation for random variables, specifies the truth value under the assumption that $\Sigma \models [E_1=E_2]$ is defined. 


\item If $E$ and $D$ are integer and distribution expressions respectively then the assertion $E \sim D$ is defined by
\begin{gather*}
\FV(E \sim D) ~  := ~ \Var(E) \cup \Var(D) \\
\Sigma \models {E\sim D} ~ \, {:\!\iff} ~ 
\forall d \in \Supp(\Sem{D}_\Sigma), ~ p_{\,{(\Sem{E}_\Sigma)}_{|\Sem{D}_\Sigma = d}} = d \, .
\end{gather*}
Here, the expression $\Sem{D}_\Sigma$ is considered as the distribution-valued random variable $\omega \mapsto \Sem{D}_{\Sigma(\omega)}$, and the
property asserts that the distribution of $E$, conditional on any possible distribution $d$ arising from $D$, is itself $d$.

\item If $E$ is an integer expression then the assertion $\Det(E)$ is defined by
\begin{gather*}
\FV(\Det(E)) ~  := ~ \Var(E) \\
\Sigma \models {\Det(E)} ~ \, {:\!\iff} ~ 
\exists n \in \Int, ~ \Prob[\Sem{E}_\Sigma = n] = 1 \, . 
\end{gather*}
Informally: $E$ is deterministic.

\item If $\Phi$ is a semantic assertion then so is $\neg \Phi$ defined classically by
\begin{gather*}
\FV(\neg \Phi) ~  := ~ \FV(\Phi) \\
\Sigma \models {\neg \Phi} ~ \, {:\!\iff} ~ \Sigma \not \models \Phi
 \, . 
\end{gather*}
We emphasise that the second line only applies in the case that
$(\Sigma \models {\neg \Phi})\Defined$.


\item If $\Phi, \Psi$ are semantic assertions then 
$\Phi \vee \Psi$, $~\Phi \wedge \Psi$ and $\Phi \Imp \Psi$,
are defined in the standard classical way, for example
\begin{gather*}
\FV(\Phi \Imp \Psi) ~  := ~ \FV(\Phi) \cup \FV(\Psi)\\
\Sigma \models {\Phi \Imp \Psi} ~ \, {:\!\iff} ~ \text{$\Sigma \not\models \Phi$ or $\Sigma \models \Psi$,}
 \, . 
\end{gather*}
%with the obvious adaptations to the cases of conjunction and implication.

\item If $E$ is an integer expression and $\Phi$ is a semantic assertion then
so is $\CM{E} \,\Phi$ defined by
\begin{gather*}
\FV(\CM{E}\, \Phi) ~  := ~ \Var(E) \cup \FV(\Phi) \\
\Sigma \models {\CM{E}\, \Phi} ~ \, {:\!\iff} ~ \forall n \in \Supp(\Sem{E}_{\Sigma}), ~ 
\Sigma_{|\Sem{E}_{\Sigma} = n} \models \Phi \, . 
\end{gather*}
Here $\CM{E}$ is essentially the \emph{conditioning modality} introduced in~\cite{LAS}, which we model by conditioning the random state~$\Sigma$, using the conditioning operation on random variables from
Section~\ref{section:preliminaries}.

\item
If $\Phi, \Psi$ are semantic assertions then so is $\Phi * \Psi$ defined by
\begin{gather*}
\FV(\Phi * \Psi) ~  := ~ \FV(\Phi) \cup \FV(\Psi)\\
\Sigma \models \Phi * \Psi ~  {:\! \iff} ~ 
\Sigma \models \Phi\ \text{and}\ \Sigma \models \Psi\ \text{and}\ \RState{\Sigma}{\FV(\Phi)} \Indep \RState{\Sigma}{\FV(\Psi)} \, ,
% \text{there exist finite}\ U,V \subseteq \Var\ \text{s.t.}\ \Sigma_U \models \Phi\ \text{,}\ \Sigma_V \models \Psi\ \text{and}\ \Sigma_U \Indep \Sigma_V
\end{gather*}
%using~\eqref{eqn:Sigma-V} to define $\Sigma_{\FV(\Phi)}$ and $\Sigma_{\FV(\Psi)}$.
\end{itemize}

\noindent
The last assertion above is of course the separating conjunction, which will play a critical role in the frame rule. One might expect the  second clause in its definition to have a different form; for example,
\begin{equation}
\label{star-B}
%\Sigma \models \Phi * \Psi ~  {:\! \iff} ~ 
\RState{\Sigma}{\FV(\Phi)} \models \Phi\ \text{and}\ \RState{\Sigma}{\FV(\Phi)} \models \Psi\ \text{and}\ \RState{\Sigma}{\FV(\Phi)} \Indep \RState{\Sigma}{\FV(\Psi)} \, ;
\end{equation}
but this is equivalent by~\eqref{eqn:SAA-SAB}. 
Another equivalent is given by 
\begin{equation}
\label{star-C}
%\Sigma \models \Phi * \Psi ~  {:\! \iff} ~ 
\exists U, V \subseteq \Var, ~
\RState{\Sigma}{U} \models \Phi\ \text{and}\ \RState{\Sigma}{V} \models \Psi\ \text{and}\ 
\RState{\Sigma}{U} \Indep \RState{\Sigma}{V} \, .
\end{equation}
Indeed, it is immediate that~\eqref{star-B} implies~\eqref{star-C}.
For the converse, suppose we have $U,V$ as in~\eqref{star-C}.
Since $\RState{\Sigma}{U} \models \Phi$ and $\RState{\Sigma}{V} \models \Psi$, we have,
by (SA2), that $\FV(\Phi) \subseteq U$ and $\FV(\Psi) \subseteq V$. So
$\RState{\Sigma}{\FV(\Phi)} \models \Phi$, by~\eqref{eqn:SAA-SAB},
because $\RState{\Sigma}{\FV(\Phi)} = \RState{\RState{\Sigma}{U\!}}{\FV(\Phi)}$.
Similarly, $\RState{\Sigma}{\FV(\Phi)} \models \Psi$.
Finally, since, if we compose $\sigma \mapsto \RState{\sigma}{\FV{\Phi}}$
with the left-hand side and $\sigma \mapsto \RState{\sigma}{\FV{\Psi}}$ with the right-hand side
 of the independence statement $\RState{\Sigma}{U} \Indep \RState{\Sigma}{V}$, then
it follows from~\eqref{indep-function} (and its symmetric version) that
$\Sigma_{\FV(\Phi)} \Indep \Sigma_{\FV(\Psi)}$.

As a final comment about $*$, we remark that it is possible for 
$\Sigma \models \Phi * \Psi$ to hold in cases in which $\FV(\Phi) \cap \FV(\Psi) \neq \emptyset$.
In such cases, by composing both sides of $\RState{\Sigma}{\FV(\Phi)} \Indep \RState{\Sigma}{\FV(\Psi)}$
with the function $\sigma \mapsto \RState{\sigma}{V}$, where $V := \FV(\Phi) \cap \FV(\Psi)$, it
follows from~\eqref{indep-function} that $\RState{\Sigma}{V} \Indep \RState{\Sigma}{V}$.
This means that $\RState{\Sigma}{V}$ is a deterministic random variable. That is, there exists
a $V$-defined state $\sigma$ such that $\Prob[\RState{\Sigma}{V} = \sigma] = 1$.
Thus our formulation of the separating conjunction, automatically entails the property that the two sides $\Phi$ and $\Psi$ can share deterministic variables, which in the original probabilistic separation logics is built-in 
via a syntactic distinction between deterministic and probabilistic variables~\cite{BHL,BGHT}.




\section{Specifications}
\label{section:specifications}

%
% *****************************************************************
%
A \emph{specification} is given by a Hoare triple
\[
\{\Phi\} \, C \, \{\Psi\} \, ,
\]
where $\Phi$ and $\Psi$ are semantic assertions, and $C$ is a command from the programming language of Section~\ref{section:language}.
As is standard, we shall have two forms of correctness for specifications, \emph{partial} and \emph{total}, whose precise form, in which \emph{safety} is built in, is influenced by heap separation logic~\cite{OHRY,YOH}. Partial correctness will say that if $C$ is run in any random state $\Sigma$ for which $\Sigma \models \Phi$, then the execution of $C$ is fault-free (this is the safety component) and, if $C$ almost surely terminates, then 
$\Tau \models \Psi$, where $\Tau$ is the induced random state in which $C$ terminates. Total correctness more simply says that if $C$ is run in any random state $\Sigma$, for which $\Sigma \models \Phi$, then $C$ almost surely terminates (hence is \emph{a fortiori} fault-free), and $\Tau \models \Psi$, where $\Tau$ is the termination random state. To make this precise, we have to define the random state in which a terminating program terminates.

Let $\Sigma : \Omega \to \State$ be a random state. We view the pair $C, \Sigma$ as a random configuration (with deterministic first component). The notions of fault-freeness and termination for 
deterministic configurations, defined in Section~\ref{section:language}, extend to random configurations 
in the natural way. Specifically, 
we say that $C,\Sigma$ is \emph{fault-free} if
$\Prob[\text{$C, \Sigma$ is fault-free}] = 1$,%
\footnote{Because $\Supp(p_\Omega) = \Omega$,
this is equivalent to the probability-free: for every $\omega \in \Omega$, the configuration $C, \Sigma(\omega)$ is fault-free. However, the probabilistic formulation is preferable, since it is independent of the design choice that $\Supp(p_\Omega) = \Omega$.}
and is 
%, for every $\omega \in \Omega$, the configuration $C, \Sigma(\omega)$ is fault free (as defined in Section~\ref{section:language}).
%Similarly, we say 
%that $C,\Sigma$ is 
\emph{terminating} if $\Prob[\text{$C, \Sigma$ is terminating}] = 1$.
% for every $\omega \in \Omega$, the configuration $C, \Sigma(\omega)$ is terminating. If $C,\Sigma$ is terminating, then we define a new sample space $\Omega_{C,\Sigma}$ by
\begin{align*}
\Omega_{C,\Sigma} ~ := ~ & \{ (\omega, \pi) \mid 
\text{$\omega \in \Omega$ and $\pi$ is a terminal path from $C,\Sigma(\omega)$}\} \\
p_{\Omega_{C,\Sigma}} (\omega,\pi) ~ := ~ & p_\Omega(\omega) \cdot \Prob(\pi)\, .
\end{align*}
Note that it is because of the condition that $C,\Sigma$ is terminating that $p_{\Omega_{C,\Sigma}}$ is a probability distribution on $\Omega_{C,\Sigma}$. Also note that, for the same reason, the projection function $q_{C,\Sigma} : \Omega_{C,\Sigma} \Epi \Omega$, defined by
$q_{C,\Sigma}(\omega, \pi) := \omega$, is a morphism of sample spaces.
Define $\Tau_{C,\Sigma} : \Omega_{C,\Sigma} \to \State$ by 
\[
\Tau_{C,\Sigma} (\omega,\pi) ~ := ~ \Final(\pi) \, .
\]
It is $\Tau_{C,\Sigma}$ that provides the desired termination random state of the random configuration
$C, \Sigma$.

\begin{definition}[Partial correctness]
\label{definition:partial-correctness}
A specification $\{\Phi\} \, C \, \{\Psi\}$ is \emph{partially correct} if, for every random state $\Sigma: \Omega \to \State$ for which $\Sigma \models \Phi$ we have:
\begin{itemize} 
\item $C, \Sigma$ is fault-free (the \emph{safety guarantee}), and 
\item if $C, \Sigma$ is terminating then $\Tau_{C,\Sigma} \models \Psi$.
\end{itemize}
\end{definition}

\begin{definition}[Total correctness]
A specification $\{\Phi\} \, C \, \{\Psi\}$ is \emph{totally correct} if, for every random state $\Sigma: \Omega \to \State$ for which $\Sigma \models \Phi$ we have:
\begin{itemize} 
\item  $C, \Sigma$ is terminating and $\Tau_{C,\Sigma} \models \Psi$.
\end{itemize}
\end{definition}
\noindent
It is trivial that every totally correct specification is partially correct. 



\section{The frame rule}
\label{section:frame}

\begin{figure}
\[
\begin{prooftree}
\{\Phi\} \, C\, \{\Psi\}
\justifies
\,\{\Phi * \Theta \} \, C\, \{\Psi * \Theta\}\,
\using{\,\FV(\Theta) \cap \MV(C) = \emptyset}
\end{prooftree}
\]
\caption{The frame rule}
\label{figure:frame-rule}
\begin{align*}
\MV(\pAssgn{X}{D}) ~ & := ~ \{X\}  &  \MV(C_1;C_2) ~ & := ~ \MV(C_1) \cup \MV(C_2) \\
\MV(X := E) ~ & := ~ \{X\} & \MV(\If\ B\ \Then\ C_1\ \Else\ C_2) ~ & := ~  \MV(C_1) \cup \MV(C_2) \\
\MV(\Skip)~ & := ~  \emptyset & \MV(\While\ B\ \Do\ C) ~ & := ~  \MV(C)\, .
\end{align*}
\caption{Modified variables $\MV(C)$}
\label{figure:MV}
\end{figure}


The frame rule is given in Figure~\ref{figure:frame-rule}. 
Its formulation is identical to the 
original frame rule formulation in heap separation logic~\cite{YOH}.
The single side condition involves the set 
$\MV(C)$ of all variables that the program $C$ is able to modify, which is defined (in the obvious way) in Figure~\ref{figure:MV}. The lemmas below simply state that variables outside $\MV(C)$ do not change during the execution of $C$. The statement we need later is given by Lemma~\ref{lemma:MV-random}, which asserts this for random state. This is in turn a simple consequence of Lemma~\ref{lemma:MV-deterministic}, which states the property for deterministic state. The straightforward proofs are omitted.
\begin{lemma}
\label{lemma:MV-deterministic}
If $V \subseteq \Var$ is such that $V \cap \MV(C) = \emptyset$, and if $C, \sigma \dTrans^* \tau$ then
$\RState{\tau}{V} = \RState{\sigma}{V}\,$.
\end{lemma}
\begin{lemma}
\label{lemma:MV-random}
If $V \subseteq \Var$ is such that $V \cap \MV(C) = \emptyset$, and if $C,\Sigma$ is a terminating random configuration then $\RState{\Tau_{C,\Sigma}}{V} = \RState{\Sigma}{V} \circ q_{C,\Sigma}\,$.
\end{lemma}
\noindent
Rather than using the syntactic definition of $\MV(C)$  in Figure~\ref{figure:MV}, we remark that one could take the satisfaction of
Lemma~\ref{lemma:MV-deterministic} as a more permissive semantic definition of the set $\MV(C)$ , and the proof of the frame rule below remains valid. 

The main work in proving the soundness of the frame rule lies in proving the theorem below, which
formulates the \emph{relative tightness} property outlined in Section~\ref{section:introduction}. 
This
 asserts a fundamental property of partial (and hence also total) correctness specifications:  the portion of the final state 
$\Tau_{C,\Sigma}$ that is relevant to interpreting the postcondition $\Psi$, 
namely $\RState{\Tau_{C,\Sigma}}{\FV(\Psi)}$, depends only on that part of the start state
$\Sigma$ that is relevant to interpreting the precondition $\Phi$, namely $\RState{\Sigma}{\FV(\Phi)}$. Since the state is randomised, the property of depending only on $\RState{\Sigma}{\FV(\Phi)}$ can be expressed by saying that $\RState{\Tau_{C,\Sigma}}{\FV(\Psi)}$ is  conditionally independent of the input state $\Sigma$ conditional on $\RState{\Sigma}{\FV(\Phi)}$.
In order to formulate this property precisely, the random variables involving $\Sigma$ need to be composed with the
sample space morphism $q_{C,\Sigma} : \Omega_{C,\Sigma} \Epi \Omega$, so that all random variables 
lie over the same sample space $\Omega_{C,\Sigma}$. 


\begin{theorem}[Relative tightness]
\label{theorem:independence}
Suppose $\{\Phi\} C \{\Psi\}$ is partially correct, $\Sigma \models \Phi$ and the random configuration 
$C, \Sigma$ is terminating,
then 
\begin{equation}
\label{eqn:relative-tightness}
 \RState{\Tau_{C,\Sigma}}{\,\FV(\Psi)} ~  \Indep ~  \Sigma \circ q_{C,\Sigma} ~ \mid ~
  \RState{\Sigma}{\FV(\Phi)} \circ \, q_{C,\Sigma} ~ . 
\end{equation}
\end{theorem}

\noindent
Before giving the somewhat involved proof of Theorem~\ref{theorem:independence}, we 
show how the soundness of the frame rule follows as a consequence of relative tightness.
%the theorem, via an argument whose high-level structure is at the pleasingly abstract level of reasoning using general principles of independence and  conditional independence. % using general principles (already discused in Section~\ref{section:preliminaries}.
\begin{corollary}[Soundness of the frame rule]
\label{corollary:frame}
The frame rule is sound for both partial correctness and total correctness.
\end{corollary}
\begin{proof} We first consider partial correctness. Suppose $\{\Phi\} C \{\Psi\}$ is partially correct. Suppose
also that $\Theta$ is such that $\FV(\Theta) \cap \MV(C) = \emptyset$. 
We need to show that the specification $\{\Phi * \Theta \} C \{\Psi * \Theta\}$ is partially correct.

Suppose then that $\Sigma \models \Phi * \Theta$. That is, we have
\begin{gather}
\label{frame-sound-phi}
\Sigma \models \Phi
\\
\label{frame-sound-theta}
\Sigma \models \Theta
\\
\label{frame-sound-PIT}
\Sigma_{\FV(\Phi)} \Indep \Sigma_{\FV(\Theta)}
\end{gather}
%We need to show that the random configuration $C, \Sigma$ is fault-free, and that
%if $C, \Sigma$ is terminating then $\Tau_{C,\Sigma} \models \Psi * \Theta$.
By~\eqref{frame-sound-phi} and the partial correctness of $\{\Phi\} C \{\Psi\}$,
it is immediate that $C, \Sigma$ is fault-free. Assume that $C, \Sigma$ is terminating. We need to show that 
$\Tau_{C,\Sigma} \models \Psi * \Theta$.

 By~\eqref{frame-sound-phi} and the partial correctness of $\{\Phi\} C \{\Psi\}$, we 
have $\Tau_{C,\Sigma} \models \Psi$. 

Since $\FV(\Theta) \cap \MV(C) = \emptyset$,
we have, by Lemma~\ref{lemma:MV-random}, that 
\begin{equation}
\label{frame-sound-equality}
\RState{\Tau_{C,\Sigma}}{\FV(\Theta)} = \RState{\Sigma}{\FV(\Theta)} \! \circ \, q_{C,\Sigma}\, .
\end{equation}
From~\eqref{frame-sound-theta}, it follows that  
$\RState{\Sigma}{\FV(\Theta)} \models \Theta$, by~\eqref{eqn:SAA-SAB}, hence 
$\RState{\Sigma}{\FV(\Theta)} \circ q_{C,\Sigma} \models \Theta$ by (SA3), i.e.,
$\RState{\Tau_{C,\Sigma}}{\FV(\Theta)} \models \Theta$. It then follows from (SA1)
that $\Tau_{C,\Sigma} \models \Theta$.

Finally, we show that $\RState{\Tau_{C,\Sigma}}{\FV(\Psi)} \Indep \RState{\Tau_{C,\Sigma}}{\FV(\Theta)}$.
By~\eqref{frame-sound-PIT}, we have 
 $\RState{\Sigma}{\FV(\Phi)} \circ q_{C,\Sigma} \Indep \RState{\Sigma}{\FV(\Theta)} \circ q_{C,\Sigma}$; equivalently, by~\eqref{frame-sound-equality} (and the symmetry of independence)
\begin{equation}
\label{frame-sound-indep-a}
\RState{\Tau_{C,\Sigma}}{\FV(\Theta)} 
\Indep 
\RState{\Sigma}{\FV(\Phi)} \circ \, q_{C,\Sigma} \, .
\end{equation}
  By Theorem~\ref{theorem:independence}, we have 
$\RState{\Tau_{C,\Sigma}}{\FV(\Psi)}   \Indep  \Sigma \circ q_{C,\Sigma}  \mid 
  \RState{\Sigma}{\FV(\Phi)}  \circ \, q_{C,\Sigma}$.
  It thus follows from~\eqref{cond-indep-def} and~\eqref{indep-function}, using the function $\sigma \mapsto \RState{\sigma}{\FV(\Theta)} : \State \to \State$, that
  $\RState{\Tau_{C,\Sigma}}{\FV(\Psi)}   \Indep  \RState{\Sigma}{\FV(\Theta)} \circ q_{C,\Sigma}  \mid 
  \RState{\Sigma}{\FV(\Phi)}  \circ \, q_{C,\Sigma}\,$; i.e., by~\eqref{frame-sound-equality},
  \begin{equation}
  \label{frame-sound-indep-b}
  \RState{\Tau_{C,\Sigma}}{\FV(\Psi)}   \Indep  \RState{\Tau_{C,\Sigma}}{\FV(\Theta)} 
   \mid 
  \RState{\Sigma}{\FV(\Phi)}  \circ q_{C,\Sigma} \, .
  \end{equation}
  Applying~\eqref{cond-indep-rule} to~\eqref{frame-sound-indep-a} and~\eqref{frame-sound-indep-b}, we get
  \[\RState{\Tau_{C,\Sigma}}{\FV(\Psi)}  \, \Indep \, (\RState{\Tau_{C,\Sigma}}{\FV(\Theta)} , \,
  \RState{\Sigma}{\FV(\Phi)} \! \circ q_{C,\Sigma})\, .\]
  Finally, by another application of~\eqref{indep-function}, using first projection $(\tau,\sigma) \mapsto \tau$ as the function, we obtain
  $\RState{\Tau_{C,\Sigma}}{\FV(\Psi)}   \Indep  \RState{\Tau_{C,\Sigma}}{\FV(\Theta)}$, as required.

  The soundness of the frame rule for total correctness follows directly from soundness for partial correctness, because the  termination of $C, \Sigma$, which is the only additional property needed to
to show the total correctness of
 $ \{\Phi * \Theta \} \, C\, \{\Psi * \Theta\}$, is immediate from the assumption that
 $ \{\Phi\} \, C\, \{\Psi \}$ is totally correct.
\end{proof}

We now turn to the proof of Theorem~\ref{theorem:independence}. In preparation, we need a simple lemma about the operational semantics. Given $\sigma,\sigma' \in \State$, we define $\Mask{\sigma}{\sigma'} \in \State$ (the
\emph{masking of $\sigma$ by
$\sigma'$}) by:
\[
\Mask{\sigma}{\sigma'}(X) ~ := ~ \begin{cases}
\sigma'(X) & \text{if $X \in \Dom(\sigma')$} \\
\sigma(X) & \text{otherwise}\, .
\end{cases}
\]
It is immediate from the definition that 
$\sigma' \sqleq \Mask{\sigma}{\sigma'}$. Also we have:
\begin{equation}
\label{equation:masking}
\sigma' \sqleq \sigma ~ \implies ~ \Mask{\sigma}{\sigma'} = \sigma \, .
\end{equation}
\begin{lemma}[Masking lemma]
\label{lemma:masking}
For any state $\sigma$, configuration $C_0,\sigma_0$ and terminal path $\pi \in \TP_{C_0,\sigma_0}$ of the form
\eqref{eqn:terminal-path}, we have $\Mask{\sigma}{\pi} \in \TP_{C_0,\Mask{\sigma}{\sigma_0}}$, where the masked path $\Mask{\sigma}{\pi}$ is defined by
\[
\Mask{\sigma}{\pi} ~ := ~ C_0,\Mask{\sigma}{\sigma_0} \lTrans{L_0} C_1,\Mask{\sigma}{\sigma_1}  \lTrans{L_1}  \cdots\ C_{n-1},
\Mask{\sigma}{\sigma_{n-1}} \lTrans{L_{n-1}} \Mask{\sigma}{\tau}\, ,
\]
Similarly, for every infinite path $\zeta \in \TP_{C_0,\sigma_0}$ of the form
\eqref{eqn:infinite-path}, we have $\Mask{\sigma}{\zeta} \in \IP_{C_0,\Mask{\sigma}{\sigma_0}}$,
where the masked path $\Mask{\sigma}{\zeta}$ is defined by
\[
\Mask{\sigma}{\zeta} ~ := ~
C_0,\Mask{\sigma}{\sigma_0} \lTrans{L_0} C_1,\Mask{\sigma}{\sigma_1}  \lTrans{L_1}  C_{2},
\Mask{\sigma}{\sigma_{2}} \lTrans{L_{2}} \cdots \, ,
\]
\end{lemma}
\noindent
Although we omit the straightforward proof, we remark that
the lemma holds because the inequality $\sigma' \sqleq \Mask{\sigma}{\sigma'}$ means that
transitions of the form $C', \sigma'  \lTrans{L} C'', \sigma''$
and $C', \sigma'  \lTrans{L} \tau'$ are preserved by masking; that is, they give rise to transitions $C', \Mask{\sigma}{\sigma'}  \lTrans{L} C'', \Mask{\sigma}{\sigma''}$
and $C', \Mask{\sigma}{\sigma'}  \lTrans{L} \Mask{\sigma}{\tau'}$ respectively.
The same does not apply to error transitions $C', \sigma'  \dTrans \Fail$, because
the masked state $\sigma$ may be defined on the variable whose undefinedness in
$\sigma'$ triggers the fault.





