  \begin{equation}
  \label{main-to-show}
 \forall\sigma,\sigma' \in \Supp({\Sigma}), ~~\RState{\sigma}{\FV(\Phi)} =  \RState{\sigma'}{\FV(\Phi)}
 ~ \implies ~ p_{T|S=\sigma} = p_{T|S=\sigma'} \, .
 \end{equation}
