\section{Preliminaries}\label{sec:Preliminaries}
While there are plenty other more comprehensive sources regarding Ore algebras and D-finite functions  \cite{Kauers2023,ChyzakSalvy1998}, Poincar\'e Perron asymptotics \cite{Poincare1885,Perron1921,FlajoletSedgewick2009,}, and Ap\'ery limits \cite{DoughertyBliss2021,ChamberlandStraub2021,KoutschanZudilin2021}, the following sub-sections detail definitions, theorems, and notations that will be used later in this paper. The final sub-section regarding conservative matrix fields contains similarly core definitions and results.
\subsection{Ore Algebra}
Recall the definition of Ore algebras, as defined in \cite{Kauers2023}:
\begin{definition}\label{def:ore_algebra}
    Let $A$ be an integral domain, with $\sigma$ endomorphism, and $\delta$ a $\sigma$-derivation. Meaning $\delta:A\to A$ is linear, and satisfies:
    \[\delta(ab) =\delta(a)b+\sigma(a)\delta(b)\]
    for all $a,b\in A$\\
    Define $A[\partial]$ as the ring of polynomials in $\partial$, with non-commutative multiplication, satisfying for $a\in A$:
    \[\partial a = \sigma(a)\partial + \delta(a)\]
    Then, $\A\coloneqq (A[\partial],\sigma,\delta)$ is an \textit{Ore algebra} over $A$. 
\end{definition}

\begin{examp}\label{ex:univar_ore_algs}
While the generality of Definition \ref{def:ore_algebra} is useful, this work deals with two main Ore algebras. Let $K$ be a field of characteristic $0$. We consider two main Ore algebras:
\begin{itemize}
    \item $(K(z)[\theta_z],\Id,z\frac{d}{dz})$ - the algebra of Euler differential operators
    \item $(K(x)[S],\sigma,0)$, where $\sigma(x) = x+1$ - the algebra of recurrence operators. Satisfying $Sf(x) = f(x+1)S$
\end{itemize}
\end{examp}
Ore algebras can be considered in the multivariate case, under further conditions. 
\begin{definition}\label{def:multivariate_ore_algebra}
For $1\<=i\<=d$, let $\A_i \coloneqq (A[\partial_i],\sigma_i,\delta_i)$ be Ore algebras, where the $\sigma_i$'s and $\delta_i$'s commute. One can define the non-commutative ring $A[\partial_1,\dots, \partial_d]$ with each $\partial_i$ satisfying the same commutation with field elements as in $\A_i$, and also satisfying $\partial_i\partial_j = \partial_j\partial_i$.\\
    Then, $\A\coloneqq(A[\partial_1,\dots, \partial_d],\sigma_1,\dots,\sigma_d,\delta_1,\dots,\delta_d)$ is a (multivariate) \textit{Ore algebra} over $A$. 
\end{definition}
\begin{examp}
an example of such extension is that of Ore Laurent polynomials. For example, for $K$ field of characteristic 0, consider:
\[\A' \coloneqq(K(x)[S,S^{-1}],\sigma,\sigma^{-1},0,0)\]
Note that as $\sigma$ commutes with its inverse, and as both derivations are the zero function, the conditions in Definition \ref{def:multivariate_ore_algebra} hold.
\end{examp}
Let us detail the multivariate Ore algebras that will be core to the theory of conservative matrix fields. 
\begin{remark}\label{rem:mult_ore_algebra_shift_notation}
    We will be interested in the following multivariate Ore algebras:
    $$\text{for } \textbf{x} =(x_1,\dots,x_d),\textbf{z} =(z_1,\dots,z_l),\quad \A = K(\textbf{x},\textbf{z})[S_{x_1},\dots,S_{x_d},\theta_{z_1},\dots,\theta_{z_l}]$$
    $$\A' = K(\textbf{x},\textbf{z})[S_{x_1},S_{x_1}^{-1},\dots,S_{x_d},S_{x_d}^{-1},\theta_{z_1},\dots,\theta_{z_l}]$$
with $S_{x_i}$ the shift operator of $x_i$, and $\theta_{z_i}$ the Euler differential of $z_i$.\\
We will notate a shift in direction $v$ for $v = (v_1,\dots,v_d)$ (with $v\in\N^d$ in $\A$ and $v\in\Z^d$ in $\A'$) as  $S_v\coloneqq\prod_{i=1}^dS^{v_i}_{x_i}$ and $\sigma_v$ as the appropriate composition of $\sigma_i$'s. Meaning, for $f\in K(\textbf{x},\textbf{z})$:
    \[S_vf(x,z) = \sigma_v(f(x,z))S_v = f(x+v,z)S_v\]
    Note $S_vS_w = S_{v+w}$.
\end{remark}
\subsection{D-finite Functions}
The ring of functions $f\in F\coloneqq K(\textbf{x})[[\textbf{z}]]$ form a left module of the Ore algebras in Remark \ref{rem:mult_ore_algebra_shift_notation}. We shall notate the action using a bottom dot: meaning for $L\in\A$, its action on $f\in F$ is notated as $L.f$. Some such functions vanish under operators in an Ore algebra ($L.f \equiv 0$). This set of operators is called the annihilator ideal:
\begin{definition}
    the \textit{Annihilator} of a function $f(\textbf{x},\textbf{z})\in F$ in the Ore algebra $\A = K(\textbf{x},\textbf{z})[S_{x_1},\dots,S_{x_d},\theta_{z_1},\dots,\theta_{z_l}]$ is the following set:
    $$\text{ann}(f) = \set{L\in \A: L.f = 0}$$
\end{definition}
\begin{remark}
    $\text{ann}(f)\subset \A$ is a left ideal of the Ore algebra $\A$.
\end{remark}
Often, the image of a function under a set of operators is also considered:
\begin{definition}
the image of a function $f\in F$ under an Ore algebra $\A$ is the following set:
$$\A.f \coloneqq \set{L.f:L\in\A}$$
\end{definition}
\begin{definition}\label{def:D_finite}
    A \textit{D-finite function} $f$ is a function for which:
    \[\dim \A/\text{ann}(f) = \dim \A.f < \infty\]
As vector spaces over $K(\textbf{x},\textbf{z})$.
\end{definition}
\begin{remark}\label{rem:Dfin_other_defs_and_neg_shift} ${}$
\begin{itemize}
    \item The condition in Definition \ref{def:D_finite} is equivalent (and sometimes replaced by) either $\dim \text{span}\set{\partial_i^k.f:k\in\N}<\infty$ for all $i$, or $K[\partial_i]\cap \text{ann}(f)\neq\emptyset$ for all $i$.
    \item Note that for any $f\in F$, $S_{x_i}.f\equiv 0\iff f\equiv 0$. Thus implying, for $f\in F$ D-finite, the minimal degree operator in $K[S_{x_i}]\cap \text{ann}(f)$, $\sum_{j=0}^r p_j S_{x_i}^j$ satisfies $p_j\in K(\textbf{x},\textbf{z})\quad p_0,p_r\not\equiv0$
    \item Given that minimal operator $\sum_{j=0}^r p_j S_{x_i}^j$, Note that: 
    $$\left(\sum_{j=0}^r p_jS_{x_i}^j\right).f = 0\implies \left(-\sum_{j=1}^r \frac{p_j}{p_0}S_{x_i}^{j}\right).f = f$$
    $$\implies \left( -\sum_{j=1}^r \sigma_i^{-1}\left(\frac{p_j}{p_0}\right)S_{x_i}^{j-1}\right).f = \sigma_i^{-1}(f) = S_{x_i}^{-1}.f$$
    \item The point above means that for $f\in F$ D-finite over $\A$, $\A.f = \A'.f$
\end{itemize}
\end{remark}
\begin{examp}
Examples of D-finite functions include:
\begin{itemize}
    \item The binomial $f(n,k) = \binom{n}{k}$ is D-finite in $\A = \Q(n,k)[S_{n},S_{k}]$
    \item Bessel Functions (such as $J_n(z),I_n(z)\dots$) are D-finite in $\A = \Q(n,z)[S_n,\theta_z]$
    \item Generalized hypergeometric functions $\pFq{p}{q}{x_1,\dots,x_p}{y_{1},\dots,y_{q}}{z}$ are D-finite in $\A = \Q(\textbf{x},\textbf{y},z)[S_{x_1},\dots,S_{y_q},\theta_z]$
\end{itemize}
\end{examp}
For the special case of a univariate Ore algebra $K(n)[S_n]$ (recurrence operator algebra), D-finite functions are called \textit{D-finite Sequences} or sometimes \textit{Holonomic} or \textit{P-recursive} sequences.
\subsection{Poincar\'e Perron Asymptotics}
The two landmark papers by Poincar\'e and Perron \cite{Poincare1885,Perron1921}, establish the asymptotic analysis of D-finite sequences. First, let us define the asymptotic of a function:
\begin{definition}\label{def:asymptotic}
    A function  $g(n)$ is an \textit{asymptotic} of $f(n)$ if $\lim_{n\to\infty}\frac{f(n)}{g(n)}=1$, and that is denoted as $f(n)\sim g(n)$
\end{definition}
\begin{theorem} \label{thm:poincare_perron}
(Poincar\'e 1885,  Perron 1921)\footnote{Our formulation is not as general as the original, as we are interested only in D-finite sequences.}. Let $L\in \Q(n)[S_n]$ satisfy:
$$L = \sum_{i=0}^r a_i(n)S_n^i\quad \text{s.t}\quad a_r = 1\ , \ \lim_{n\to\infty}a_i(n) = a_i$$
Suppose further the roots ($ \lambda_1,\dots,\lambda_r$) of the \textit{characteristic polynomial} $\sum_{i=0}^r a_it^i$ satisfy:
$$\abs{\lambda_1}>\abs{\lambda_2}>\cdots >\abs{\lambda_r}$$
Then, for any solution $u(n)$ of $L$ (meaning $L.u(n) = 0$), either $\exists_N :\forall_{n>N}\ u(n) =0$, or $\lim_{n\to\infty}\frac{u(n+1)}{u(n)} = \lambda_i$ for some $i$.\\
If also $\forall_n\ a_1(n)\neq 0$, then for each $\lambda_i$ there exists a solution $u(n)$ of $L$ such that $\lim_{n\to\infty}\frac{u(n+1)}{u(n)} = \lambda_i$. 
\end{theorem}
\begin{remark}\label{rem:eigens_of_companion}
The roots  ($ \lambda_1,\dots,\lambda_r$)  of the characteristic polynomial of $L\in \Q(n)[S_n]$ will be referred to as the \textit{eigenvalues} of the recurrence.\\
This, as when $L$ is encoded as a companion matrix, the characteristic polynomial of the matrix is exactly the characteristic polynomial of the recurrence. Thus,  the eigenvalues of the limit of the companion matrix as $n\to \infty$, are exactly the roots ($ \lambda_1,\dots,\lambda_r$)
\end{remark}
A well known corollary of the theorem of Poincar\'e and Perron is the following:
\begin{corollary}\label{cor:asymptotic_decomposition}
If the conditions in Theorem \ref{thm:poincare_perron} are satisfied, then each solution $u(n)$ satisfies:
$$u(n)= \sum_{i=1}^r c_i\lambda_i^nf_i(n)$$
where each $\lambda_i^nf_i(n)$ is a solution to $L$, the functions $f_i(n)$ are independent of initial conditions, and satisfy $\frac{f_i(n+1)}{f_i(n)}\to 1$.\\
The values of $c_i$ depend linearly on the initial conditions, and will be referred to as \textit{multiplicative constants}.
\end{corollary}
\begin{corollary}\label{cor:asymptotic_with_first_nonzero}
If the conditions in Theorem \ref{thm:poincare_perron} are achieved, then each non-zero solution $u(n)$ satisfies:
$$u(n)\sim c_j\lambda_j^nf_j(n)$$
Where $j$ is the index of the first non zero multiplicative constant. ($j = \min\set{1\<=i\<=r:c_i\neq0}$)
\end{corollary}
\begin{remark}\label{rem:c_i_closed_form}
    Finding closed forms for $c_i$ as functions of the initial conditions is not solved in the general case and is of general interest. \cite{Melczer2021,PemantleWilsonMelczer2024}
\end{remark}
Corollaries \ref{cor:asymptotic_decomposition},\ref{cor:asymptotic_with_first_nonzero} are highly useful for the theory of Ap\'ery limits, which is discussed in the following sub-section.
