It is useful to examine the matrices associated with straight paths in $x+\Z^d$. We call such paths (starting at point $x$ and moving by $v$ at each step) \textit{trajectories}, and the associated sequence of matrices \textit{trajectory matrices}. A definition:
\begin{definition}
    In a CMF $\clM$ of dimension $d$ and rank $r$ over $K$, we define a \textit{trajectory matrix}  $T_{x,v}(n)$ as the matrix that is associated with the $n$th step (starting at 0) in the trajectory $x+nv$
    $$T_{x,v}(n) \coloneqq \clM_v(x+nv)\in \text{GL}_r(K(n))$$
\end{definition}
Using \eqref{eq:path_indep} we have the following: 
\begin{remark}
    Defining $\prod$ notation for matrices thusly:
    $$\prod_{k=0}^n M_k = M_0\cdot M_1\cdots M_n$$
    results in:
    \begin{equation}\label{eq:prod_of_traj}
        \clM_{nv}(x) = \prod_{k=0}^{n-1} T_{x,v}(k)
    \end{equation}
\end{remark}
\begin{examp}\label{ex:Zeta3Traj}
Using the CMF defined in Example \ref{ex:Zeta3CMF}, we see that:
$$T_{(1,1),(1,0)}(n) = \begin{pmatrix}0 & -1\\\frac{\left(n + 2\right)^{3}}{\left(n + 1\right)^{3}} & \frac{\left(2 n + 3\right) \left(n^{2} + 3 n + 3\right)}{\left(n + 1\right)^{3}}\end{pmatrix}$$ $$T_{(1,1),(1,1)}(n) = \begin{pmatrix}- \frac{\left(n + 2\right)^{3}}{\left(n + 1\right)^{3}} & \frac{\left(- 2 n - 3\right) \left(3 n^{2} + 9 n + 7\right)}{\left(n + 1\right)^{3}}\\\frac{6 \left(n + 2\right)^{3}}{\left(n + 1\right)^{3}} & \frac{35 n^{3} + 159 n^{2} + 243 n + 125}{\left(n + 1\right)^{3}}\end{pmatrix}$$
\end{examp}
\begin{remark}
Note that from Example \ref{ex:1dCMF}, trajectory matrices generate a 1-dimensional CMF. In fact, as 1-dimensional CMFs are very well studied (under the guise of D-finite systems), CMFs can be considered higher dimensional generalizations of D-finite systems.
\end{remark}
A final preliminary notion that requires a definition is that of a \textit{coboundary transformation}:
\begin{definition}
    Two CMFs $\clM^1,\clM^2$ of dimension $d$ and rank $r$ over $K$, are \textit{coboundary equivalent} %\footnote{The set $\clZ^1(\Z^d,\text{GL}_r(K(\mathbf{x})))/\!\!\sim$ of conservative matrix fields up to coboundary equivalence is denoted $\text{H}^1(\Z^d,\text{GL}_r(K(\mathbf{x})))$, the first cohomology of $\Z^d$ with $\text{GL}_r(K(\mathbf{x}))$-coefficients. It is a pointed set whose distinguished point is the equivalence class of coboundaries.} 
    (which we notate as $\clM^1 \sim \clM^2$) if there exists a matrix $A \in \text{GL}_r(K(\mathbf{x}))$ such that 
    \begin{equation}
         A \cdot \clM^1_v = \clM^2_v \cdot \sigma_v(A)
    \end{equation}
    or equivalently:
    \begin{equation}
         A \clM^1_v S_v = \clM^2_v S_v A
    \end{equation}
    for every $v \in \Z^d$.\\
The matrix $A$ will be referred to as the \textit{coboundary matrix}
\end{definition}
It is a good exercise to verify that in fact a coboundary transformation $\clM_v\mapsto A^{-1}\cdot\clM_v\cdot \sigma_v(A)$ satisfies the cocycle condition \eqref{eq:cocycle}. A few examples:

\begin{examp}
The CMF from Example \ref{ex:Zeta3CMF} is coboundary equivalent to the CMF generated by:
$$\overline{M}_1 = \begin{pmatrix}
\frac{x_{2} \left(2 x_{1} + 1\right) \left(x_{2} - 1\right) + \left(x_{1} + 1\right)^{3}}{x_{1}^{3}} & \frac{x_{2}^{2} \left(2 x_{1} + 1\right) \left(x_{2} - 1\right)}{x_{1}^{3}}\\\frac{x_{1}^{3} + x_{2} \left(2 x_{1} + 1\right) \left(x_{2} - 1\right) + \left(x_{1} + 1\right)^{3}}{x_{1}^{3} x_{2}} & \frac{x_{1}^{3} + x_{2} \left(2 x_{1} + 1\right) \left(x_{2} - 1\right)}{x_{1}^{3}}
\end{pmatrix}\quad \overline{M}_2 = \begin{pmatrix}
    \frac{2 x_{1}^{2}}{x_{2}^{2}} + 1 & \frac{2 x_{1} \left(x_{2} + 1\right)}{x_{2}}\\\frac{2 x_{1} \left(x_{1}^{2} + x_{2}^{2}\right)}{x_{2}^{4}} & \frac{\left(2 x_{1}^{2} + x_{2}^{2}\right) \left(x_{2} + 1\right)}{x_{2}^{3}}
\end{pmatrix}$$
Via the coboundary matrix $A = \begin{pmatrix}
    1&-y\\
    1&y
\end{pmatrix}$. This as:
$$\overline{M}_1 = A^{-1}M_1\sigma_{1}(A)\quad\overline{M}_2 = A^{-1}M_2\sigma_{2}(A)$$
\end{examp}
\begin{examp}
If we define $\overline{\clM} \coloneqq \sigma_w(\clM)$, then $\overline{\clM} \sim \clM$. This as for $A = \clM_w$:
$$A\overline{\clM}_v =  \clM_w \sigma_w(\clM_v) = \clM_{v+w} = \clM_v\sigma_v(\clM_w) =\clM_v\sigma_v(A) $$
\end{examp}
\begin{examp}\label{ex:Zeta3TrajCompanion}
Note how coboundary transforms effect trajectory matrices. Recall the trajectory matrices calculated in Example \ref{ex:Zeta3Traj}
Using the coboundary matrix $A = \begin{pmatrix}
   \frac{1}{x_{1}^{3}} & - \frac{1}{x_{2}^{3}}\\0 & \frac{x_{1}^{3} + 2 x_{1}^{2} x_{2} + 2 x_{1} x_{2}^{2} + x_{2}^{3}}{x_{1}^{3} x_{2}^{3}}
\end{pmatrix}$ on the CMF from Example \ref{ex:Zeta3CMF} , one gets that the trajectory matrix of the coboundary CMF $\overline{\clM}$ is:
$$\overline{T}_{(1,1),(1,1)}(n) = \begin{pmatrix}
    0 & - \frac{\left(n + 1\right)^{3}}{\left(n + 2\right)^{3}}\\1 & \frac{\left(2 n + 3\right) \left(17 n^{2} + 51 n + 39\right)}{\left(n + 2\right)^{3}}
\end{pmatrix}$$
Note that this matrix is in companion form, and encodes the recurrence:
$$(n+2)^3u(n+2)-(2n+3)(17n^2+51n+39)u(n+1) +(n+1)^3 u(n) = 0$$
The recurrence used in Ap\'erys proof of the irrationality of $\zeta(3)$ (see Theorem \ref{thm:aperys_theorem}).
\end{examp}
