\section{Dual CMF, and Sub CMF}\label{app:Dual_Sub_CMF}
\begin{definition} \label{def:Dual_CMF}
    Let $\clM$ be a CMF of dimension $d$ rank $r$ over $K$. Then, the \textit{Dual CMF} of $\clM$, $\clM^*$ is a CMF of dimension $d$ rank $r$ over $K$ satisfying:
    $$\forall_{v\in\Z^d}\ \clM^*_v = (\clM_v^{-1})^t$$
\end{definition}
\begin{definition}
    Let $\clM$ be a CMF of dimension $d$ rank $r$ over $K$. Let $\Lambda$ be a sub lattice of $\Z^d$, and let $(l_1,\dots,l_s)$ be a basis of $\Lambda$, and $(l_1,\dots,l_s,l_{s+1},\dots,l_{d})$ be a basis of $\Z^d$.\\
    Then, the matrices $\clM_{l_1},\dots,\clM_{l_s}$ can be rewritten as members of $\text{GL}_r(K(l_1,\dots,l_d))$, and in that form they generate a CMF of dimension $s$ rank $r$ over $K(l_{s+1},\dots,l_d)$. Such a CMF is called a \textit{Sub-CMF} of $\clM$.
\end{definition}
\begin{remark}
    Trajectory matrices $T_{x,v}(n)$ are evaluations of the sub-CMF associated with $\Lambda = \set{kv:k\in\Z}$
\end{remark}
