\section{Additional Details on the CALM-PDE Framework}
\label{app:calm-pde}

\subsection{CALM Layer}

\paragraph{Overview.} \Cref{fig:calm-layer-details} shows a CALM layer that performs continuous convolution with three distinct features: (i) locality inductive bias, consisting of a limited receptive field and distance weighting, to emphasize closer points, (ii) learnable query points to let the model learn where to compute convolution, and (iii) kernel modulation to allow different query points to have different weights for similar translation vectors. Depending on the purpose (e.g., encoder or final layer of the decoder), the query points can be learned or provided as an external input query. The kernel function $k$ is given as
\begin{equation}
    \resizebox{1.0\hsize}{!}{$
    k_{i,o}(a - \alpha) = \underbrace{\vphantom{\frac{\exp \bigl(-\frac{\norm{a - \alpha}^2 - \min(a)}{T(\max(a)-\min(a)))} \bigr)}{\sum\limits_{\alpha_j \in \mathtt{RF}(a)} \exp \bigr(- \frac{\norm{a - \alpha_j}^2 - \min(a)}{T(\max(a)-\min(a))} \bigl)}}\biggl(\boldsymbol{W_2} \cdot \sigma \Bigl( \bigl(\boldsymbol{W_1} \cdot \mathtt{RFF}(a - \alpha) + \boldsymbol{b_1} \bigr) \odot \boldsymbol{\gamma}_a + \boldsymbol{\beta}_a \Bigr) + \boldsymbol{b_2} \biggr)_{i,o}}_{\text{Modulated MLP}} \underbrace{\frac{\exp \bigl(-\frac{\norm{a - \alpha}^2 - \min(a)}{T(\max(a)-\min(a)))} \bigr)}{\sum\limits_{\alpha_j \in \mathtt{RF}(a)} \exp \bigr(- \frac{\norm{a - \alpha_j}^2 - \min(a)}{T(\max(a)-\min(a))} \bigl)}}_{\text{Distance Weighting}}
    $}
    \label{eq:kernel-function-complete}
\end{equation}
where $\boldsymbol{\gamma}_a$ and $\boldsymbol{\beta}_a$ denote the modulation parameters which depend on the query point $a$, and $\min(a) = \min_{\alpha_j \in \mathtt{RF}(a)}\norm{a - \alpha_j }^2$ computes the minimum distance within the epsilon neighborhood. Similarly, $\max(a)$ computes the maximum distance within the epsilon neighborhood. The distance normalization ensures that small distances are amplified and the effect of large distances is reduced.

