\centering
\caption{Dataset statistics.}
\vskip 0.5em
\label{tab:dataset_stats}
\begin{tabular}{lcccc}
\toprule
\textbf{Dataset}   & \textbf{Nodes} & \textbf{Edges} & \textbf{Features} & \textbf{Classes} \\ \midrule
