	& \quad +{h^3r_{1}}	((11 r_2/40 + r_3/4 ) f_{_\epsilon} -  (	\bv \cdot \nabla f_{_\epsilon} - \Delta f_{_\epsilon})/4)\\
	&\quad + h^4 ( r_{4} f_{_\epsilon} +r_{5} f_{_\epsilon}^{(1, 0)}  +r_{6} f_{_\epsilon}^{(0, 1)}+r_{7} f_{_\epsilon}^{(2, 0)}+ r_{3}  f_{_\epsilon}^{(1, 1)}/15+ r_{8} f_{_\epsilon}^{(0, 2)}-  2\zeta )\\
	&\quad + h^5 (  r_{9} f_{_\epsilon} +r_{10} f_{_\epsilon}^{(1, 0)}  +r_{11} f_{_\epsilon}^{(0, 1)}+r_{12} f_{_\epsilon}^{(2, 0)}+ r_{1}r_{3}  f_{_\epsilon}^{(1, 1)}/30+ r_{13} f_{_\epsilon}^{(0, 2)} \\
	&\quad \qquad -  r_{1}\zeta+ r_{1}( \Delta^2  f_{_\epsilon} +2f_{_\epsilon}^{(2, 2)} )/120),
\end{split}
\ee
%
%	
where
\be\label{zeta}
\bv:= (a_\epsilon,  b_\epsilon),\qquad \zeta:=(a_\epsilon f_\epsilon^{(3, 0)}  +  2b_\epsilon f_\epsilon^{(2, 1)} +  2a_\epsilon f_\epsilon^{(1, 2)} + b_\epsilon f_\epsilon^{(0, 3)})/60,
\ee
 $r_1,\dots r_{15}$ are defined in \eqref{r1:r15} and  each $f_\epsilon^{(m,n)}$ is defined in \eqref{fmn}.
%

Using the above \eqref{c:h:0}--\eqref{zeta}, we prove the sixth-order convergence rate of our FDM in the following \cref{theorem:interior}.
%
\begin{theorem}\label{theorem:interior} Assume that the solution $u$, the source term $f$, and the constant coefficient $(a,b)$ of \eqref{Model:Original} satisfy that $u\in C^8(\overline{\Omega})$, $f\in C^6(\overline{\Omega})$, and $a\ge b$. Let the grid point $(x_i,y_j)\in \Omega$ and define the following 9-point compact FDM:
	%%
	%
	\be\label{FDMs:u:interior}
		\mathcal{L}_h (u_h)_{i,j} :=\frac{1}{h^2}\sum_{k,\ell=-1}^1 C_{k,\ell} (u_h)_{i+k,j+\ell}=F_{i,j}\Big|_{(x,y)=(x_i,y_j)} \quad \text{with} \quad C_{k,\ell}:=\sum_{p=0}^6 c_{k,\ell ,p}h^p,
	\ee
%
where $c_{k,\ell,p}$ is defined in \eqref{c:h:0}--\eqref{c:h:6} and $F_{i,j}$ is defined in \eqref{F:ij}. Then
%
\be\label{sign:cd}
C_{k,\ell}\le  0 \quad \text{if} \quad (k,\ell)\ne (0,0), \quad   C_{0,0}>  0, \quad  \text{for any mesh size } h>0, \quad \text{and} \quad \sum_{k,\ell=-1}^1 C_{k,\ell}=0.
\ee
%
%
Furthermore,   $	\mathcal{L}_h (u_h)_{i,j}$ in \eqref{FDMs:u:interior}   with $u=g$ on $\partial \Omega$  forms an M-matrix for any mesh size $h>0$,  and
	\be\label{convergence:order:6}
\|u-u_h\|_{\infty}\le Ch^6, \quad  \text{for any mesh size } h>0,
	\ee
	where  $C$ is independent of  $h$.
\end{theorem}


\begin{proof}
%	
%
\textbf{Step 1 (the sixth	order of consistency):}		We define 
\be \label{ind}
\ind_{M+1}:=\{ (m,n)\in \NN^2 \; : \;  m+n\le M+1 \}, \qquad M+1\in \NN,\qquad \NN:=\N\cup\{0\},
\ee
and $\N$ denotes the set of all positive integers.
%
Then the Taylor expansion at the grid point $(\xa_i,\ya_j)\in \Omega$ with the Lagrange remainder can be written as 
%
%
%
\[
u(x_i+x,y_j+y)
=
\sum_{(m,n)\in \ind_{M+1}}
\frac{\partial^{m+n}u(\xa_i,\ya_j) }{\partial x^m \partial y^n}\frac{x^my^n}{m!n!}+\sum_{\substack{0\le m,n \le M+2 \\ m+n=M+2}} \frac{\partial^{M+2}u(\xi,\eta) }{\partial x^m \partial y^{n}}\frac{x^my^{n}}{m!n!},
\]
%
where $\xi \in (x_i-|x|,x_i+|x|)$ and $\eta \in (y_j-|y|,y_j+|y|)$. Choose $M=6$, and $x,y=0,\pm h,$
%
%
\be \label{taylor:u}
u(x_i+x,y_j+y)
=
\sum_{(m,n)\in \ind_{7}}
\frac{\partial^{m+n}u(\xa_i,\ya_j) }{\partial x^m \partial y^n}\frac{x^my^n}{m!n!}+c_1h^8, 
\ee
%
where $c_1$ only depends on $\frac{\partial^{8}u(\xi,\eta) }{\partial x^m \partial y^{n}}$ with $0\le m,n \le 8$,  $m+n=8$, $\xi \in (x_i-|x|,x_i+|x|)$ and $\eta \in (y_j-|y|,y_j+|y|)$. As $u\in C^8(\overline{\Omega})$, $|c_1|<\infty$. 
%
%
By the definition of $	\mathcal{L}_h (u_h)_{i,j} $ in \eqref{FDMs:u:interior}, we also define that
%
\be\label{L:h:u:1}
	\mathcal{L}_h (u)_{i,j} :=\frac{1}{h^2}\sum_{k,\ell=-1}^1 C_{k,\ell} u_{i+k,j+\ell}=\frac{1}{h^2}\sum_{k,\ell=-1}^1 C_{k,\ell} u(\xa_i+kh,\ya_j+\ell),
\ee
	%
for any $(x_i,y_j)\in \Omega$.
	Let 
	\be\label{L:u}
	\mathcal{L} u:=-  \Delta u + a_{\epsilon}u_x+b_{\epsilon}u_y.
	\ee
	%
Plug the defined $C_{k,\ell}$ in \eqref{FDMs:u:interior} with \eqref{c:h:0}--\eqref{c:h:6} and \eqref{taylor:u} into \eqref{L:h:u:1}, after the simplification, we obtain
\be\label{L:h:u:2}
\mathcal{L}_h (u)_{i,j} :=\sum_{p=0}^5C_p h^p\Big|_{(x,y)=(x_i,y_j)}+c_2h^6, \quad \text{for any }  h>0,
\ee
where $0<c_2$ is independent of $h$,
%
	\begin{align}\label{C0:C5}
	&C_0=6\mathcal{L} u,\qquad C_1=3r_{1} \mathcal{L} u, \notag\\
	&C_2= (21r_2 + 30r_3)\mathcal{L} u/20 - 	(\bv \cdot \nabla \mathcal{L} u - \Delta \mathcal{L} u) /2, \notag\\
	&C_3=\tfrac{r_{1}}{40}	(11 r_2 + 10 r_3 ) \mathcal{L} u - \tfrac{r_{1}}{4} (	\bv \cdot \nabla \mathcal{L} u - \Delta \mathcal{L} u),\notag\\
	&C_4=  r_{4} \mathcal{L} u +r_{5} \mathcal{L} u_x  +r_{6} \mathcal{L} u_y+r_{7} \mathcal{L} u_{xx}+ r_{3} \mathcal{L} u_{xy}/15+ r_{8} \mathcal{L} u_{yy} \\
	&\qquad -   (a_\epsilon \mathcal{L} u_{xxx}  + 2 b_\epsilon \mathcal{L} u_{xxy} +  2a_\epsilon \mathcal{L} u_{xyy} + b_\epsilon \mathcal{L} u_{yyy})/30,  \notag \\
	&C_5=   r_{9} \mathcal{L} u +r_{10} \mathcal{L} u_{x}  +r_{11} \mathcal{L} u_{y}+r_{12} \mathcal{L} u_{xx}+ r_{1}r_{3}  \mathcal{L} u_{xy}/30+ r_{13} \mathcal{L} u_{yy} \notag\\
	&\qquad -  r_{1}(a_\epsilon \mathcal{L} u_{xxx}  +  2b_\epsilon \mathcal{L} u_{xxy} +  2a_\epsilon \mathcal{L} u_{xyy} + b_\epsilon \mathcal{L} u_{yyy})/60 \notag\\
	&\qquad + r_{1}( \Delta^2  \mathcal{L} u +2 \mathcal{L} u_{xxyy}  )/120.\notag
\end{align}	
%
From \eqref{L:u}, we observe that $	\mathcal{L} u=f_{\epsilon}$ and  $	\mathcal{L} \tfrac{\p ^{m+n}u}{\p x^m \p y^n}=\tfrac{\p ^{m+n} f_{\epsilon}}{\p x^m \p y^n} $. Now \eqref{F:ij}, $\mathcal{L}_h(u_h)$ in \eqref{FDMs:u:interior}, \eqref{L:h:u:2}, and \eqref{C0:C5} imply that
\be\label{truncation:error:h:6}
|\mathcal{L}_h (u_h)_{i,j}-\mathcal{L}_h (u)_{i,j}|	\le c_3 h^6,  \quad \text{for any }  h>0 \text{ and } (x_i,y_j)\in \Omega,
\ee	
where $c_3=\max_{(x_i,y_i)\in \Omega} |c_2|$, and $c_3$ is independent of $h$.

\textbf{Step 2 (the M-matrix property):}
By \eqref{c:h:0}--\eqref{c:h:6}, $a_\epsilon \ge 1$, $b_\epsilon \ge 1$, and $a_\epsilon \ge b_\epsilon$, it is straightforward to verify that
\be	\label{ckl:p:0:5}
\begin{split}
& c_{k,\ell,0}<  0 \quad \text{if} \quad (k,\ell)\ne (0,0), \quad \text{and} \quad  c_{0,0,0}>  0,\\	
& c_{k,\ell,p}\le  0 \quad \text{if} \quad (k,\ell)\ne (0,0), \quad \text{and} \quad  c_{0,0,p}\ge  0, \quad \text{for} \quad p=1,2,3,4,6,\\
& c_{k,\ell,5}\le  0 \quad \text{if} \quad (k,\ell)\notin\{(-1,-1), (-1,1), (0,0)\}, \quad \text{and} \quad  c_{0,0,5}\ge  0.
\end{split}
\ee
We set that
\[
a_\epsilon =b_\epsilon+\omega, \quad \text{with} \quad \omega\ge 0, \quad a_\epsilon \ge 0, \quad b_\epsilon \ge 0.
\]
Then $ c _{-1, -1, 5}$ and $ c _{-1, 1, 5}$ in \eqref{c:h:5} lead to
\be\label{ckl:p5}
\begin{split}
	& c _{-1, -1, 5} = -(120 b_\epsilon ^5 + 320 \omega b_\epsilon ^4 + 328 \omega^2 b_\epsilon ^3 + 169 \omega^3 b_\epsilon ^2 + 45  \omega^4 b_\epsilon + 5\omega^5)/480
	\le 0,   \\
	& c _{-1, 1, 5} = -(20 \omega b_\epsilon ^4 + 48\omega^2 b_\epsilon ^3 + 49\omega^3 b_\epsilon ^2 + 25\omega^4 b_\epsilon  + 5\omega^5)/480
	\le 0.
\end{split}	
\ee
%
So, $C_{k,\ell}$ in \eqref{FDMs:u:interior} satisfies that
\be\label{M:Matrix}
C_{k,\ell}\le  0 \quad \text{if} \quad (k,\ell)\ne (0,0), \quad \text{and} \quad  C_{0,0}>  0, \quad \text{for any } h>0.
\ee
%
On the other hand, by the direct calculation, $C_{k,\ell}$ in \eqref{FDMs:u:interior} also satisfies that
\be \label{Ckl:sum}
\sum_{k,\ell=-1}^1 C_{k,\ell}=0, \quad \text{for any } h>0.
\ee
%
%

According to \cite{LiZhang2020}, an M-matrix is a square matrix with positive diagonal entries, non-positive off-diagonal entries, and non-negative row sums for all rows, with at least one row sum strictly positive. So
the sign condition \eqref{M:Matrix}  and summation condition \eqref{Ckl:sum} with the Dirichlet boundary condition $u=g$ on $\partial \Omega$ indicate that \eqref{FDMs:u:interior} yields an M-matrix for any mesh size $h$. 


\textbf{Step 3 (construct the comparison function):}
	We define that
\be\label{L:tilde}
	\mathcal{\tilde{L}}_h:=	-\mathcal{L}_h, \qquad  \theta(x,y):=(x-a_\epsilon)^2+(y-b_\epsilon)^2,
\ee
where $\theta(x,y)$ is the comparison function. 
Then
\[
	\mathcal{\tilde{L}}_h(\theta)_{i,j} =-\frac{1}{h^2}\sum_{k,\ell=-1}^1 C_{k,\ell} \theta_{i+k,j+\ell}=-\frac{1}{h^2}\sum_{k,\ell=-1}^1 C_{k,\ell} \theta(x_i+kh,y_j+\ell h), \quad (x_i,y_j)\in \Omega.
\]
By the direct calculation, 
%
\be\label{L:tilde:2}
\mathcal{\tilde{L}}_h(\theta)_{i,j}=\sum_{p=0}^6 \phi_ph^p, \quad \text{for any }  h>0 \text{ and } (x_i,y_j)\in \Omega,
\ee
where 
%
\begin{align}
	&\phi_0=12(a_\epsilon^2 - a_\epsilon x_i + b_\epsilon^2 - b_\epsilon y_j + 2), \notag\\
	&\phi_1=6(a_\epsilon + b_\epsilon)(a_\epsilon^2 - a_\epsilon x_i + b_\epsilon^2 - b_\epsilon y_j + 2), \notag\\
	&\phi_2=(21a_\epsilon^4 + (30b_\epsilon - 21 x_i)a_\epsilon^3 + (42b_\epsilon^2 - (30 x_i + 21 y_j)b_\epsilon + 52)a_\epsilon^2 \notag \\
	&\qquad + (30b_\epsilon^3 - (21 x_i + 30 y_j)b_\epsilon^2 + 60b_\epsilon)a_\epsilon + 21b_\epsilon^4 - 21 y_jb_\epsilon^3 + 52b_\epsilon^2)/10,	\notag\\
	&\phi_3=(11a_\epsilon^5 + (21b_\epsilon - 11 x_i)a_\epsilon^4 + (32b_\epsilon^2 - 21b_\epsilon x_i - 11b_\epsilon y_j + 32)a_\epsilon^3\notag \\
	& \qquad  + (32b_\epsilon^3 - 21b_\epsilon^2 x_i - 21b_\epsilon^2 y_j + 52b_\epsilon)a_\epsilon^2 + (21b_\epsilon^4 - 11b_\epsilon^3 x_i - 21b_\epsilon^3 y_j + 52b_\epsilon^2)a_\epsilon \notag \\
	& \qquad+ 11b_\epsilon^5 - 11 y_jb_\epsilon^4 + 32b_\epsilon^3)/20, \notag \\
	&\phi_4=(14a_\epsilon^6 + (33b_\epsilon - 14 x_i)a_\epsilon^5 + (56b_\epsilon^2 - 33b_\epsilon x_i - 14b_\epsilon y_j + 47)a_\epsilon^4 + (66b_\epsilon^3 - 42b_\epsilon^2 x_i \notag \\
&\qquad - 33b_\epsilon^2 y_j + 96b_\epsilon)a_\epsilon^3 + (52b_\epsilon^4 - 33b_\epsilon^3 x_i - 42b_\epsilon^3 y_j + 126b_\epsilon^2)a_\epsilon^2 + (33b_\epsilon^5 - 10b_\epsilon^4 x_i \notag \\
&\qquad - 33b_\epsilon^4 y_j + 96b_\epsilon^3)a_\epsilon + 10b_\epsilon^6 - 10 y_jb_\epsilon^5 + 39b_\epsilon^4)/120, \notag	\\
&	\phi_5=(5a_\epsilon^7 + (14b_\epsilon - 5 x_i)a_\epsilon^6 + (26b_\epsilon^2 - 14b_\epsilon x_i - 5b_\epsilon y_j + 19)a_\epsilon^5 + (36b_\epsilon^3 - 21b_\epsilon^2 x_i  \notag \\
&\qquad - 14b_\epsilon^2 y_j + 47b_\epsilon)a_\epsilon^4 + (31b_\epsilon^4 - 22b_\epsilon^3 x_i - 21b_\epsilon^3 y_j + 74b_\epsilon^2)a_\epsilon^3 + (22b_\epsilon^5 - 10b_\epsilon^4 x_i\notag \\
&\qquad  - 22b_\epsilon^4 y_j + 76b_\epsilon^3)a_\epsilon^2 + (10b_\epsilon^6 - 10b_\epsilon^5 y_j + 39b_\epsilon^4)a_\epsilon + 9b_\epsilon^5)/240, \notag\\
	&\phi_6=a_\epsilon(7a_\epsilon + b_\epsilon)(5a_\epsilon^3 + 9a_\epsilon^2b_\epsilon + 12a_\epsilon b_\epsilon^2 + 10b_\epsilon^3)(a_\epsilon + b_\epsilon)/480.\notag
\end{align}
%
%
%
As $0<x_i<1$, $0<y_j<1$, $1\le a_\epsilon$, and $1\le b_\epsilon$, we infer that
%
\be\label{psik}
\phi_k\ge \psi_k,\qquad k=0,\dots, 5, \quad \text{and} \quad \phi_6\ge 0,
\ee
where 
%
%
\begin{align}
&\psi_0=12(a_\epsilon^2 - a_\epsilon  + b_\epsilon^2 - b_\epsilon + 2), \notag\\
&\psi_1=6(a_\epsilon + b_\epsilon)(a_\epsilon^2 - a_\epsilon + b_\epsilon^2 - b_\epsilon + 2), \notag\\
&\psi_2=(21a_\epsilon^4 + (30b_\epsilon - 21)a_\epsilon^3 + (42b_\epsilon^2 - 51 b_\epsilon + 52)a_\epsilon^2 + (30b_\epsilon^2 - 51 b_\epsilon + 60)a_\epsilon b_\epsilon \notag\\
& \qquad + (21b_\epsilon^2 - 21 b_\epsilon + 52)b_\epsilon^2)/10, \notag\\
&	\psi_3=(11a_\epsilon^5 + (21b_\epsilon - 11)a_\epsilon^4 + (32b_\epsilon^2 - 32b_\epsilon + 32)a_\epsilon^3 + (32b_\epsilon^2 - 42b_\epsilon  + 52)a_\epsilon^2b_\epsilon  \notag\\
&\qquad  + (21b_\epsilon^2 - 32b_\epsilon + 52)a_\epsilon b_\epsilon^2 + (11b_\epsilon^2 - 11 b_\epsilon + 32)b_\epsilon^3)/20,\notag\\
&	\psi_4=(14a_\epsilon^6 + (33b_\epsilon - 14)a_\epsilon^5 + (56b_\epsilon^2 - 47b_\epsilon  + 47)a_\epsilon^4 + (66b_\epsilon^2 - 75b_\epsilon  + 96)a_\epsilon^3b_\epsilon \notag\\ 
&\qquad + (52b_\epsilon^2 - 75b_\epsilon  + 126)a_\epsilon^2b_\epsilon^2 + (33b_\epsilon^2 - 43b_\epsilon  + 96)a_\epsilon b_\epsilon^3 + (10b_\epsilon^2 - 10 b_\epsilon + 39)b_\epsilon^4)/120, \notag\\
&	\psi_5=(5a_\epsilon^7 + (14b_\epsilon - 5 )a_\epsilon^6 + (26b_\epsilon^2 - 19b_\epsilon + 19)a_\epsilon^5 + (36b_\epsilon^2 - 35b_\epsilon + 47)a_\epsilon^4b_\epsilon  \notag\\
&\qquad + (31b_\epsilon^2 - 43b_\epsilon + 74)a_\epsilon^3b_\epsilon^2 + (22b_\epsilon^2 - 32b_\epsilon+ 76)a_\epsilon^2b_\epsilon^3  + (10b_\epsilon^2 - 10b_\epsilon + 39)a_\epsilon b_\epsilon^4 + 9b_\epsilon^5)/240.\notag
\end{align}
%
%
%
%
Utilizing $1\le a_\epsilon$, $1\le b_\epsilon$ and the simple fact:  $\mu_2 b_\epsilon^2 +\mu_1b_\epsilon + \mu_0>0$ for any $b_\epsilon \in \R$ if  $\mu_2>0$ and $\mu_1^2-4\mu_2\mu_0<0$, we deduce
%
%
\be\label{positive}
\psi_0 \ge 24, \quad \text{and} \quad	\psi_k \ge 0,\qquad k=1,\dots, 5.
\ee
%
Based on \eqref{L:tilde:2}--\eqref{positive} 
\be\label{greater:than:24}
	\mathcal{\tilde{L}}_h(\theta)_{i,j}=	\sum_{p=0}^6 \phi_ph^p\ge 	\sum_{p=0}^5 \psi_ph^p +\phi_6h^6 \ge 24, \quad \text{for any }  h>0 \text{ and } (x_i,y_j)\in \Omega.
\ee
%	
%

\textbf{Step 4 (the sixth-order convergence rate):}
From $\Omega=(0,1)^2$ and \eqref{xiyj}, 
we define 
\[
\begin{split}
& \Omega_h:=\{(x_i,y_j):\ (x_i,y_j) \in \Omega\}, \qquad \overline{\Omega}_h:=\{(x_i,y_j):\ (x_i,y_j) \in \overline{\Omega}\}, \qquad \partial \Omega_h:=\overline{\Omega}_h \cap \partial \Omega,\\
& V(\overline{\Omega}_h):=\{(v)_{i,j}=v(x,y)|_{(x,y)=(x_i,y_j)}\in \mathbb{R}:\  (x_i,y_j) \in \overline{\Omega}\}. 
\end{split}
\]
%
Now the Dirichlet boundary condition $u=g$ on $\partial \Omega$, $\mathcal{L}_h$ in \eqref{FDMs:u:interior}, and $\mathcal{\tilde{L}}_h$ in \eqref{L:tilde} imply that our proposed FDM can be rewritten as: find $u_h \in
V(\overline{\Omega}_h)$ such that:
\be\label{DeltahuhF}
\mathcal{\tilde{L}}_h (u_h)_{i,j}=-F_{i,j}
 \quad \mbox{for}\quad (x_i,y_j)\in \Omega_h \quad\mbox{with}\quad u_h=g\quad \mbox{on}\quad
\partial \Omega_h.
\ee
%%
%%
%
According to \eqref{M:Matrix} and \eqref{Ckl:sum},
 the discrete maximum principle: 
%
\be\label{max:principle} 
\max_{(x_i,y_j)\in \Omega_h} v(x_i,y_j)\le \max_{(x_i,y_j)\in \partial \Omega_h} v(x_i,y_j), \quad \text{if} \quad \mathcal{\tilde{L}}_h v\ge 0 \ \text{in} \ \Omega_h, \ \text{for any} \ v\in V(\overline{\Omega}_h),
\ee
%
is proved by contradiction in the following \eqref{vmn:assume}--\eqref{max:prin:proof}:
%%%%%%%%%%%%%%
Suppose that $\max\limits_{(x_i,y_j)\in \Omega_h} (v)_{i,j}> \max\limits_{(x_i,y_j)\in \partial \Omega_h} (v)_{i,j}$.
So we assume that
\be\label{vmn:assume}
(v)_{m,n}= v(x_m,y_n)=\max\left\{ v(x_i,y_j) :  (x_i,y_j)\in \Omega_h\right\}.
\ee
From  \eqref{Ckl:sum}
%
\[
\sum_{k,\ell\in\{-1,0,1\} \atop k\ne 0, \  \ell\ne 0} -C_{k,\ell} =  C_{0,0}.
\]
%
By \eqref{M:Matrix} 
\[
-C_{k,\ell}\ge  0 \quad \text{if} \quad (k,\ell)\ne (0,0), \quad \text{and} \quad  C_{0,0}>  0.
\]
%
%
%
Then
\be\label{Ckl:sign:ineq:1}
\sum_{k,\ell\in\{-1,0,1\} \atop k\ne 0, \  \ell\ne 0} -C_{k,\ell} (v)_{m+k,n+\ell} \le C_{0,0} (v)_{m,n}.
\ee
%%
Based on  $\mathcal{\tilde{L}}_h v\ge 0$ in $\Omega_h$, and the definition of $\mathcal{\tilde{L}}_h$ in \eqref{L:h:u:1} and \eqref{L:tilde}, we demonstrate that 
%
\be\label{Ckl:sign:ineq:2}
0\le h^2(\mathcal{\tilde{L}}_h v)_{m,n}=-\sum_{k,\ell =-1}^1 C_{k,\ell} (v)_{m+k,n+\ell}=-C_{0,0} (v)_{m,n}-\sum_{k,\ell\in\{-1,0,1\} \atop k\ne 0, \  \ell\ne 0} C_{k,\ell} (v)_{m+k,n+\ell}.
\ee
Now, \eqref{Ckl:sign:ineq:1} and \eqref{Ckl:sign:ineq:2} result in
%
\be\label{max:prin:proof}
C_{0,0} (v)_{m,n}\le \sum_{k,\ell\in\{-1,0,1\} \atop k\ne 0, \  \ell\ne 0} -C_{k,\ell} (v)_{m+k,n+\ell} \le C_{0,0} (v)_{m,n}.
\ee
%
Equality holds throughout and $v$ attains the maximum value at all its nearest neighbors of $(x_m,y_n)$. Applying the same argument to the neighbors in $\Omega_h$ and repeat this argument, we  can say that $v$ must be a constant which  contradicts \eqref{vmn:assume}.
So \eqref{vmn:assume}--\eqref{max:prin:proof} prove the discrete maximum principle \eqref{max:principle}.
%%%%%%%%%%%%%%%%%	




 \eqref{truncation:error:h:6} and the defined $\mathcal{\tilde{L}}_h$ in  \eqref{L:tilde} indicate
	%
	%
	%
	%
	\be\label{Rxiyj}
	\mathcal{\tilde{L}}_h 	(u)_{i,j}=-F_{i,j}+R_{i,j}, \quad \text{with} \quad	|R_{i,j}|\le
	c_3 h^6,  \quad \text{for any }  h>0 \text{ and } (x_i,y_j)\in \Omega_h, 
	\ee
	%
	%
	%
	where $R_{ij}$ is the truncation error of $	\mathcal{\tilde{L}}_h 	(u)_{i,j}$ at the grid point $(x_i,y_j)\in \Omega_h$ and $0<c_3$ is independent of $h$. It is clear from \eqref{DeltahuhF} that   
%
	\be\label{intersect:trunR}
\mathcal{\tilde{L}}_h 	(u- u_h)_{i,j}=R_{i,j} \quad \mbox{for}\quad (x_i,y_j)\in \Omega_h \quad \mbox{with}\quad (u- u_h)_{i,j}=0\quad \mbox{for}\quad (x_i,y_j)\in \partial \Omega_h.
	\ee
	%
	%
From \eqref{greater:than:24}, and $c_3>0$ in \eqref{Rxiyj}, we observe that
	%
	%
	\be\label{4CH6}
	\tfrac{1}{24}c_3h^6(\mathcal{\tilde{L}}_h  \theta)_{i,j}\ge 	
	c_3 h^6,\quad \text{for any }  h>0 \text{ and } (x_i,y_j)\in \Omega_h.
	\ee
	%
	Let  
	\[
	(E_h)_{i,j}:= u(x_i,y_j)-(u_h)_{i,j} \quad \text{with} \quad(x_i,y_j)\in \overline{\Omega}_h. 
	\]
	Then
	\be\label{Eh:bd}
		(E_h)_{i,j}=0 \quad \text{for} \quad (x_i,y_j)\in \partial\Omega_h. 
	\ee
	%
	%
	It follows from \eqref{intersect:trunR}  that
	%
	%
	\be\label{order6:proof:compare}
	\begin{split}
	(\mathcal{\tilde{L}}_h  (E_h+	\tfrac{1}{24} c_3 h^6 \theta))_{i,j}
	&=(\mathcal{\tilde{L}}_h  E_h)_{i,j}+	\tfrac{1}{24} c_3 h^6 (\mathcal{\tilde{L}}_h  \theta)_{i,j}\\
	&= R_{i,j}+	\tfrac{1}{24} c_3 h^6 (\mathcal{\tilde{L}}_h  \theta)_{i,j}, \quad \text{for any }  h>0 \text{ and } (x_i,y_j)\in \Omega_h.
	\end{split}
	\ee
	%	
	%
According to \eqref{Rxiyj}, \eqref{4CH6}, and \eqref{order6:proof:compare},
	\be\label{L:h:E:theta}
	(\mathcal{\tilde{L}}_h  (E_h+	\tfrac{1}{24} c_3 h^6 \theta))_{i,j}\ge 0, \quad \text{for any }  h>0 \text{ and } (x_i,y_j)\in \Omega_h.
	\ee
	%
	Recall the definition of the comparison function $\theta$ in \eqref{L:tilde} with $a_\epsilon,b_\epsilon \ge 1$ and $\Omega=(0,1)^2$, $\theta$ satisfies
	\be \label{theta:max}
	0\le \theta \le a_\epsilon^2+b_\epsilon^2 \quad \text{on} \quad \overline{\Omega}_h.
	\ee
	%%
	As $c_3> 0$  in \eqref{Rxiyj}, 
	\[
		\max_{(x_i,y_j)\in \Omega_h} (E_h)_{i,j}
	\le
	\max_{(x_i,y_j)\in \Omega_h} (E_h+	\tfrac{1}{24} c_3 h^6 \Theta)_{i,j}.
	\]
	\eqref{max:principle}, \eqref{L:h:E:theta}, and $c_3>0$ yield
	\[
	\max_{(x_i,y_j)\in \Omega_h} (E_h)_{i,j} \le 	\max_{(x_i,y_j)\in \partial \Omega_h} (E_h+	\tfrac{1}{24} c_3 h^6 \theta)_{i,j}\le \max_{(x_i,y_j)\in \partial \Omega_h} (E_h)_{i,j}+
	\tfrac{1}{24} c_3 h^6 \times \max_{(x_i,y_j)\in \partial \Omega_h}(\theta)_{i,j}.
	\] 
%
We infer from \eqref{Eh:bd} and \eqref{theta:max} that	
	\[
		\max_{(x_i,y_j)\in \Omega_h} (u-u_h)_{i,j} \le Ch^6, \quad \text{with} \quad 	C=\frac{a_\epsilon^2+b_\epsilon^2}{24}  c_3, \quad \text{for any }  h>0.
	\]
Apply the similar technique to $-E_h$, we finally prove \eqref{convergence:order:6}.
%
	%
\end{proof}
