	\subsection{The sixth-order FDM for \bm{$a\le b $}}\label{sec:case2}
Similar to  \cref{theorem:interior}, we construct the sixth-order 9-point compact FDM for the model problem \eqref{Model:Original} with $a\le b $ in this section. By our calculation, we observe that $c_{k,\ell,p}$ with $p=0,\dots,3$ and $a\le b $ are exactly the same as those in \eqref{c:h:0}--\eqref{c:h:3}. So, we only provide the following notations for the simplification:\\
%
%
\textbf{coefficients of $h^4$ of the  LHS of the FDM:}
%
\begin{align}\label{case2:p:4}
	& c_{-1, -1, 4} := -(9 a_\epsilon ^4 + 40 a_\epsilon ^3 b_\epsilon   + 60 a_\epsilon ^2 b_\epsilon ^2  + 40 a_\epsilon b_\epsilon ^3   + 11 b_\epsilon ^4)/240, \notag \\
	& c_{-1, 0, 4} := -(21 a_\epsilon ^4 + 43  a_\epsilon ^3 b_\epsilon  + 33 a_\epsilon ^2  b_\epsilon ^2 + 13 a_\epsilon b_\epsilon ^3   + 2 b_\epsilon ^4)/120 ,    \notag \\
	&c_{-1, 1, 4} := -(9 a_\epsilon ^4 +  b_\epsilon ^4)/240, \quad c_{0, -1, 4} := -(13 a_\epsilon ^3 b_\epsilon   + 33 a_\epsilon ^2 b_\epsilon ^2  + 43 a_\epsilon b_\epsilon ^3   + 23 b_\epsilon ^4)/120 ,\\
	& c_{0, 0, 4} := (9a_\epsilon ^4  + 13 b_\epsilon ^4 )/40+ 4 a_\epsilon ^2 b_\epsilon ^2 /5+ 19 (a_\epsilon ^3 b_\epsilon    +a_\epsilon b_\epsilon ^3 ) /30 ,\quad c_{0, 1, 4} := 0,  \notag \\
	& c_{1, -1, 4} :=  (a_\epsilon ^4 - 11 b_\epsilon ^4)/240,\quad  c_{1, 0, 4} :=  (a_\epsilon ^4 -  b_\epsilon ^4)/60, \quad c_{1, 1, 4} :=  (a_\epsilon ^4 -  b_\epsilon ^4)/240,  \notag
\end{align}
%
%
\textbf{coefficients of $h^5$ of the  LHS of the FDM:}
%
\begin{align}\label{case2:p:5}
	& c_{-1, -1, 5} := - a_\epsilon b_\epsilon  r_1 ( a_\epsilon ^2 +  a_\epsilon  b_\epsilon  +  b_\epsilon ^2)/24, \notag \\
	& c_{-1, 0, 5} := -(11 a_\epsilon ^5 +5 a_\epsilon ^4 b_\epsilon  +25 a_\epsilon ^3 b_\epsilon ^2 +10 a_\epsilon ^2 b_\epsilon ^3 +21 b_\epsilon ^5)/240, \quad c_{-1, 1, 5} := 0, \notag \\
	& c_{0, -1, 5} := r_1(    5 b_\epsilon -a_\epsilon )( 2a_\epsilon ^3 - 6a_\epsilon ^2  b_\epsilon  +  a_\epsilon  b_\epsilon ^2 - 6 b_\epsilon ^3)/240, \\
	& c_{0, 0, 5} := (18 a_\epsilon ^5 - 29  a_\epsilon ^4 b_\epsilon + 65a_\epsilon ^3  b_\epsilon ^2 + 45 a_\epsilon ^2 b_\epsilon ^3 + 19 a_\epsilon  b_\epsilon ^4 + 86 b_\epsilon ^5)/240, \notag \\
	& c_{0, 1, 5} := 	4\beta, \quad  c_{1, -1, 5} := 	\beta, \quad c_{1, 0, 5} := 	4\beta, \quad c_{1, 1, 5} := 	\beta,\notag
\end{align}
where
\[
\beta:= r_1( b_\epsilon  -  a_\epsilon )( a_\epsilon ^3 - 6 a_\epsilon ^2 b_\epsilon  + 2 a_\epsilon  b_\epsilon ^2 - 7 b_\epsilon ^3)/480,
\]
%
\textbf{coefficients of $h^6$ of the  LHS of the FDM:}
%
\begin{align}\label{case2:p:6}
	& c_{-1, -1, 6} := (-20 a_\epsilon ^6  +63 a_\epsilon ^5 b_\epsilon   + 2 a_\epsilon ^4 b_\epsilon ^2 - 199 a_\epsilon ^3 b_\epsilon ^3 - 96 a_\epsilon ^2 b_\epsilon ^4 - 188 a_\epsilon  b_\epsilon ^5 - 210 b_\epsilon ^6)/1920, \notag \\
	&  c_{-1, 0, 6} := 0, \quad c_{-1, 1, 6} := (-5 a_\epsilon ^5 b_\epsilon  + 22 a_\epsilon ^4 b_\epsilon ^2 - 27 a_\epsilon ^3 b_\epsilon ^3 - 16 a_\epsilon ^2 b_\epsilon ^4 - 4 a_\epsilon  b_\epsilon ^5 - 42 b_\epsilon ^6)/1920, \notag \\
	&  c_{0, -1, 6} := (5 a_\epsilon ^6 - 27 a_\epsilon ^5 b_\epsilon  + 49 a_\epsilon ^4 b_\epsilon ^2 - 11 a_\epsilon ^3 b_\epsilon ^3 - 12 a_\epsilon ^2 b_\epsilon ^4 + 38 a_\epsilon  b_\epsilon ^5 - 42 b_\epsilon ^6)/480,  \\
	&c_{0, 0, 6} :=\lambda/96,\quad  c_{0, 1, 6} :=-\lambda/480, \quad  c_{1, -1, 6} :=-\lambda/1920, \quad  c_{1, 0, 6} :=-\lambda/480, \notag \\
	&  c_{1, 1, 6} :=-\lambda/1920, \notag  
\end{align}
%
where
%
\[
\lambda:=5 a_\epsilon ^5 b_\epsilon  - 22 a_\epsilon ^4 b_\epsilon ^2 + 27 a_\epsilon ^3 b_\epsilon ^3 + 16 a_\epsilon ^2 b_\epsilon ^4 + 4 a_\epsilon  b_\epsilon ^5 + 42 b_\epsilon ^6, 
\]
%
\textbf{the  RHS of the FDM:}
%
\be
\begin{split}\label{case2:Fij}
	F_{i,j}	&:=6f_\epsilon+3h	r_{1} f_\epsilon + h^2 ((21r_2 + 30r_3)f_\epsilon/20 - 	\bv \cdot \nabla f_\epsilon/2 + \Delta f_\epsilon/2) \\
	& \qquad +{h^3r_{1}}	((11 r_2/40 + r_3/4 ) f_{_\epsilon} -  (	\bv \cdot \nabla f_{_\epsilon} - \Delta f_{_\epsilon})/4)\\
	&\qquad + h^4 ( r_{14} f_\epsilon  +r_{5} f_{_\epsilon}^{(1, 0)}  +r_{6} f_{_\epsilon}^{(0, 1)}+r_{7} f_{_\epsilon}^{(2, 0)}+ r_{3}  f_{_\epsilon}^{(1, 1)}/15+ r_{8} f_{_\epsilon}^{(0, 2)}-  2\zeta )\\
	&\qquad + h^5 (  r_{15} f_\epsilon +r_{10} f_{_\epsilon}^{(1, 0)}  +r_{11} f_{_\epsilon}^{(0, 1)}+r_{12} f_{_\epsilon}^{(2, 0)}+ r_{1}r_{3}  f_{_\epsilon}^{(1, 1)}/30+ r_{13} f_{_\epsilon}^{(0, 2)} \\
	&\quad \qquad \quad -  r_{1}\zeta+ r_{1}( \Delta^2  f_{_\epsilon} +2f_{_\epsilon}^{(2, 2)} )/120),
\end{split}	
\ee
%
%
%	
%
where $r_1,\dots r_{15}, \bv,  \zeta $ are defined in \eqref{r1:r15}, \eqref{zeta}, and each $f_\epsilon^{(m,n)}$ is defined in \eqref{fmn}.
%
%
\begin{theorem}\label{theorem:2:interior} Assume that the solution $u$, the source term $f$ and the constant coefficient $(a,b)$ of \eqref{Model:Original} satisfy that $u\in C^8(\overline{\Omega})$, $f\in C^6(\overline{\Omega})$, $a\le b$. Let the grid point $(x_i,y_j)\in \Omega$ and define the following 9-point compact FDM:
	%%
	%
	\be\label{FDMs:2:u:interior}
	\mathcal{L}_h (u_h)_{i,j} :=\frac{1}{h^2}\sum_{k,\ell=-1}^1 C_{k,\ell} (u_h)_{i+k,j+\ell}=F_{i,j}\Big|_{(x,y)=(x_i,y_j)} \quad \text{with} \quad C_{k,\ell}:=\sum_{p=0}^6 c_{k,\ell ,p}h^p,
	\ee
	%
	where $c_{k,\ell,p}$ is defined in \eqref{c:h:0}--\eqref{c:h:3}, \eqref{case2:p:4}--\eqref{case2:p:6} and $F_{i,j}$ is defined in \eqref{case2:Fij}. Then
	%
	\[
	C_{k,\ell}\le  0 \quad \text{if} \quad (k,\ell)\ne (0,0), \quad   C_{0,0}>  0, \quad  \text{for any mesh size } h>0, \quad \text{and} \quad \sum_{k,\ell=-1}^1 C_{k,\ell}=0.
	\]
	%
	%
	Furthermore,   $\mathcal{L}_h (u_h)_{i,j}$ in \eqref{FDMs:2:u:interior} with $u=g$ on $\partial \Omega$  forms an M-matrix for any mesh size $h$,  and
	\[
	\|u-u_h\|_{\infty}\le Ch^6, \quad  \text{for any mesh size } h>0,
	\]
	where  $C$ is independent of $h$.
\end{theorem}
%
%
\begin{proof}
Similar to the proof of \cref{theorem:interior}, so we omit the proof.
\end{proof}
