\appendixproof{lemma:local_clonable_characterisation}{localclonablecharacterisation}{
\begin{proof}
    $(\Rightarrow) \colon$
    Let $(\Gamma', \chi')$ be a \drawing{\ell} in general position obtained from $(\Gamma, \chi)$ by cloning $v$ into the cell $C_{\Gamma, S}(v)$; call the clone $w$.
    Applying \obsref{obs:drawing_maps_clones_in_set} for all distinct $a, b \in N_G(v)$ where $\chi(va) = \chi(vb)$ yields
    \begin{equation*}
        \Gamma'(w) \in \bigcap_{\substack{a, b \in N_G(v), a \neq b, \\ \chi(va) = \chi(vb)}} T_{\Gamma}(v, a, b) \cup H_{\Gamma}(v, a, b).
    \end{equation*}
    Observe that $H_{\Gamma}(v, a, b) \cap C_{\Gamma, S}(v) = \emptyset$ for all distinct $a, b \in N_G(v)$. Hence, using $\Gamma'(w) \in C_{\Gamma, S}(v)$,
    \begin{equation*}
        \Gamma'(w) \in \bigcap_{\substack{a, b \in N_G(v), a \neq b, \\ \chi(va) = \chi(vb)}} T_\Gamma(v, a, b) = A_{\Gamma, \chi}(v).
    \end{equation*}
    Therefore, $A_{\Gamma, \chi}(v) \neq \emptyset$.

    $(\Leftarrow) \colon$
    Assume $A_{\Gamma,\chi}(v) \neq \emptyset$.
    We find a suitable position to insert a clone of $v$ as follows:
First, we find an open disk $D_1 \subseteq C_{\Gamma, S}(v)$ with center $\Gamma(v)$ and positive radius.
Next, we find the region $B$ (see \obsref{lemma:global_crossing_free_region}) where $v$ can be moved without introducing monochromatic crossings, and use $\Gamma(v) \in B$ together with the fact that $B$ is open (\obsref{lemma:global_crossing_free_region}) to find an open disk $D_2 \subseteq B$ with positive radius and center $\Gamma(v) \in B$.
The set $D \coloneqq D_1 \cap D_2$ is again an open disk with positive radius and center $\Gamma(v)$.
Observe that $A_{\Gamma, \chi}(v)$ forms a ``tie''-shape with center $\Gamma(v)$ as it is a non-empty intersection of ``tie''-shapes of center $\Gamma(v)$.
Hence, there is $x \in D \cap A_{\Gamma, \chi}(v)$ and clearly we can also assume that $\Set{x} \cup \Gamma(V(G))$ is again in general position.

To construct the required drawing, we clone $v$ and insert the clone, call it $w$, at position~$x$.
Because $x \in D_1$, $w$ is inserted into the required cell $C_{\Gamma, S}(v)$.
Because $x \in D_2$ and \obsref{lemma:global_crossing_free_region}, the edges incident to $w$ do not create monochromatic crossings with edges not incident to $v$ in the original drawing.
An edge that is the only one of its color incident to $w$ cannot create a crossing with any edge incident to $v$.
For colors that have two (or more) edges incident to $w$ we cannot get monochromatic crossings with the edges incident to $v$ due to $x \in A_{\Gamma, \chi}(v)$ and \obsref{obs:drawing_maps_clones_in_set}.
Clearly, the edges incident to $w$ in the new drawing also do not create monochromatic crossings with themselves.
Hence, in total, the new drawing satisfies the conditions of this lemma.
\qed\end{proof}
} %

\paragraph{Deriving the Kernel.}


Using Theorem 28.1.1 of the Handbook of Discrete and Computational Geometry \cite{GeometryHandbook} to bound the number of distinct cells in a drawing, we have all prerequisites to derive a kernel parameterized by the vertex cover number plus the number of colors, $\ell$:


\begin{restatable}{lemma}{geomthicknessfptbyvcplusl}\label{lemma:geom_thickness_fpt_by_vc_plus_l}
\probname{Geometric Thickness} parameterized by $\ell + k$, where $k$ denotes the vertex cover number of the input graph and $\ell$ the number of allowed colors in the drawing, admits a problem kernelization mapping each instance $I = (G, \ell)$ to an equivalent instance $I' = (G^*, \ell)$ where $\Size{V(G^*)} = \ell^{\BigO{k}}$.
\end{restatable}
\ifshort



\fi

\appendixproof{lemma:geom_thickness_fpt_by_vc_plus_l}{geomthicknessfptbyvcplusl}{
\begin{proof}
Let $I = (G, \ell)$ be an instance of \probname{Geometric Thickness} and let $S \subseteq V(G)$ be a vertex cover of $G$ of size $k'\leq 2k$ computed, e.g., via the standard 2-approximation algorithm. 
For two vertices $u$, $v$ in $V(G)\setminus S$, we define the equivalence relation $\sim$ where $u \sim v$ if and only if $N_G(u) = N_G(v)$.
The kernel $G^*$ is obtained by applying the following data reduction rule exhaustively:

If there is a vertex $v \in V(G) \setminus S$
whose equivalence class w.r.t.\ $\sim$ (written as $[v]_\sim$) exceeds a size of  
$\ell^{k'} ( \frac{{k'}^2+k'+2}{2} + 1 )$ vertices,
delete $v$ from $G$.

Clearly, the kernel can be computed in polynomial time and \textsc{GT} is decidable since it is in $\exists\mathbb{R}$~\cite{ForsterKMPTV24}. As there are at most $2^{k'}$ equivalence classes w.r.t.\ $\sim$ in $G$ and in the reduced instance, each class has at most $\BigO{\ell^{k'} {k'}^2}$ vertices, the kernel has $\BigO{ 2^{k'} \ell^{k'} {k'}^2} = \ell^{\BigO{k}}$ vertices in total.

It remains to show that the kernelization is \emph{correct}, that is, $I$ is a positive instance of \probname{Geometric Thickness} if and only if $I'$ is a positive instance of \probname{Geometric Thickness}.
For this it suffices to show that the reduction rule is \emph{safe}, that is,
an application of the rule does not change the outcome of an instance.
Let $x$ be a vertex deleted by the rule acting on the instance $(G, \ell)$, producing the instance $(G', \ell)$.
We show that $(G, \ell)$ is a positive instance if and only if $(G', \ell)$ is one:

$(\Rightarrow) \colon$ Clearly, in any \drawing{\ell}, deleting a vertex does not introduce new crossings, hence, the reduced instance is positive as well.

$(\Leftarrow) \colon$
Let $(\Gamma', \chi')$ be a \drawing{\ell} of $G'$ in general position.
Observe that $[x]_\sim \cap V(G')$ has size at least $\ell^{k'} ( \frac{{k'}^2+k'+2}{2} + 1 )$, and that for each vertex in $[x]_\sim \cap V(G')$, the vertex has at most $k'$ incident edges in $G'$, hence its edges can be colored in at most $\ell^{k'}$ ways. Thus, by the pigeonhole principle, there is a set $C \subseteq [x]_\sim \cap V(G')$ of pairwise clones in $(\Gamma', \chi')$ of size at least $\frac{{k'}^2+k'+2}{2} + 1$ all equivalent to $x$ with respect to $\sim$.

By Theorem 28.1.1 in \cite{GeometryHandbook}, there are at most $\frac{{k'}^2+k'+2}{2}$ distinct cells induced by $S$ in $\Gamma'$.
Hence, by the pigeonhole principle, there are distinct $c_1, c_2 \in C$ with $C_{\Gamma', S}(c_1) = C_{\Gamma', S}(c_2)$.
Thus, $c_2$ is a witness certifying that $c_1$ can be cloned into their shared cell in the drawing $(\Gamma'', \chi'')$ obtained from $(\Gamma', \chi')$ by deleting $c_2$.
Hence, by \cref{lemma:local_clonable_characterisation}, $A_{\Gamma'', \chi''}(c_1) \neq \emptyset$.
Towards a contradiction, suppose $A_{\Gamma', \chi'}(c_1) = \emptyset$. Then, since $c_1$ and $c_2$ are not neighbors in $G'$, $A_{\Gamma'', \chi''}(c_1) = \emptyset$, a contradiction.
Therefore, $A_{\Gamma', \chi'}(c_1) \neq \emptyset$ and we can apply \cref{lemma:local_clonable_characterisation} to $(\Gamma', \chi')$ and $c_1$ and obtain the desired \drawing{\ell} of $G$.
\qed\end{proof}
} %

\cref{thm:fptvcn} now follows directly from \cref{lemma:geom_thickness_fpt_by_vc_plus_l} in combination with the previously established fact that the geometric thickness $\ell$ is upper-bounded by $\lceil \frac{k}{2}\rceil$ in the class of graphs of treewidth at most $k$ (which also contains all graphs of vertex cover number $k$)~\cite{DujmovicW07}.

\fptvcn*

