  \centering
  \includegraphics[width=.9\columnwidth,trim={0 0 0 0},clip=false]{diffusionflow_col.pdf}
  \caption{Schematic representation of the \gls*{dansep} diffusion flow mechanism in a topology-unconstrained \gls*{wasn} with $K=7$ nodes, pruned to a tree with root node index $k=7$. The filter $\tW^{i+1}$ is computed at the root node. The matrix $\Gkq[k][l]^{i+1}$ is the $Q\times Q$ part of $\tW^{i+1}$ applied to $\ettkq[l][k]^i$. It is sent through the branch starting at node $l$, and this is done $\forall l\in\Uk^i$. The index $n^i(q)$, necessary to define the fusion matrices via~\eqref{eq:fusionrule}, is shown for all $q\in\K\backslash\{k\}$ at the bottom of the figure.}
  \label{fig:diffusionflow}
\end{figure}

% Similarly as in \gls*{tidanse}, where fused signals from different nodes are also summed together during a fusion flow, the definition of the fusion matrices in~\eqref{eq:fused_signal_zk} must include a transformation that depends on the data at all nodes in the \gls*{wasn} to decorrelate the individual elements of the sums $\{\ettkq[q][k]^i\}_{q\in\Uk^i}$.

As detailed under~\eqref{eq:tW_partition}, for any $l\in\Uk^i$, the $Q\times Q$ filter $\Gkq[k][l]^{i+1}$ is applied by node $k$ to the sum $\ettkq[l][k]^i$ and thus to $\zkd[q]^i,\:\forall\:q\in\Ukb[l]^i\cup l$. Since $\zkd[q]^i = \Pk[q]^{i,\Her}\yk[q]$ according to~\eqref{eq:fused_signal_zk}, we can instead multiply the fusion matrix $\Pk[q]^i$ at node $q$ by the matrix $\Gkq[k][l]^{i+1}$. This results in the fusion matrix definition at iteration $i+1$ at all nodes in the \gls*{wasn}:

% The fusion matrices in~\eqref{eq:fused_signal_zk} at iteration $i+1$ are defined as:

\begin{equation}\label{eq:PkDef}
  \Pk[q]^{i+1} \triangleq  \Wkk[q]^{i+1}\Tk[q]^{i+1},\:\forall\:q\in\K,
\end{equation}

\noindent
with $\Wkk[q]^{i+1}$ defined in~\eqref{eq:tW_partition} and~\eqref{eq:nonupdatingnode}. The transformation matrix $\Tk[q]^{i+1}$ is recursively defined as:

\begin{equation}\label{eq:fusionrule}
  \Tk[q]^{i+1} \triangleq  \begin{cases}
    \Tk[q]^{i}\Gkq[k][n^i(q)]^{i+1}\:&\forall\:q\in\K\backslash\{k\}\\
    \I[Q]\:&\text{for $q=k$}
  \end{cases},
\end{equation}

\noindent
where node $n^i(q)$ is the child node of node $k$ that belongs to the same branch as node $q$, i.e., $n^i(q)\in\Uk^i$ and $q\in\Ukb[n^i(q)]^i$.
% index of the node in $\Uk^i$ that belongs to the same branch as $q$. %, i.e., $q\in\Ukb[n^i(q)]^i\cup \{n^i(q)\}$ and 
% If $q\in\Uk^i$, then $n^i(q) = q$, otherwise, $n^i(q)$ is a (grand-)parent node of $q$. The index $n^i(q)$ is the same for any node $q$ in the same branch, i.e., in $\Ukb[n^i(q)]^i\cup\{n^i(q)\}$. 
% The values of $n^i(q)$ for the example \gls*{wasn} of~\figref{fig:diffusionflow} are provided in the same figure.

% Based on~\eqref{eq:fusionrule}, the desired signal estimate at node $k$ at iteration $i+1$ is found to be equal to a sum of fused signals:

% \begin{align}\label{eq:eta_dhat_relation}
%   \dhatk^{i+1} &= \tW^{i+1,\Her}\ty^{i}\\
%   &= \Wkk^{i+1,\Her}\yk + \sum_{q\in\Uk^i}\Gkq^{i+1,\Her}\zkd[q]^{i}\\
%   &= \Wkk^{i+1,\Her}\yk + \sum_{q\in\Uk^i} \Gkq^{i+1,\Her}\Pk[q]^{i,\Her}\yk[q]\\
%   &= \Pk^{i+1,\Her}\yk + \sum_{q\in\Uk^i} \Pk[q]^{i+1,\Her}\yk[q]\\
