\subsection{Convergence and Optimality}\label{subsec:convergence}

The expression for the target signal estimate at the root node in \gls*{dansep}~\eqref{eq:dansep_dhat} can be re-written using~\eqref{eq:fusionflow},~\eqref{eq:yTildeRoot},~\eqref{eq:tW_partition} and~\eqref{eq:PkDef} (the latter considering~\eqref{eq:fusionrule} in the case $q=k$) as:

\begin{align}
  \dhatk^{i+1} &= \Wkk^{i+1,\Her}\yk + \sum_{l\in\Uk^i}\Gkq[k][l]^{i+1,\Her}\ettkq[l][k]^i\\
  &= \Pk^{i+1,\Her}\yk + \sum_{l\in\Uk^i}\Gkq[k][l]^{i+1,\Her}\left(
    \zkd[l]^i + \sum_{m\in\Ukb[l]^i}\zkd[m]^i
  \right)\label{eq:rewrite_dk_eq3}\\
  &= \Pk^{i+1,\Her}\yk + \sum_{q\in\K\backslash\{k\}}\Gkq[k][n^i(q)]^{i+1,\Her}\Pk[q]^{i,\Her}\yk[q]\label{eq:rewrite_dk_eq4}\\
  &= \sum_{q\in\K}\Pk[q]^{i+1,\Her}\yk[q].\label{eq:dansep_dhat_expanded}
\end{align}

\noindent
Substituting~\eqref{eq:dansep_dhat_expanded} into~\eqref{eq:desSigEst} gives:
\begin{equation}\label{eq:desSigEst_expanded}
  \dhatk[q]^{i+1} = \left(\Tk[q]^{i+1}\right)^{-\Her}\sum_{m\in\K}\Pk[m]^{i+1,\Her}\yk[m],\:\forall\:q\in\K\backslash\{k\}.
\end{equation}

\noindent
% The equality between~\eqref{eq:rewrite_dk_eq3} and~\eqref{eq:rewrite_dk_eq4} holds since all nodes in a same branch have the same index $n^i(q)$ (as defined below~\eqref{eq:fusionrule}).
Based on~\eqref{eq:PkDef} and~\eqref{eq:desSigEst_expanded}, the network-wide \gls*{dansep} filter defined such that $\Wk[q]^{i+1,\Her}\yk[] = \dhatk[q]^{i+1}$, $\forall\:q\in\K\backslash\{k\}$, can be written as:

\begin{equation}\label{eq:nw_filter_dansep}
  \Wk[q]^{i+1} \triangleq
  \begin{bmatrix}
      \Pk[1]^{i+1}\left(\Tk[q]^{i+1}\right)^{-1}\\
      \vdots\\
      \Wkk[q]^{i+1}\\
      \vdots\\
      \Pk[K]^{i+1}\left(\Tk[q]^{i+1}\right)^{-1}\\
  \end{bmatrix}
  =
  \begin{bmatrix}
    \Wkk[1]^{i+1}\Tk[1]^{i+1}\left(\Tk[q]^{i+1}\right)^{-1}\\
    \vdots\\
    \Wkk[q]^{i+1}\\
    \vdots\\
    \Wkk[K]^{i+1}\Tk[K]^{i+1}\left(\Tk[q]^{i+1}\right)^{-1}\\
  \end{bmatrix}.
\end{equation}

\noindent
% This is indeed consistent with~\eqref{eq:desSigEst} since it can be verified that $\Wk[q]^{i+1,\Her}\mathbf{y} = \left(\Tk[q]^{i+1}\right)^{-\Her}\tW^{i+1,\Her}\ty^i = \left(\Tk[q]^{i+1}\right)^{-\Her}\dhatk^{i+1}$.
% \begin{equation}
%   \Wk[q]^{i+1,\Her}\mathbf{y} = \left(\Tk[q]^{i+1}\right)^{-\Her}\tW^{i+1,\Her}\ty^i,
% \end{equation}
% \noindent
% with $\tW^{i+1}$ and $\ty^i$ defined in~\eqref{eq:tW_partition} and~\eqref{eq:yTildeRoot}, respectively. 
% All nodes thus determine the parametrized version~\eqref{eq:nw_filter_dansep} of their centralized node-specific filter, % from~\eqref{eq:parametrization_Wk_centralized},
% where node $q$ can only manipulate $\Wkk[q]^{i+1}$ and $\Tk[q]^{i+1}$.
The set of parameters $\left\{\Wkk[q']^{i+1},\Tk[q']^{i+1}\right\}\fa q' \in\K$ defines the parametrization~\eqref{eq:nw_filter_dansep} of all achievable network-wide filters $\Wk[q]^{i+1}\fa q\in\K$.

\textit{Theorem 1:} If the signal model in~\eqref{eq:sk_to_slat} and~\eqref{eq:dk_to_sk} holds with $\Psibkov[q]$ full-rank, $\forall\:q\in\K$,
% and $Q=S$, i.e., the dimension of the target signal is equal to the number of latent desired sources, 
then the solution space defined by the parametrization~\eqref{eq:nw_filter_dansep} includes the centralized optimal filters $\hWk[q]=\left(\Ryy\right)^{-1}\Rydk[q]$ as in~\eqref{eq:centr_mwf}$\fa q\in\K$.

\textit{Proof:} see Appendix A.

\textit{Theorem 2:} In any connected topology-unconstrained \gls*{wasn}, if the signal model in~\eqref{eq:sk_to_slat} and~\eqref{eq:dk_to_sk} holds with
% with $Q=S$ and 
$\Psibkov[q]$ full-rank$\fa q\in\K$, then the \gls*{dansep} algorithm in node $q$ converges to the centralized optimal filter $\hWk[q]=\left(\Ryy\right)^{-1}\Rydk[q]$ in~\eqref{eq:centr_mwf}$\fa q\in\K$.

\textit{Proof:} see Appendix B.

