\subsection{\gls*{scm} transformation matrices}\label{subapp:scm_transformation_matrices}

The \gls*{danse}, \gls*{tidanse}, and \gls*{dansep} observation vector \gls*{scm} $\Ryyt^i$ can be obtained from the centralized \gls*{scm} $\Ryy$ using the appropriate set of fusion matrices as:

\begin{equation}
  \Ryyt^{i} = \Ck^{i,\Her}\Ryy\Ck^{i}.
\end{equation}

% \begin{align}
%   \text{\gls*{danse}:}\:\:\Ryyt^{i,\mathrm{D}} &= \left(\Ck^{i,\mathrm{D}}\right)^\Her\Ryy\Ck^{i,\mathrm{D}},\\
%   \text{\gls*{tidanse}:}\:\:\Ryyt^{i,\mathrm{TI}} &= \left(\Ck^{i,\mathrm{TI}}\right)^\Her\Ryy\Ck^{i,\mathrm{TI}},\\
%   \text{\gls*{dansep}:}\:\:\Ryyt^{i,\mathrm{TI+}} &= \left(\Ck^{i,\mathrm{TI+}}\right)^\Her\Ryy\Ck^{i,\mathrm{TI+}},
% \end{align}

\noindent
Consequently, it holds that $\Rsst^i = \Ck^{i,\Her}\Rss\Ck^{i}$ and $\Rnnt^i = \Ck^{i,\Her}\Rnn\Ck^{i}$.
The definition of $\Ck^i$ is specific to each algorithm:

\begin{align}
  \begin{split}
    \Ck^i &\triangleq \begin{cases}
      [
        \Sk\:|\:\Bk[k,\mathrm{D}]^{i}
      ]
      % \in\C[M][(M_k+Q(K-1))]
      &\text{for \gls*{danse}},\\
      [
        \Sk\:|\:\Bk[k,\mathrm{TI}]^{i}
      ]
      % \in\C[M][(M_k+Q)]
      &\text{for \gls*{tidanse}},\\
      [
        \Sk\:|\:\Bk[k,\mathrm{TI+}]^{i}
      ]
      % \in\C[M][{(M_k+Q|\Uk^i|)}]
      &\text{for \gls*{dansep}},
    \end{cases}\\
    \text{with}\:\:
    \Sk &\triangleq \begin{bmatrix}
      \mathbf{0}_{M_k\times (\sum_{q<k}M_q)} \:|\: \I[M_k] \:|\:\mathbf{0}_{M_k\times (\sum_{q>k}M_q)}
    \end{bmatrix}^\T.
  \end{split}
\end{align}

% \noindent
% with:

% \begin{equation}
%   \Sk \triangleq \begin{bmatrix}
%     \mathbf{0}_{M_k\times (\sum_{q<k}M_q)} \:|\: \I[M_k] \:|\:\mathbf{0}_{M_k\times (\sum_{q>k}M_q)}
%   \end{bmatrix}^\T.
% \end{equation}

\noindent
For \gls*{danse}, $\Bk[k,\mathrm{D}]^{i}\in\C[M][(M_k+Q(K-1))]$ is defined as:

\begin{align}
  \Bk[k,\mathrm{D}]^{i} &\triangleq \begin{bmatrix}
    \Bk[<k]^i & \mathbf{0}_{(\sum_{q<k}M_q)\times (K-k)Q}\\
    \mathbf{0}_{M_k\times (k-1)Q} & \mathbf{0}_{M_k\times (K-k)Q}\\
    \mathbf{0}_{(\sum_{q>k}M_q)\times (k-1)Q} & \Bk[>k]^i\\
  \end{bmatrix},\\
  \Bk[<k]^i &\triangleq \mathrm{blkdiag}\left\{
    \Pk[1,\mathrm{D}]^{i},\dots,\Pk[k-1,\mathrm{D}]^{i}
  \right\},\\
  \Bk[>k]^i &\triangleq \mathrm{blkdiag}\left\{
    \Pk[k+1,\mathrm{D}]^{i},\dots,\Pk[K,\mathrm{D}]^{i}
  \right\},
\end{align}

\noindent
with $\Pk[q,\mathrm{D}]^{i}$ the fusion matrix of node $q$ at iteration $i$, $\forall\:q\in\K$.
For \gls*{tidanse}, $\Bk[k,\mathrm{TI}]^{i}\in\C[M][(M_k+Q)]$ is defined as:

\begin{equation}
  \begin{split}
    \Bk[k,\mathrm{TI}]^{i} \triangleq &
    \begin{bmatrix}
      \Pk[1,\mathrm{TI}]^{i,\T}\:\dots\:
      \Pk[k-1,\mathrm{TI}]^{i,\T}\:\:
      \mathbf{0}\:\:%_{Q\times M_k},
      \Pk[k+1,\mathrm{TI}]^{i,\T}\:\dots\:
      \Pk[K,\mathrm{TI}]^{i,\T}
    \end{bmatrix}^\T
  \end{split}
\end{equation}

\noindent
with $\Pk[q,\mathrm{TI}]^{i}$ the fusion matrix of node $q$ at iteration $i$, $\forall\:q\in\K$.
For \gls*{dansep}, $\Bk[k,\mathrm{TI+}]^{i}\in\C[M][{(M_k+Q|\Uk^i|)}]$ is defined as:

\begin{align}
  \Bk[k,\mathrm{TI+}]^{i} &\triangleq \begin{bmatrix}
    \Bk[k1]^{i,\mathrm{TI+}} \dots \Bk[kB]^{i,\mathrm{TI+}}
  \end{bmatrix},\\
  \text{where:}\:\:
  \Bk[kl]^{i,\mathrm{TI+}} &\triangleq \begin{bmatrix}
    \Vk[kl,1]^{i,\T} \dots \Vk[kl,K]^{i,\T}
  \end{bmatrix}^\T
  \:\forall\:l\in\Uk^i,\\
  \text{with:}\:\:
  \Vk[kl,q]^{i} &\triangleq \begin{cases}
    \Pk[q]^i &\text{if $q\neq k$ and $n^i(q)=l$},\\
    \mathbf{0}_{M_q\times Q} &\text{otherwise}
  \end{cases}.
\end{align}

