% \end{aligned}
% \end{equation}
where $C_i$ and $C_o$ represent the dimensions of input and output channels, the $B_i$ and $B_o$ indicate the capacities of ifmap and ofmap in bytes. The ofmap's height and width are denoted as $H_o$ and $W_o$. Besides, the input tile size $\Tilde{S}i$ is enlarged based on output tiles, kernels, and strides, as explained in \cite{tu2017deep}. The $\Tilde{S}_p$ is the size of tiled PSUM calculated as $\beta\times P_o \times P_{co}$, where $P_{oh}$ and $P_{ow}$ are the height and width of the output/PSUM tile, constrained by $P_o=P_{oh}\times P_{ow}$. If exceeding the $B_i$ or $B_o$, extra read to both the SRAM and DRAM occur, the $N_d^{i/w/p/o}$ is defined as:
\begin{equation}
\begin{aligned}
&\quad\quad\quad\  N_d^i=\left\{
\begin{array}{ll}
1, & \Tilde{S}_i<B_i \\
\left\lceil\frac{C_o}{P_{co}}\right\rceil, & \Tilde{S}_i \geq B_i
\end{array}\right., 
N_d^w=1 \\
&  N_d^p=\left\{\begin{array}{ll}
0, & \frac{H_o\cdot W_o}{P_{o}}\cdot\Tilde{S}_p<B_o \\
2\left(\left\lceil\frac{C_{i}}{P_{ci}}\right\rceil-1\right), & \frac{H_o\cdot W_o}{P_{o}}\cdot\Tilde{S}_p \geq B_o
\end{array}\right.,  N_d^o=1
\end{aligned}
\end{equation}

\subsection{Quantization}
\label{section2.2}
Quantization has emerged as an effective strategy to alleviate computational and memory overheads, particularly advantageous for deployments on hardware accelerators, and can be expressed as:
\begin{equation}
\Tilde{x}=\alpha \cdot Q_k(x)=\alpha \cdot\left\lfloor\operatorname{Clip}\left(\frac{x}{\alpha}, Q_n, Q_p\right)\right\rceil
\end{equation}
