	\subsection{Sensing Channel Model}
	In low-altitude sensing scenarios, consistent with common assumptions in cooperative ISAC systems \cite{zhenkunzhang,JunTang}, we assume a direct line-of-sight (LoS) path between any tBS-rBS pair. 
	This leads to $K+1$ resolvable propagation paths at rBS $n_{\mathrm{r}}$, comprising $K$ target-scattered paths and one dominant LoS component, where the length of target-scattered paths are also known as the \textit{bistatic ranges}.
	The temporal characteristics of these paths are quantified through path-specific delays $\tau_k=d_k/c_0$ for $k=1,\dots,K+1$, where $d_k$ represents the length of the $k$th path, and $c_0$ is the speed of light.
	In addition, the Doppler shift of the LoS path ($k=k_{\mathrm{LoS}}$) is known to satisfy $f_{k_{\mathrm{LoS}}}^{\mathrm{d}}=0$, while each scattered path ($k\ne k_{\mathrm{LoS}}$) exhibits shift $f_{k}^{\mathrm{d}}=v_k/\lambda$ proportional to the total radial velocity $v_k$ (called \textit{bistatic Doppler velocity}) of a target relative to tBS $n_{\mathrm{t}}$ and rBS $n_{\mathrm{r}}$, with $\lambda$ denoting the carrier wavelength.
	Then, the time-delay domain channel matrix between tBS $n_{\mathrm{t}}$ and rBS $n_{\mathrm{r}}$ is formulated as
	\begin{align}
		\label{equation:time_and_delay_channel}
		\mathbf{H}(t,\tau)=\sum_{k=1}^{K+1}{\left[ \begin{array}{l}
				\alpha _k\mathbf{a}_{\mathrm{r}}\left( \theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}} \right) \mathbf{a}_{\mathrm{t}}^{\mathrm{H}}\left( \theta _{k}^{\mathrm{t}},\phi _{k}^{\mathrm{t}} \right)\\
				\times \delta \left( \tau -\tau _k-{\delta}^{\mathrm{t}} \right) e^{j2\pi (f_{k}^{\mathrm{d}}+{\delta}^{\mathrm{f}})t}\\
			\end{array} \right] ,}
	\end{align}
	where $\alpha_k$ represents the composite channel gain of the $k$th path, while ${\delta}^{\mathrm{t}}$ and ${\delta}^{\mathrm{f}}$ are the STO and CFO after synchronization between tBS $n_{\mathrm{t}}$ and rBS $n_{\mathrm{r}}$.
	The spatial characteristics are determined by azimuth/elevation angles of arrival (AoA) $\left\{ \theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}} \right\} $ and departure (AoD) $\left\{ \theta _{k}^{\mathrm{t}},\phi _{k}^{\mathrm{t}} \right\} $.
	To simplify the notation, we further define
	\begin{equation}
		\left\{ \begin{array}{l}
			\varPhi _{k}^{\mathrm{r}}\triangleq \cos \theta _{k}^{\mathrm{r}}, \,\varTheta _{k}^{\mathrm{r}}\triangleq \sin \theta _{k}^{\mathrm{r}}\cos \phi _{k}^{\mathrm{r}},\\
			\varPhi _{k}^{\mathrm{t}}\triangleq \cos \theta _{k}^{\mathrm{t}}, \,\varTheta _{k}^{\mathrm{t}}\triangleq \sin \theta _{k}^{\mathrm{t}}\cos \phi _{k}^{\mathrm{t}}.\\
		\end{array} \right.
		\label{equation:azimuth/elevationAoA}
	\end{equation}
	Then, the steering vectors $\mathbf{a}_{\mathrm{r}}\left( \theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}} \right)$ and $\mathbf{a}_{\mathrm{t}}\left( \theta _{k}^{\mathrm{t}},\phi _{k}^{\mathrm{t}} \right) $ in \eqref{equation:time_and_delay_channel} can be written as
	\begin{align}
		&\mathbf{a}_{\mathrm{r}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) =\mathbf{a}_{\mathrm{r}}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{r}} \right) \otimes \mathbf{a}_{\mathrm{r}}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{r}} \right) \in \mathbb{C} ^{L\times 1},
		\\
		&\mathbf{a}_{\mathrm{t}}\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right) =\mathbf{a}_{\mathrm{t}}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{t}} \right) \otimes \mathrm{}\mathbf{a}_{\mathrm{t}}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{t}} \right) \in \mathbb{C} ^{L\times 1},
	\end{align}
	where the corresponding UPA steering vectors are constructed based on planar wavefront geometry
	\begin{align}
		&\mathbf{a}_{\mathrm{r}}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{r}} \right) =[1,\cdots ,e^{j2\pi (N_{\mathrm{v}}-1)\frac{d}{\lambda}\varPhi _{k}^{\mathrm{r}}}]^{\mathrm{T}}\in \mathbb{C} ^{N_{\mathrm{v}}\times 1},
		\\
		&\mathbf{a}_{\mathrm{r}}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{r}} \right) =[1,\cdots ,e^{j2\pi (N_{\mathrm{h}}-1)\frac{d}{\lambda}\varTheta _{k}^{\mathrm{r}}}]^{\mathrm{T}}\in \mathbb{C} ^{N_{\mathrm{h}}\times 1},
	\end{align}
	with analogous expressions for $\mathbf{a}_{\mathrm{t}}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{t}} \right) $ and $\mathbf{a}_{\mathrm{t}}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{t}} \right)$ through substitution of superscripts $\mathrm{r}\rightarrow \mathrm{t}$.
	By processing the Fourier transform of $\tau$, the frequency domain channel at the $m$th subcarrier can be derived as
	\begin{align}
		\mathbf{H}_m(t)=\sum_{k=1}^{K+1}{\left[ \begin{array}{l}
				\alpha _k\mathbf{a}_{\mathrm{r}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \mathbf{a}_{\mathrm{t}}^{\mathrm{H}}\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right)\\
				\times e^{-j2\pi m\Delta f\left( \tau _k+{\delta}^{\mathrm{t}} \right)}e^{j2\pi \left( f_{k}^{\mathrm{d}}+{\delta}^{\mathrm{f}} \right) t}\\
			\end{array} \right] .}
	\end{align}
	%where $\Delta \tau _k\triangleq \tau _k+{\delta}^{\mathrm{t}}$ and $\Delta f_{k}^{\mathrm{d}}\triangleq f_{k}^{\mathrm{d}}+{\delta}^{\mathrm{f}}$.
	Then, by sampling the received signal at the $n$th OFDM symbol, we can obtain the discrete frequency-domain channel for the $n$th symbol at the $m$th subcarrier as follows
	\begin{align}\label{equation:channel_H_mn}
		\mathbf{H}_{m,n}=\sum_{k=1}^{K+1}{\left[ \begin{array}{l}
				\alpha _k\mathbf{a}_{\mathrm{r}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \mathbf{a}_{\mathrm{t}}^{\mathrm{H}}\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right)\\
				\times e^{-j2\pi m\Delta f\left( \tau _k+{\delta}^{\mathrm{t}} \right)}e^{j2\pi \left( f_{k}^{\mathrm{d}}+{\delta}^{\mathrm{f}} \right) nT_{\mathrm{s}}}\\
			\end{array} \right] .}
	\end{align}

	In the following, we first develop an efficient sensing parameter estimation algorithm to extract the bistatic ranges $\left\{ d_k \right\} _{k=1}^{K+1}$, azimuth/elevation angles $\left\{ \theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}} \right\} _{k=1}^{K+1}$, and bistatic Doppler velocities $\left\{ v_k \right\} _{k=1}^{K+1}$ related to the targets from the received signals $\hat{\mathbf{y}}_{m,n}$.
	Then, we propose a data fusion scheme that integrates these parameters to achieve accurate 3D localization and velocity estimation of the targets. 

	\section{Tensor-Based Parameter Estimation Algorithm}\label{Sec_Tensor-Based_Estimation}
	In this section, a tensor decomposition-based parameter estimation framework for bistatic ISAC systems is proposed. 
	By reshaping received signals into a third-order tensor, we employ CP decomposition to extract the delay, angle, and Doppler factor matrices from the received signals $\hat{\mathbf{y}}_{m,n}$. 
	Leveraging the inherent Vandermonde structure in one factor matrix, we develop an ESPRIT-inspired algorithm for efficient parameter estimation. 

	\subsection{Tensor Formulation of the Received Signal}
	By substituting \eqref{equation:channel_H_mn} into \eqref{equation:hat_y}, the received signal $\hat{\mathbf{y}}_{m,n}$ can be rewritten as
	\begin{align}
		\hat{\mathbf{y}}_{m,n}=\sum_{k=1}^{K+1}{\left[ \begin{array}{l}
				\alpha _k\mathbf{Q}^{\mathrm{H}}\mathbf{a}_{\mathrm{r}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \mathbf{a}_{\mathrm{t}}\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right) ^H\mathbf{F1}\\
				\times e^{-j2\pi m\Delta f\left( \tau _k+{\delta}^{\mathrm{t}} \right)}e^{j2\pi \left( f_{k}^{\mathrm{d}}+{\delta}^{\mathrm{f}} \right) nT_{\mathrm{s}}}\\
			\end{array} \right]}+\hat{\mathbf{n}}_{m,n}.
	\end{align}
	By stacking the $N$ OFDM symbols and $M$ subcarriers, the received signal can be transformed to a three-order tensor $\mathcalbf{Y} \in \mathbb{C}^{R \times N \times M}$ as follows
	\begin{equation}\label{equation:tensor_Y_by_vector}
		\mathcalbf{Y} =\sum_{k=1}^{K+1}{\alpha _k\mathbf{a}(\varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}},\varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}})\circ \mathbf{b}(f_{k}^{\mathrm{d}},{\delta}^{\mathrm{f}})\circ \mathbf{c}(\tau _k,{\delta}^{\mathrm{t}})}+\mathcal{N} ,
	\end{equation}
	where $\mathcal{N}$ is the noise tensor, $\mathbf{a}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}},\varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right)  \in \mathbb{C}^{R \ \times 1}$, $\mathbf{b}\left( f_{k}^{\mathrm{d}},{\delta}^{\mathrm{f}} \right) \in \mathbb{C}^{N \times 1}$, and $\mathbf{c}\left( \tau _k,{\delta}^{\mathrm{t}} \right)  \in \mathbb{C}^{M \times 1}$ can be respectively derived as follows
	\begin{align}
		\!\mathbf{a}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}},\varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right) &=\mathbf{Q}^{\mathrm{H}}\mathbf{a}_r\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \mathbf{a} ^{\mathrm{H}}_t\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right)\mathbf{F1}, \!\label{vector_a}
		\\
		\mathbf{b}(f_{k}^{\mathrm{d}},{\delta}^{\mathrm{f}})&=[1,\cdots ,e^{j2\pi (N-1)T_{\mathrm{s}}(f_{k}^{\mathrm{d}}+{\delta}^{\mathrm{f}})}]^{\mathrm{T}},\label{vector_b}
		\\
		\mathbf{c}\left( \tau _k,{\delta}^{\mathrm{t}} \right) &=[1,\cdots ,e^{-j2\pi (M-1)\Delta f(\tau _k+{\delta}^{\mathrm{t}})}]^{\mathrm{T}}.\label{vector_c}
	\end{align}
	By defining factor matrices $\mathbf{A}\in \mathbb{C}^{R \times (K+1)}$, $\mathbf{B}\in \mathbb{C}^{N \times (K+1)}$, and $\mathbf{C}\in \mathbb{C}^{M \times (K+1)}$, whose $k$th column are respectively given by $\mathbf{a}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}},\varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right)$, $\alpha _k \mathbf{b}(f_{k}^{\mathrm{d}},{\delta}^{\mathrm{f}})$, and $\mathbf{c}\left( \tau _k,{\delta}^{\mathrm{t}} \right)$, \eqref{equation:tensor_Y_by_vector} can also be expressed as 
	\begin{align}\label{equation:tensor_Y_by_matrix}
		\mathcalbf{Y} =\llbracket \mathbf{A},\mathbf{B},\mathbf{C} \rrbracket+\mathcal{N}.
	\end{align}

	\subsection{Decomposition-Based Factor Matrices Recovery}\label{subsec_Matrices_Recovery}
	From \eqref{vector_a}-\eqref{vector_c}, it can be observed that the factor matrices $\mathbf{A}$, $\mathbf{B}$, and $\mathbf{C}$ respectively encode the angle, Doppler, and delay parameters of all propagation paths.
	To extract these sensing parameters, we first formulate the following CP decomposition problem to recover $\mathbf{A}$, $\mathbf{B}$, and $\mathbf{C}$:
	\begin{equation}\label{Proble_CP_decomp}
		\min_{\mathbf{A},\mathbf{B},\mathbf{C}} \left\| \mathcalbf{Y} -\sum_{k=1}^{K+1}{\alpha _k\mathbf{a}(\varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}},\varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}})\!\circ\! \mathbf{b}(f_{k}^{\mathrm{d}},{\delta}^{\mathrm{f}})\! \circ \! \mathbf{c}(\tau _k,{\delta}^{\mathrm{t}})} \right\| _{\mathrm{F}}^{2},
	\end{equation}
	where $\|\cdot\|_{\mathrm{F}}$ denotes the Frobenius norm. 
	While conventional alternating least squares (ALS) methods \cite{zhouzhou,C-DRCNN} can solve the non-convex Problem \eqref{Proble_CP_decomp}, they suffer from computational inefficiency, initialization-dependent convergence, and numerical instability.
	To address these limitations, in the following, we leverage the inherent Vandermonde structure of delay-related matrix $\mathbf{C}$ through an ESPRIT-inspired decomposition scheme. 

	Let $\mathbf{Y}_{(1)}$ represent the mode-1 unfolding of tensor $\mathcalbf{Y}$, expressed as
	\begin{equation}\label{equation:Y1}
		\mathbf{Y}_{(1)}^{\mathrm{T}}=\left(\mathbf{C} \odot \mathbf{B}\right)\mathbf{A}^{\mathrm{T}} \in \mathbb{C}^{M N \times R}.
	\end{equation}
	In addition, we select a pair of integer ${L_1,L_2}$ subjected to $L_1+L_2 = M+1$ and define the cyclic matrix as 
	\begin{equation}
		\mathbf{J}_{l}=\left[ \mathbf{0}_{L_1\times (l-1)},\mathbf{I}_{L_1},\mathbf{0}_{L_1\times (L_2-l)} \right] \in \mathbb{C} ^{L_1\times M}.
	\end{equation}
	Then, a smoothed measurement matrix can be constructed as 
	\begin{align}\label{equation:Y_S}
		\mathbf{Y}_{\mathrm{S}}&=\left[ \left( \mathbf{J}_1\otimes \mathbf{I}_N \right) \mathbf{Y}_{\left( 1 \right)}^{\mathrm{T}},\dots ,\left( \mathbf{J}_{L_2}\otimes \mathbf{I}_N \right) \mathbf{Y}_{\left( 1 \right)}^{\mathrm{T}} \right]\notag
		\\
		&\overset{\left( a \right)}{=}\left( \mathbf{C}^{L_1}\odot \mathbf{B} \right) \left( \mathbf{C}^{L_2}\odot \mathbf{A} \right) ^{\mathrm{T}}\in \mathbb{C} ^{L_1N\times L_2R},
	\end{align}
	where $\mathbf{C}^{L_1}= [\mathbf{C}]_{1:L_1,:}$ and $\mathbf{C}^{L_2}=[\mathbf{C}]_{1:L_2,:}$ denote the first $L_1$ and $L_2$ rows of $\mathbf{C}$, respectively. 
	The equality $(a)$ follows from Khatri-Rao product properties, i.e., $(\mathbf{A} \otimes \mathbf{B})(\mathbf{C} \odot \mathbf{D})=(\mathbf{A}\mathbf{C}) \odot (\mathbf{B}\mathbf{D})$, and the shift-invariance induced by the Vandermonde structure of $\mathbf{C}$, i.e., $\mathbf{J}_{l_2} \mathbf{C}=\mathbf{J}_1 \mathbf{C} \mathrm{diag}\left(\left[\mathbf{C}\right]_{l_2,:}\right)$ \cite{timevarying_TVT}.
	By performing truncated singular value decomposition (SVD) on $\mathbf{Y}_{\mathrm{S}}$, we have
	\begin{equation}
		\mathbf{Y}_{\mathrm{S}}=\mathbf{U} \mathbf{\Sigma} \mathbf{V}^{\mathrm{H}},
		\label{equation:svd_Y_S}
	\end{equation}
	where $\mathbf{U}\in \mathbb{C}^{L_1N \times (K+1)}$, $\mathbf{\Sigma} \in \mathbb{C}^{(K+1) \times (K+1)}$, and $\mathbf{V} \in \mathbb{C}^{L_2R \times (K+1)}$. 
	Note that $\mathbf{U}$ span the column spaces of  $\mathbf{Y}_S$. 
	Therefore, a nonsingular matrix $\mathbf{M} \in \mathbb{C}^{(K+1) \times (K+1)}$ exists such that \cite{zxd}
	\begin{align}
		\mathbf{C}^{L_1} \odot \mathbf{B}&=\mathbf{U M} \in \mathbb{C}^{L_1 N \times (K+1)},	\label{equation:UM}
		\\
		\mathbf{C}^{L_2} \odot \mathbf{A}&=\mathbf{V}^*\mathbf{\Sigma }\left( \mathbf{M}^{-1} \right) ^{\mathrm{T}}\in \mathbb{C} ^{L_2R\times (K+1)}. \label{equation:VSigmaM}
	\end{align}
	By leveraging the shift-invariant structure, we partition $\mathbf{U}$ into overlapped submatrices $\mathbf{U}_1={\left[ \mathbf{U}\right] }_{1:(L_1-1)N,:}$ and  $ \mathbf{U}_2=\left[ \mathbf{U}\right] _{N+1:L_1N,:}$, yielding
	\begin{align}
		\mathbf{U}_1 \mathbf{M}& = \underline{\mathbf{C}}^{L_1} \odot \mathbf{B}, 
		\label{equation:up}
		\\
		\mathbf{U}_2 \mathbf{M}& = \overline{\mathbf{C}}^{L_1} \odot \mathbf{B},
		\label{equation:down}
	\end{align}
	where $\underline{\mathbf{C}}^{L_1}$ and $\overline{\mathbf{C}}^{L_1}$ respectively denote $\mathbf{C}^{L_1}$ with the first and last rows removed.  
	Based on the Vandermonde structure of $\mathbf{C}^{L_1}$, we derive that 
	\begin{equation}
		(\underline{\mathbf{C}}^{L_1} \odot \mathbf{B})\mathbf{Z}= \overline{\mathbf{C}}^{L_1} \odot \mathbf{B},
		\label{equation:Vandermonde}
	\end{equation}
	where $\mathbf{Z}= \mathrm{diag}([e^{-j 2 \pi \Delta f \Delta \tau_1}, \ldots, e^{-j 2 \pi \Delta f \Delta \tau_K}])$.
	Substituting \eqref{equation:up} and \eqref{equation:down} into \eqref{equation:Vandermonde}, we have
	\begin{equation}
		\mathbf{U}_1^{\dagger} \mathbf{U}_2 =\mathbf{M Z M}^{-1}.
		\label{equation:performing_svd}
	\end{equation}


	From \eqref{equation:performing_svd}, it can be noted  that the estimates of $\mathbf{Z}$ and $\mathbf{M}$, denoted by $\hat{\mathbf{Z}}$ and $\hat{\mathbf{M}}$, can be obtained from the eigenvalue decomposition (EVD) of $\mathbf{U}_1^{\dagger}\mathbf{U}_2$. 
	Then, a recovery of $\mathbf{C}$ can be generated by the normalized diagonal elements of $\hat{\mathbf{Z}}$.
	Specifically, each column of the recovered factor matrix ${\mathbf{C}}$ is given by
	\begin{equation}
		\hat{\mathbf{c}}_k =\left[1, \hat{z}_k, \ldots, \hat{z}_k^{M-1}\right]^{\mathrm{T}},\,k=1, \ldots, K+1,
		\label{equation:recovered_C}
	\end{equation}
	where $\hat{z}_k={[\hat{\mathbf{Z}}]_{k,k}}\big/{\left| [\hat{\mathbf{Z}}]_{k,k} \right|}$.
	Recall that the $k$th column of $\mathbf{B}$ is given by $\alpha _k \mathbf{b}(f_{k}^{\mathrm{d}},{\delta}^{\mathrm{f}})$.
	Let $\mathbf{c}_{k}^{L_1}$ and $\mathbf{m}_k$ denote the $k$th columns of $\mathbf{C}^{L_1}$ and $\mathbf{M}_k$, respectively.
	From the Kronecker product structure in \eqref{equation:UM}, we have 
	\begin{equation}
		\mathbf{c}_{k}^{L_1}\otimes \left( \alpha _k\mathbf{b}(f_{k}^{\mathrm{d}},{\delta}^{\mathrm{f}}) \right) =\mathbf{Um}_k.
	\end{equation}
	Hence, we can further recover each column of $\mathbf{B}$ as follows
	\begin{align}
		\hat{\mathbf{b}}_k\overset{\left( a \right)}{=} &\left( \frac{(\hat{\mathbf{c}}_{k}^{L_1})^{\mathrm{H}}}{\left\| \hat{\mathbf{c}}_{k}^{L_1} \right\| _{2}^{2}}\otimes \mathbf{I}_N \right) \left( \hat{\mathbf{c}}_{k}^{L_1}\otimes \hat{\mathbf{b}}_k \right) \notag
		\\
		=&\left( \frac{(\hat{\mathbf{c}}_{k}^{L_1})^{\mathrm{H}}}{\left\| \hat{\mathbf{c}}_{k}^{L_1} \right\| _{2}^{2}}\otimes \mathbf{I}_N \right) \mathbf{U}\hat{\mathbf{m}}_k,\,k=1,\cdots ,K+1,
		\label{equation:recovered_B}
	\end{align} 
	where $\hat{\mathbf{c}}_{k}^{L_1}$ and $\hat{\mathbf{m}}_k$ represent the $k$th columns of $\hat{\mathbf{C}}^{L_1}$ and $\hat{\mathbf{M}}_k$, respectively.
	The equality $\left( a \right)$ in \eqref{equation:recovered_B} follows from the Kronecker product identities, i.e., $\left( \mathbf{A}\otimes \mathbf{B} \right) \left( \mathbf{C}\otimes \mathbf{D} \right) =\mathbf{AC}\otimes \mathbf{BD}$.
	Similarly, it can be derived from \eqref{equation:UM} that $\mathbf{c}_k^{L_2} \otimes \mathbf{a}_k = \mathbf{V^*}\mathbf{\Sigma}\mathbf{t}_k$, where $\mathbf{t}_k$ is the $k$th column of $\left( \mathbf{M}^{-1} \right) ^{\mathrm{T}}$.
	Thus, each column of ${\mathbf{A}}$ can be recovered as 
	\begin{equation}
		\hat{\mathbf{a}}_k=\left(\frac{(\hat{\mathbf{c}}_k^{L_2})^{\mathrm{H}}}{\left\|\hat{\mathbf{c}}_k^{L_2}\right\|_2^2} \otimes \mathbf{I}_R\right) \mathbf{V}^{*} \mathbf{\Sigma} \hat{\mathbf{t}}_k, \,k = 1,\cdots,K+1,
		\label{equation:recovered_A}
	\end{equation} 
	where $\hat{\mathbf{c}}_{k}^{L_2}$ and $\hat{\mathbf{t}}_k$ represent the $k$th columns of $\hat{\mathbf{C}}^{L_2}$ and $( \hat{\mathbf{M}}^{-1} ) ^{\mathrm{T}}$, respectively.

	\begin{remark}
		Here, the factor matrices $\mathbf{A}$, $\mathbf{B}$, and $\mathbf{C}$ are recovered as $\hat{\mathbf{A}}=\left[ \hat{\mathbf{a}}_1,\dots ,\hat{\mathbf{a}}_{K+1} \right] $, $\hat{\mathbf{B}}=\left[ \hat{\mathbf{b}}_1,\dots ,\hat{\mathbf{b}}_{K+1} \right] $, and $\hat{\mathbf{C}}=\left[ \hat{\mathbf{c}}_1,\dots ,\hat{\mathbf{c}}_{K+1} \right] $, respectively.
		The uniqueness of the CP decomposition will be discussed in Section \ref{subsec_uniqueness}, which	
		guarantees the following equalities \cite{AlwinOnKruskal}:
		\begin{equation}\label{equation_uniqueness}
			\hat{\mathbf{A}}=\mathbf{A} \mathbf{\Pi} \mathbf{\Delta}_1, \
			\hat{\mathbf{B}}=\mathbf{B} \mathbf{\Pi} \mathbf{\Delta}_2, \  \hat{\mathbf{C}}=\mathbf{C} \mathbf{\Pi} \mathbf{\Delta}_3,
		\end{equation}
		where $\mathbf{\Pi}$ is a unique permutation matrix, while $\mathbf{\Delta}_1$, $\mathbf{\Delta}_2$, and $\mathbf{\Delta}_3$ are unique diagonal scaling matrices satisfying $\mathbf{\Delta }_1\mathbf{\Delta }_2\mathbf{\Delta }_3=\mathbf{I}_{K+1}$. 
		The shared permutation matrix ensures automatic parameter pairing - the $k$th columns across all factor matrices inherently correspond to the same propagation path, which reduces the data association requirements.
	\end{remark}


	\subsection{Parameter Estimation}\label{subsec_Parameter_Estimation}
	In this subsection, we extract the bistatic ranges, azimuth/elevation angles, and bistatic Doppler velocities correspond to all targets from the recovered factor matrices $\hat{\mathbf{A}}$, $\hat{\mathbf{B}}$, and $\hat{\mathbf{C}}$.

	First, the delay of the $k$th path can be estimated as 
	\begin{equation}
		\Delta \hat{\tau}_k\triangleq\hat{\tau}_k+\hat{\delta}^{\mathrm{t}}=\frac{\measuredangle \hat{z}_k}{-2\pi \Delta f}, \,k = 1,\cdots,K+1,
	\end{equation}
	where $\hat{\delta}^{\mathrm{t}}$ denotes the estimate of the STO ${\delta}^{\mathrm{t}}$, and $\measuredangle \hat{z}_k$ is the angle of $\hat{z}_k$. 
	Without estimating the permutation matrix $\mathbf{\Pi}$, we can index the minimum value of $\{\Delta \hat{\tau}_k\}_{k=1}^{K+1}$ to find the LoS path, i.e.,
	\begin{equation}
		k_{\mathrm{LoS}} = \arg\min_{\substack{1 \leqslant k \leqslant K+1}} \Delta \hat{\tau}_k.
		\label{equation:LoS_path}
	\end{equation}
	Since the locations of all BSs are apriori known, the residual STO can be estimated as 
	\begin{equation} 
		\hat{\delta}^t = \Delta \hat{\tau}_{k_{\mathrm{LoS}}}-{\tau}_{k_{\mathrm{LoS}}},
	\end{equation} 
	where $\tau_{k_{\mathrm{LoS}}}= d_{k_{\mathrm{LoS}}}/c_0$, and $d_{k_{\mathrm{LoS}}}$ is the distance between tBS $n_{\mathrm{t}}$ and rBS $n_{\mathrm{r}}$.
	Then, the delay of the target-scattered paths can be extracted as 
	\begin{equation} 
		\hat{\tau}_k = \Delta \hat{\tau}_k-\hat{\delta}^t,\, k \in \{1, \cdots, K+1\}\setminus k_{\mathrm{LoS}}.
	\end{equation}
	The corresponding bistatic ranges are obtained as 
	\begin{equation}
		\hat{d}_k=\hat{\tau}_k c_0, \, k \in \{1, \cdots, K+1\}\setminus k_{\mathrm{LoS}}.
		\label{equation:estimated_bistatic_range}
	\end{equation}

	Next, the estimation of the Doppler parameters $\{f^{\mathrm{d}}_k,{\delta}^{\mathrm f}\}$ can be deduced as 
	\begin{align}
		&\Delta \hat{f}_{k}^{\mathrm{d}}\triangleq \hat{\delta}^{\mathrm{f}}+\hat{f}_{k}^{\mathrm{d}}=\mathrm{arg}\max_{\Delta f_{k}^{\mathrm{d}}} \frac{\left| \hat{\mathbf{b}}_{k}^{\mathrm{H}}\mathbf{b}\left( f_{k}^{\mathrm{d}},\delta ^{\mathrm{f}} \right) \right|^2}{\left\| \hat{\mathbf{b}}_k \right\| _{2}^{2}\left\| \mathbf{b}\left( f_{k}^{\mathrm{d}},\delta ^{\mathrm{f}} \right) \right\| _{2}^{2}},\notag
		\\
		&k \in \{1, \cdots, K+1\}\setminus k_{\mathrm{LoS}}.
		\label{equation:estimate_sumDroppler}
	\end{align}
	The solution of Problem \eqref{equation:estimate_sumDroppler} can be obtained via the one-dimensional search.
	By utilizing $f_{k_{\mathrm{LoS}}}^{\mathrm{d}} =0$, we can separate $\hat{f}_{k}^{\mathrm{d}}$ and $\hat{\delta}^{\mathrm f}$ as follows
	\begin{align} 
		&\hat{\delta}^{\mathrm{f}}=\Delta \hat{f}_{k_{\mathrm{LoS}}}^{\mathrm{d}},
		\\
		&\hat{f}_{k}^{\mathrm{d}}=\Delta \hat{f}_{k}^{\mathrm{d}}-\hat{\delta}^{\mathrm{f}},\,k\in \{1,\cdots ,K+1\}\setminus k_{\mathrm{LoS}}.
	\end{align}
	Then, the bistatic Doppler velocities are estimated as 
	\begin{equation}
		\hat{v}_k=\hat{f}^{\mathrm{d}}_k \lambda,\, k \in \{1, \cdots, K+1\}\setminus k_{\mathrm{LoS}}.
		\label{equation:estimated_bistatic_Doppler_velocity}
	\end{equation}

	Finally, we extract the angle parameters from $\hat{\mathbf{A}}$.
	Note that it is challenging for the four-dimensional parameter extraction of $\left\{ \theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}},\theta _{k}^{\mathrm{t}},\phi _{k}^{\mathrm{t}} \right\} _{k=1}^{K+1}$.
	Therefore, we propose to only estimate the AoAs $\{\theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}}\}_{k=1}^{K+1}$.
	The AoDs $\{\theta _{k}^{\mathrm{t}},\phi _{k}^{\mathrm{t}}\}_{k=1}^{K+1}$ can be calculated after target localization.
	From \eqref{vector_a}, we formulate the problem for jointly estimating  ${\varTheta}_{k}^{\mathrm{r}}$ and ${\varPhi}_{k}^{\mathrm{r}}$ as
	\begin{equation}
		\max_{\varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}}} \frac{\left| \hat{\mathbf{a}}_{k}^{\mathrm{H}}\mathbf{Q}^{\mathrm{H}}\mathbf{a}_{\mathrm{r}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \right|^2}{\left\| \hat{\mathbf{a}}_k \right\| _{2}^{2}\left\| \mathbf{Q}^{\mathrm{H}}\mathbf{a}_{\mathrm{r}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \right\| _{2}^{2}},
		\label{Prob_2D_AOA}
	\end{equation}
	where the normalization operation eliminates the scaling ambiguity caused by $\mathbf{\Delta}_1$ and the impact of AoDs. 
	In the objective function of Problem \eqref{Prob_2D_AOA}, the variables ${\varTheta}_{k}^{\mathrm{r}}$ and ${\varPhi}_{k}^{\mathrm{r}}$ are highly coupled.
	Although the problem can be solved via a two-dimensional search, the complexity is prohibitively high.
	In the following, an SVD-based decoupling algorithm is proposed for estimating $\{\theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}}\}_{k=1}^{K+1}$ efficiently.
	First, we approximate the combining matrix $\mathbf{Q}$ as the Kronecker product of two matrices by solving the following problem \cite{VanLoan1993}:
	\begin{equation}\label{Problem_aproxQ}
		\min_{\mathbf{Q}_{\mathrm{v}},\mathbf{Q}_{\mathrm{h}}} \parallel \mathbf{Q}-\mathbf{Q}_{\mathrm{v}}\otimes \mathbf{Q}_{\mathrm{h}}\parallel _{\mathrm{F}}^{2},
	\end{equation}
	where $\mathbf{Q}_{\mathrm{v}} \in \mathbb{C}^{N_{\mathrm{v}} \times J_{\mathrm{v}}}$, $\mathbf{Q}_{\mathrm{h}} \in \mathbb{C}^{N_{\mathrm{h}} \times J_{\mathrm{h}}}$, and $J_{\mathrm{v}} J_{\mathrm{h}} = R$. 
	Problem \eqref{Problem_aproxQ} can be equivalently reformulated as 
	\begin{equation}\label{Problem_aproxQ_reform}
		\min_{\mathbf{Q}_{\mathrm{v}},\mathbf{Q}_{\mathrm{h}}} \left\| R\left( \mathbf{Q} \right) -\mathrm{vec}\left( \mathbf{Q}_{\mathrm{v}} \right)  \mathrm{vec}\left( \mathbf{Q}_{\mathrm{h}} \right) ^{\mathrm{T}} \right\| _{\mathrm{F}}^{2},
	\end{equation}
	where $R\left( \mathbf{Q} \right)$ is defined as follows:
	\begin{equation} \label{R_Q}
		R\left( \mathbf{Q} \right) =\left[ \begin{array}{c}
			\mathbf{Q}_1\\
			\vdots\\
			\mathbf{Q}_{j_{\mathrm{v}}}\\
			\vdots\\
			\mathbf{Q}_{J_{\mathrm{v}}}\\
		\end{array} \right] ,\ 
		\mathbf{Q}_{j_{\mathrm{v}}}=\left[ \begin{array}{c}
			\mathrm{vec}\left( \left[ \mathbf{Q} \right] _{1,j_{\mathrm{v}}}\mathbf{Q}_{\mathrm{h}} \right) ^{\mathrm{T}}\\
			\vdots\\
			\mathrm{vec}\left( \left[ \mathbf{Q} \right] _{N_{\mathrm{v}},j_{\mathrm{v}}}\mathbf{Q}_{\mathrm{h}} \right) ^{\mathrm{T}}\\
		\end{array} \right] .
	\end{equation}
	The rank-one approximation problem \eqref{Problem_aproxQ_reform} can be solved by performing SVD on $R\left( \mathbf{Q} \right)$ \cite{eckart1936approximation}.
	Let $\sigma _{\max}$ denote the maximum singular value of $R\left( \mathbf{Q} \right)$.
	Then, the optimal solutions of Problem \eqref{Problem_aproxQ_reform} are given by
	\begin{align}
		\mathbf{Q}_{\mathrm{v}}&=\mathrm{unvec}_{N_{\mathrm{v}}\times J_{\mathrm{v}}}\left( \sqrt{\sigma _{\max}}\mathbf{u}_{\max} \right) ,
		\label{Q_v}
		\\
		\mathbf{Q}_{\mathrm{h}}&=\mathrm{unvec}_{N_{\mathrm{h}}\times J_{\mathrm{h}}}\left( \sqrt{\sigma _{\max}}\mathbf{v}_{\max}^{*} \right) ,
		\label{Q_h}
	\end{align}
	where ${\mathbf{u}}_{\max}$ and ${\mathbf{v}}_{\max}$ represent the left and right singular vectors corresponding to $\sigma _{\max}$, respectively.
	Thus, \eqref{vector_a} can be rewritten as follows
	\begin{align}
		&\quad \mathbf{a}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}},\varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right) \notag 
		\\
		&=\left( \mathbf{Q}_{v}^{\mathrm{H}}\otimes \mathbf{Q}_{h}^{\mathrm{H}} \right) \left( \mathbf{a}_{r}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{r}} \right) \otimes \mathbf{a}_{r}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \right) \mathbf{a}_{t}^{\mathrm{H}}\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right) \mathbf{F1}\notag
		\\
		&=\left( \mathbf{Q}_{v}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{r}} \right) \right) \otimes \left( \mathbf{Q}_{h}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \right) \mathbf{a}_{t}^{\mathrm{H}}\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right) \mathbf{F1}\notag
		\\
		&\triangleq \mathbf{o}_k\otimes \mathbf{w}_k,
	\end{align}
	where 
	\begin{align}
		&\mathbf{o}_k=\mathbf{Q}_{v}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{r}} \right),
		\label{equation:ok}\\
		&\mathbf{w}_k=\mathbf{Q}_{h}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{r}},\varPhi _{k}^{\mathrm{r}} \right) \mathbf{a}_{t}^{\mathrm{H}}\left( \varTheta _{k}^{\mathrm{t}},\varPhi _{k}^{\mathrm{t}} \right) \mathbf{F1}. 
		\label{equation:wk}
	\end{align}
	Moreover, by defining $\mathbf{O}=\left[ \mathbf{o}_1,\dots ,\mathbf{o}_{K+1} \right] $ and $\mathbf{W}=\left[ \mathbf{w}_1,\dots ,\mathbf{w}_{K+1} \right] $, we can reformulate factor matrix $\mathbf{A}$ as follows
	\begin{align}
		\mathbf{A}&=[\mathbf{o}_1\otimes \mathbf{w}_1,\cdots ,\mathbf{o}_{K+1}\otimes \mathbf{w}_{K+1}] \notag
		\\
		&= \mathbf{O}\odot \mathbf{W}.
	\end{align}
	To estimate $\mathbf{O}=\left[ \mathbf{o}_1,\dots ,\mathbf{o}_{K+1} \right] $ and $\mathbf{W}=\left[ \mathbf{w}_1,\dots ,\mathbf{w}_{K+1} \right] $, we formulate the following problem
	\begin{equation}
		\max_{\mathbf{o}_k,\mathbf{w}_k} \left\| \mathrm{unvec}_{J_{\mathrm{v}}\times J_{\mathrm{h}}}(\hat{\mathbf{a}}_k)-\mathbf{o}_k\mathbf{w}_{k}^{\mathrm{T}} \right\| _{\mathrm{F}}^{2}.
		\label{equation:SVDone}
	\end{equation}
	Problem \eqref{equation:SVDone} can be efficiently solved via the rank-1 truncated SVD.
	Let $\sigma _{k,\max}$, $\mathbf{u}_{k,\max}$, and $\mathbf{v}_{k,\max}$ denote the maximum singular value, and the corresponding left and right singular vectors, respectively, of $\mathrm{unvec}_{J_{\mathrm{v}}\times J_{\mathrm{h}}}(\hat{\mathbf{a}}_k)$.
	We can set the solution of Problem \eqref{equation:SVDone} as
	\begin{equation}\label{hat_ow}
		\hat{\mathbf{o}}_k=\sigma _{k,\max}\mathbf{u}_{k,\max},
		\
		\hat{\mathbf{w}}_k=\mathbf{v}^*_{k,\max}.
	\end{equation}
	Then, Problem \eqref{Prob_2D_AOA} can be decoupled as two subproblems:
	\begin{equation}
		\max_{\varPhi _{k}^{\mathrm{r}}} \frac{\left| \hat{\mathbf{o}}_{k}^{\mathrm{H}}\left( \mathbf{Q}_{\mathrm{v}}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{r}} \right) \right) \right|^2}{\left\| \hat{\mathbf{o}}_k \right\| _{2}^{2}\left\| \left( \mathbf{Q}_{\mathrm{v}}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{v}}\left( \varPhi _{k}^{\mathrm{r}} \right) \right) \right\| _{2}^{2}},
		\label{equation:one_search_Phi}
	\end{equation}
	\begin{equation}
		\max_{\varTheta _{k}^{\mathrm{r}}} \frac{\left| \hat{\mathbf{w}}_{k}^{\mathrm{H}}\left( \mathbf{Q}_{\mathrm{h}}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{r}},\hat{\varPhi}_{k}^{\mathrm{r}} \right) \right) \right|^2}{\left\| \hat{\mathbf{w}}_k \right\| _{2}^{2}\left\| \left( \mathbf{Q}_{\mathrm{h}}^{\mathrm{H}}\mathbf{a}_{r}^{\mathrm{h}}\left( \varTheta _{k}^{\mathrm{r}},\hat{\varPhi}_{k}^{\mathrm{r}} \right) \right) \right\| _{2}^{2}}.
		\label{equation:one_search_Theta}
	\end{equation}
	These subproblems can be solved sequentially through one-dimensional search method.
	From \eqref{equation:azimuth/elevationAoA}, given the optimal solutions $\hat{\varTheta}_{k}^{\mathrm{r}}$ and $\hat{\varTheta}_{k}^{\mathrm{r}}$ of subproblems \eqref{equation:one_search_Phi} and \eqref{equation:one_search_Theta}, the azimuth and elevation angles of AoA can be calculated as
	\begin{align}    
		\hat{\theta}_{k}^{\mathrm{r}}=\mathrm{arc}\cos\mathrm{(}\hat{\varPhi}_{k}^{\mathrm{r}}),
		\
		\hat{\phi}_{k}^{\mathrm{r}}=\mathrm{arc}\cos \left( \frac{\hat{\varTheta}_{k}^{\mathrm{r}}}{\sin\mathrm{(}\hat{\theta}_{k}^{\mathrm{r}})} \right) .
		\label{equation:azimuth_doa}
	\end{align}
	In Algorithm \ref{alg_SVD_Decoup}, we summarize the procedures of the proposed SVD-based algorithm for solving Problem \eqref{Prob_2D_AOA} and estimating the AoAs $\{\theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}}\}_{k=1}^{K+1}$.

	\begin{algorithm}[htb]
		\caption{SVD-based Decoupling AoA Estimation Algorithm}
		\label{alg_SVD_Decoup}
		\begin{algorithmic}[1] % The number tells where the line numbering should start
			\Require %算法的输入参数：Input
			Combining matrix $\mathbf{Q}$ and recovered factor matrix $\hat{\mathbf{A}}$.
			\Ensure %算法的输出：Output
			The estimation of azimuth/elevation AoAs $\{\theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}}\}_{k=1}^{K+1}$.
			\State \textbf{Initialization}: 
			Set $J_{\mathrm{v}}$ and $J_{\mathrm{h}}$ subject to $J_{\mathrm{v}} J_{\mathrm{h}} = R$;
			\State Calculate $R\left( \mathbf{Q} \right)$ via \eqref{R_Q}; 
			\State Obtain $\mathbf{Q}_{\mathrm{v}}$ and $\mathbf{Q}_{\mathrm{h}}$ via \eqref{Q_v} and \eqref{Q_h}, respectively; \label{step:q_design}
			\For{$k=1:K+1$} \label{step_loopbegin}
			\State Obtain $\hat{\mathbf{o}}_k$ and $\hat{\mathbf{w}}_k$ via \eqref{hat_ow}; \label{step:unvec}
			\State Obtain $\hat{\varPhi}_{k}^{\mathrm{r}}$ and $\hat{\varTheta}_{k}^{\mathrm{r}}$ by solving Problem \eqref{equation:one_search_Phi} and Problem \eqref{equation:one_search_Theta} via the one-dimensional search, respectively;
			\State Calculate $\hat{\theta}_{k}^{\mathrm{r}}$ and $\hat{\phi}_{k}^{\mathrm{r}}$ via \eqref{equation:azimuth_doa}; \label{step_cal_theta_phi}
			\EndFor \label{step_loopend}
		\end{algorithmic}
	\end{algorithm}


	\subsection{Uniqueness Analysis} \label{subsec_uniqueness}
	This subsection establishes uniqueness guarantees for the tensor decomposition \eqref{equation:tensor_Y_by_matrix} to ensure reliable recovery of factor matrices and subsequent parameter estimation. By extending the classical Kruskal’s uniqueness theorem \cite{KRUSKAL197795} and incorporating structural constraints inherent to the factor matrices, we have the following relaxed uniqueness criterion \cite{ruoyu_zhang,blind_signal}:
	\begin{lemma}
		\emph{Consider a third-order tensor $\mathcal{X} \in \mathbb{C}^{I_1 \times I_2 \times I_3}$ with rank $K$ decomposed into factor matrices $\mathbf{A}^{(1)} \in \mathbb{C}^{I_1 \times K}$, $\mathbf{A}^{(2)} \in \mathbb{C}^{I_2 \times K}$ and $\mathbf{A}^{(3)} \in \mathbb{C}^{I_3 \times K}$, where $\mathbf{A}^{(3)}$ 
			is a Vandermonde matrix with generators $\{z_k\}_{k=1}^K$.
			Let $k(\mathbf{A})$ denote the Kruskal-rank of matrix $\mathbf{A}$.
			The decomposition achieves uniqueness if the following joint rank conditions hold:
			\begin{equation}
				k\left(\mathbf{A}^{(L_1,3)} \odot \mathbf{A}^{(2)}\right) = K, 
			\end{equation}
			\begin{equation}
				k\left(\mathbf{A}^{(L_2,3)} \odot \mathbf{A}^{(1)}\right) = K,
			\end{equation}
			where $\mathbf{A}^{(L_1,3)}$ represents the first $L_1$ rows of $\mathbf{A}^{(3)}$, and $\mathbf{A}^{(L_2,3)}$ denotes the first $L_2$ rows of $\mathbf{A}^{(2)}$.
			The uniqueness means that any possible combination of factor matrices $( \hat{\mathbf{A}}^{(1)},\mathrm{}\hat{\mathbf{A}}^{(2)},\hat{\mathbf{A}}^{(3)} ) $ for $\mathcal{X}$ satisfies
			\begin{equation}
				\hat{\mathbf{A}}^{(1)}=\mathbf{A}^{(1)}\mathbf{\Pi \Delta }_1, \, \mathrm{}\hat{\mathbf{A}}^{(2)}=\mathbf{A}^{(2)}\mathbf{\Pi \Delta }_2, \, \hat{\mathbf{A}}^{(3)}=\mathbf{A}^{(3)}\mathbf{\Pi \Delta }_3,
			\end{equation}
			where $\mathbf{\Pi}$ is a $K\times K$ permutation matrix, and $\mathbf{\Delta}_1$, $\mathbf{\Delta}_2$, and $\mathbf{\Delta}_3$ with $\mathbf{\Delta }_1\mathbf{\Delta }_2\mathbf{\Delta }_3=\mathbf{I}_{K}$ are diagonal matrices. 
			For generic scenarios, these conditions reduce to the simplified dimensionality constraint:
			\begin{equation}
				\min\left(\left( L_1-1\right) I_2,\, L_2I_1\right) \geqslant K .
			\end{equation}
		}

		\noindent\textit{Proof:} 
		Refer to \cite{blind_signal}.
		$\hfill\blacksquare$
	\end{lemma}



	In the considered system model, the tensor dimensions $I_1$, $I_2$ and $I_3$ correspond respectively to the number of RF chains $R$, OFDM symbols $N$ and subcarriers $M$.
	The rank of tensor $\mathcalbf{Y}$ is $K+1$.
	Therefore, sufficient conditions for the decomposition uniqueness can be formulated as follows
	\begin{align}
		L_1 + L_2 &= M + 1, \label{uniqueness_1}\\
		(L_1 - 1)N &\geqslant K+1, \label{uniqueness_2}\\
		L_2R &\geqslant K+1. \label{uniqueness_3}
	\end{align}
	These constraints can be satisfied by appropriately selecting parameters, ensuring automatic association of the extracted parameters with respective propagation paths.
	Note that telecommunication systems in 5G and beyond typically employ a large number of subcarriers $M$.
	This enables flexible selection of integers $L_1$ and $L_2$.

	\subsection{Algorithm Development}

	\begin{algorithm}[t]
		\caption{Tensor-Based Sensing Parameter Estimation Algorithm}
		\label{alg_para_esti}
		\begin{algorithmic}[1]
			\Require %算法的输入参数：Input
			Received signal tensor $\mathcalbf{Y}$.
			\Ensure %算法的输出：Output
			Estimations of bistatic ranges, bistatic Doppler velocities, and azimuth/elevation angles of arrival $\left\{ d_k,v_k,\theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}} \right\} _{k=1,k\ne k_{\mathrm{LoS}}}^{K+1}$.
			\State \textbf{Initialization}: 
			Mode-1 unfold tensor $\mathcalbf{Y}$ as $\mathbf{Y}_{(1)}$ in \eqref{equation:Y1}; Set smoothing parameters $ L_1$ and $L_2 $ subject to $L_1+L_2 = M+1$;
			\State Calculate the smoothed measurement matrix $\mathbf{Y}_{\mathrm{S}}$ via \eqref{equation:Y_S};
			\State Obtain $\mathbf{U}$, $\mathbf{\Sigma}$, and $\mathbf{V}$ by performing SVD on $\mathbf{Y}_{\mathrm{S}}$ in \eqref{equation:svd_Y_S};
			\State Obtain $\hat{\mathbf{Z}}$ and $\hat{\mathbf{M}}$ by performing EVD on $\mathbf{U}_1^{\dagger} \mathbf{U}_2$ in \eqref{equation:performing_svd};
			\State Construct columns of $\hat{\mathbf{C}}$ via \eqref{equation:recovered_C};
			\State Construct columns of $\hat{\mathbf{B}}$ via \eqref{equation:recovered_B};
			\State Construct columns of $\hat{\mathbf{A}}$ via \eqref{equation:recovered_A};
			\State Obtain the index of LoS path $k_{\mathrm{LoS}}$ via \eqref{equation:LoS_path}; \label{step_getkLoS}
			\For{$k \in \{1, \cdots, K+1\}\setminus k_{\mathrm{LoS}}$}
			\State Calculate $\hat{d}_k$ via \eqref{equation:estimated_bistatic_range};
			\State Calculate $\hat{v}_k$ via \eqref{equation:estimated_bistatic_Doppler_velocity};
			\State Obtain $\hat{\theta}_k$ and $\hat{\phi}_k$ following Step \ref{step:unvec}-\ref{step_cal_theta_phi} of Algorithm \ref{alg_SVD_Decoup};
			\EndFor
		\end{algorithmic}
	\end{algorithm}
	Based on the discussions in Sections \ref{subsec_Matrices_Recovery} and \ref{subsec_Parameter_Estimation}, we summarize the proposed tensor decomposition and spatial smoothing-based algorithm for sensing parameter estimation in Algorithm \ref{alg_para_esti}.

	\textit{Complexity Analysis:}
	The main computational complexity is analyzed as follows:
	\begin{itemize}
		\item \textbf{Step 2:} The computational complexity of constructing $\mathbf{Y}_{\mathrm{S}}$ is initially $\mathcal{O}(L_1L_2NR)$.
		However, by leveraging the sparse cyclic selection matrices $\mathbf{J}_{l}$ to extract and assemble specific rows from $\mathbf{Y}_{(1)}$ into the extended matrix formulation, this complexity can be reduced to practically negligible levels.

		\item \textbf{Step 3:} The complexity of performing truncated SVD on $\mathbf{Y}_S$ is $\mathcal{O}(L_1  L_2 N  R K )$.

		\item \textbf{Step 4:} Calculating the pseudo-inverse of $\mathbf{U}_1$ has a complexity of $\mathcal{O}(L_1 N K)$.
		Besides, performing EVD on $\mathbf{U}_1^{\dagger} \mathbf{U}_2$ has a complexity of $\mathcal{O}(K^3)$.

		\item \textbf{Step 5-7:} The construction of matrices $\mathbf{C}$, $\mathbf{B}$, and $\mathbf{A}$ primarily requires the complexity of $\mathcal{O}(K M)$, $\mathcal{O}(L_1N^2 K)$, and $\mathcal{O}(L_2R^2 K)$, respectively.

		\item \textbf{Step 9-13:} Denote by $G$ the number of iterations in the one-dimensional search method.
		In the parameter extraction stage, the complexity is dominated by that of estimating $\{\theta _{k}^{\mathrm{r}},\phi _{k}^{\mathrm{r}}\}_{k=1,k\ne k_{\mathrm{LoS}}}^{K+1}$, which is given by $\mathcal{O}(RKG(J_{\mathrm{v}}N_{\mathrm{v}}+J_{\mathrm{h}}N_{\mathrm{h}}))$.
	\end{itemize}
	In general, the total complexity of Algorithm \ref{alg_para_esti} can be summarized as $\mathcal{O} (L_1L_2NRK+L_1N^2K+L_2R^2K+RKG(J_{\mathrm{v}}N_{\mathrm{v}}+J_{\mathrm{h}}N_{\mathrm{h}}))$.

	\begin{remark}
		In the previous analysis, $k\in \left\{ 1,\dots ,K+1 \right\} $ has been used to index the propagation paths between tBS $n_{\mathrm{t}}$ and rBS $n_{\mathrm{r}}$.
		Since the index $k_{\mathrm{LoS}}$ can be obtained at step \ref{step_getkLoS} of Algorithm \ref{alg_para_esti}, 
		we reallocate the index domain $k\in \left\{ 1,\dots ,K \right\} $ to identify the $K$ targets in the following formulations.
		In addition, we will preserve the subscripts $n_{\mathrm{t}}$ and $n_{\mathrm{r}}$ in all sensing parameters to highlight the association with their respective tBS-rBS pairs, departing from the simplified notations in the previous discussions.
	\end{remark}

	\section{Position and Velocity Estimation}\label{Sec_Pos_Vel_Est}
	Based on the bistatic ranges $\{\hat{d}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}\}$ and AoA parameters $\{\hat{\theta}_{n_{\mathrm{t}},k,n_{\mathrm{r}}},\hat{\phi}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}\}$ estimated from a distributed tBS-rBS pair, the system can theoretically estimate the 3D positions of all targets. 
	However, since only bistatic Doppler velocities $\{\hat{v}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}\}$ are measurable at each rBS, resolving the true 3D velocities necessitates fusing at least three independent radial velocity estimates. 
	To tackle this problem and improve the accuracy of position and velocity estimation, this section proposes a MST-based cooperative data fusion algorithm. 
	This scheme jointly resolves the data association ambiguity among estimated parameters from different tBS-rBS pairs while jointly optimizing the 3D positions and velocities of all targets.


	\subsection{Basic Target Localization}
	Let $d_{n_{\mathrm{t}},k}^{\mathrm{t}}=\left\| \mathbf{p}_{k}^{\mathrm{u}}-\mathbf{p}_{n_{\mathrm{t}}}^{\mathrm{t}} \right\| _2$ denote the distance between tBS $n_{\mathrm{t}}$ and target $k$, where $\mathbf{p}_{k}^{\mathrm{u}}=\left[ x_{k}^{\mathrm{u}},y_{k}^{\mathrm{u}},z_{k}^{\mathrm{u}} \right] ^{\mathrm{T}}$ and $\mathbf{p}_{n_{\mathrm{t}}}^{\mathrm{t}}=\left[ x_{n_{\mathrm{t}}}^{\mathrm{t}},y_{n_{\mathrm{t}}}^{\mathrm{t}},z_{n_{\mathrm{t}}}^{\mathrm{t}} \right] ^{\mathrm{T}}$ are the 3D position vectors of tBS $n_{\mathrm{t}}$ and target $k$, respectively.
	Similarly, the distance between  target $k$ and rBS $n_{\mathrm{r}}$ is defined as $d_{k,n_{\mathrm{r}}}^{\mathrm{r}}=\left\| \mathbf{p}_{k}^{\mathrm{u}}-\mathbf{p}_{n_{\mathrm{r}}}^{\mathrm{r}} \right\| _2$, where $\mathbf{p}_{n_{\mathrm{r}}}^{\mathrm{r}}=\left[ x_{n_{\mathrm{r}}}^{\mathrm{r}},y_{n_{\mathrm{r}}}^{\mathrm{r}},z_{n_{\mathrm{r}}}^{\mathrm{r}} \right] ^{\mathrm{T}}$ represents the position of rBS $n_{\mathrm{r}}$.
	Given $\hat{d}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}$, $\hat{\theta}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}$, and $\hat{\phi}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}$, the 3D position $\mathbf{p}_{k}^{\mathrm{u}}$ of target $k$ can be determined by solving the following system of equations:
	\begin{equation}\label{Prob_basic_loca}
		\begin{cases}
			d_{n_{\mathrm{t}},k}^{\mathrm{t}}+d_{k,n_{\mathrm{r}}}^{\mathrm{r}}=\hat{d}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}\\
			\mathbf{p}_{k}^{\mathrm{u}}=\mathbf{p}_{n_{\mathrm{r}}}^{\mathrm{t}}+d_{k,n_{\mathrm{r}}}^{\mathrm{r}}\hat{\mathbf{r}}^{\mathrm{r}}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}\\
		\end{cases},
	\end{equation}
	where $\hat{\mathbf{r}}^{\mathrm{r}}_{n_{\mathrm{r}},k,n_{\mathrm{r}}}$ represents the unit direction vector from target $k$ to rBS $n_{\mathrm{r}}$ derived from AoA estimations, expressed in the global coordinate system as:
	\begin{align}
		&\hat{\mathbf{r}}^{\mathrm{r}}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}=\mathbf{T}\left( \chi _{n_{\mathrm{r}}}^{\mathrm{r}} \right) \left[ \begin{array}{c}
			\sin \hat{\theta}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}^{\mathrm{r}}\cos \hat{\phi}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}^{\mathrm{r}}\\
			\sin \hat{\theta}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}^{\mathrm{r}}\sin \hat{\phi}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}^{\mathrm{r}}\\
			\cos \hat{\phi}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}^{\mathrm{r}}\\
		\end{array} \right] ,
		\\
		&\mathbf{T}\left( \chi _{n_{\mathrm{r}}}^{\mathrm{r}} \right) =\left[ \begin{matrix}
			\cos \chi _{n_{\mathrm{r}}}^{\mathrm{r}}&		\sin \chi _{n_{\mathrm{r}}}^{\mathrm{r}}&		0\\
			-\sin \chi _{n_{\mathrm{r}}}^{\mathrm{r}}&		\cos \chi _{n_{\mathrm{r}}}^{\mathrm{r}}&		0\\
			0&		0&		1\\
		\end{matrix} \right],
	\end{align}
	where $\chi _{n_{\mathrm{r}}}^{\mathrm{r}}$ is the horizontal orientation of rBS $n_{\mathrm{r}}$'s array, defined as the angle between the array normal and the global $x$-axis.
	Solving \eqref{Prob_basic_loca} for $\forall k$ yields basic position estimates $\{ \hat{\mathbf{p}}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}^{\mathrm{u}} \} _{k=1}^{K}$ related to tBS $n_{\mathrm{t}}$ and rBS $n_{\mathrm{r}}$.
	However, independent processing across the tBS-rBS pairs introduces data association ambiguity: 
	due to inconsistent indexing across pairs,
	the estimated $\hat{\mathbf{p}}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}^{\mathrm{u}}$ and $\hat{\mathbf{p}}_{n^\prime _{\mathrm{t}},k,n^\prime _{\mathrm{r}}}^{\mathrm{u}}$ may correspond to different targets when $n_{\mathrm{t} }\ne n^\prime _{\mathrm{t}}$ or $n _{\mathrm{r}} \ne n^\prime _{\mathrm{r}}$.
	In addition, estimation errors in $\hat{d}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}$, $\hat{\theta}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}$, and $\hat{\phi}_{n_{\mathrm{t}},k,n_{\mathrm{r}}}$ lead to biases in position estimates.
	Although greedy algorithms can be applied for the target-to-estimate association \cite{9583869}, the erroneous position estimates cannot be effectively eliminated. 
	This limitation often leads to incorrect data associations or significant global positioning biases, particularly in scenarios with a large number of targets or low signal-to-noise ratios (SNRs).
	In the following, an effective error elimination and data association algorithm is proposed based on the MST method.

	\subsection{Error Elimination and Data Association}\label{Sec_DataAssociation}
	To establish the MST-based data association framework, we first define an undirected weighted graph $\mathcal{G} =\left( \mathcal{V} ,\mathcal{E} ,W\right) $ consisting of the vertex set $\mathcal{V} $, the edge set $\mathcal{E}$, and the weight function $W$ as illustrated in Fig. \ref{fig:MST}(a).
	Specifically, $\mathcal{V} $ is represented as a union of $N_{\mathrm{t}}\times N_{\mathrm{r}}$ subsets as follows
	\begin{equation}\label{equation:Graph_V}
		\mathcal{V} =\bigcup_{n_{\mathrm{t}}=1}^{N_{\mathrm{t}}}{\bigcup_{n_{\mathrm{r}}=1}^{N_{\mathrm{r}}}{\mathcal{V} _{n_{\mathrm{t}},n_{\mathrm{r}}}}},
	\end{equation}
	where each subset $\mathcal{V} _{n_{\mathrm{t}},n_{\mathrm{r}}}$ corresponds to the estimates from tBS $n_{\mathrm{t}}$ and rBS $n_{\mathrm{r}}$, indexed as
	\begin{equation}
		\mathcal{V} _{n_{\mathrm{t}},n_{\mathrm{r}}}= \{ ( ( n_{\mathrm{r}}-1 ) N_{\mathrm{t}}+n_{\mathrm{t}}-1 ) K+1,\dots ,( ( n_{\mathrm{r}}-1 ) N_{\mathrm{t}}+n_{\mathrm{t}} ) K \}.
	\end{equation}
	The edge $\mathcal{E}$ connects vertices across different tBS-rBS pairs, defined as
	\begin{equation}
		\mathcal{E} =\left\{ \left( e_1,e_2 \right) |e_1\in V_{n_{\mathrm{t}},n_{\mathrm{r}}},\, e_2\in V\backslash V_{n_{\mathrm{t}},n_{\mathrm{r}}} \right\} .
	\end{equation}
	The edge weight between any two vertices $e_1$ and $e_2$ is defined as the Euclidean distance between their corresponding position estimates as follows
	\begin{align}\label{equation:Graph_W}
		&W\left( e_1,e_2 \right) =\left\| \hat{\mathbf{p}}_{\xi ^{\mathrm{t}}\left( e_1 \right) ,\xi ^{\mathrm{u}}\left( e_1 \right) ,\xi ^{\mathrm{r}}\left( e_1 \right)}-\hat{\mathbf{p}}_{\xi ^{\mathrm{t}}\left( e_2 \right) ,\xi ^{\mathrm{u}}\left( e_2 \right) ,\xi ^{\mathrm{r}}\left( e_2 \right)} \right\| _2, \notag
		\\
		&\forall \left( e_1,e_2 \right) \in \mathcal{E} ,
	\end{align}
	where $\xi ^{\mathrm{t}}\left( e \right) =\mathrm{mod}\left( \mathrm{mod}\left( e-1,K \right) ,N_{\mathrm{t}} \right) +1$, $\xi ^{\mathrm{u}}\left( e \right) =\lfloor \frac{e_1-1}{K} \rfloor +1$ and $\xi ^{\mathrm{r}}\left( e \right) =\lfloor \frac{\mathrm{mod}\left( e_1-1,K \right)}{N_{\mathrm{t}}} \rfloor +1$ decodes the tBS-target-rBS indices from vertex $e$, respectively,
	with $\mathrm{mod}$ and $\lfloor \cdot \rfloor $ denoting the modulus and floor operations, respectively.

	%\newcounter{TempEqCnt}  % 创建临时计数器
	%\setcounter{TempEqCnt}{\value{equation}}  % 保存当前编号
	%%\setcounter{equation}{69}  % 设置跨栏公式编号需减1）
	%\begin{figure*}[ht]
	%	\begin{equation}\label{equation_weights}
		%		W\left( e_1,e_2 \right) =\left\| \hat{\mathbf{p}}_{\mathrm{mod}\left( \mathrm{mod}\left( e_1-1,K \right) ,N_{\mathrm{t}} \right) +1,\lfloor \frac{e_1-1}{K} \rfloor +1,\lfloor \frac{\mathrm{mod}\left( e_1-1,K \right)}{N_{\mathrm{t}}} \rfloor +1}-\hat{\mathbf{p}}_{\mathrm{mod}\left( \mathrm{mod}\left( e_2-1,K \right) ,N_{\mathrm{t}} \right) +1,\lfloor \frac{e_2-1}{K} \rfloor +1,\lfloor \frac{\mathrm{mod}\left( e_2-1,K \right)}{N_{\mathrm{t}}} \rfloor +1} \right\| _2
		%	\end{equation}
	%	\rule{\textwidth}{0.4pt}
	%\end{figure*}
	%\setcounter{equation}{\value{TempEqCnt}+1}  % 恢复原编号


	It can be noted that valid position estimates of the same target should cluster spatially, while erroneous estimates deviate significantly.
	That is, a vertex is likely corresponding to erroneous estimate if all its adjacent edges have large weights.
	To eliminate such outliers, we introduce a threshold $\varpi$ and define the following pruned edge set
	\begin{equation}
		\mathcal{E} ^{\prime}=\left\{ \left( e_1,e_2 \right)\in \mathcal{E} |W_{\min}\left( e_1 \right) >\varpi  \right\} ,
	\end{equation}
	where $W_{\min}\left( e_1 \right)$ denotes the minimum weight among all edges adjacent to $e_1$.
	By removing these edges, the graph $\mathcal{G} $ is updated as
	\begin{equation}\label{equation:updateG}
		\tilde{\mathcal{G}}=\left( \mathcal{V} , \mathcal{E} \backslash \mathcal{E} ^{\prime} , W\right) ,
	\end{equation}
	which isolates vertices corresponding to erroneous estimates as illustrated in Fig. \ref{fig:MST}b.

	Finally, the MST of the pruned graph $\tilde{\mathcal{G}}$ can be computed using the well-established algorithms such as Prim's \cite{PrimShortest} or Kruskal's \cite{KruskalOn}.
	Since the valid position estimates are clustered, the edges connecting  estimates of the same target usually exhibit smaller weights and are preferentially retained in the MST.
	Therefore, the final data association is achieved by removing the $K-1$ longest edges from the MST.
	This operation partitions the MST into $K$ sub-graphs as shown in Fig. \ref{fig:MST}(c), each corresponding to a unique target. 


