\subsubsection{Minimax Optimization:} 
\label{Section 3.3.3}
Following the approach of \cite{dave2022spact, wu2020privacy}, we adopt a minimax optimization strategy to optimize the loss function of \(f_A\), represented by Equation \ref{anonymizer_loss}. The goal is to minimize the utility task loss \(L_T\) and the penalty loss \(L_{\text{penalty}}\) while maximizing the budget task loss \(L_B\). This ensures improved action performance with reduced privacy leakage. The complete training algorithm of the anonymizer, utility, and budget module is explained in Algorithm \ref{algorithm}.


% %%%%%-------------------------------------------------------------------%%%%%
\begin{algorithm}[]
\caption{Penalty driven framework}
\label{algorithm}
\begin{algorithmic}[1]

\State \textbf{Inputs:}
\State Datasets: \(X_{\text{input}}\)
\State Epochs: \(e_{\text{anon}}, e_{\text{action}}, e_{\text{privacy}}\)
\State Learning Rates: \(\alpha_A, \alpha_B, \alpha_T\)
\State Hyperparameters: \(\lambda_P\)

\State \textbf{Output:} \(\theta_A, \theta_T', \theta_B'\)

\State \textbf{Learnable Parameter}: \(\theta_A, \theta_T, \theta_B\)

\State \textbf{Initialization:}
\State \(\theta_A \gets \theta_A - \alpha_A \nabla_{\theta_A} \mathcal{L}_{L1}(\theta_A)\) 
\State \Comment{Equation \ref{l1 loss}}
\State \(\theta_B\): SimCLR \cite{chen2020simple} weights trained on ImageNet \cite{deng2009imagenet} 
\State \(\theta_T\): pre-trained weight on Kinetics400 \cite{carreira2017quo}

\State \textbf{Anonymization Training:}
\For{\(e_0 \gets 1\) to \(e_{\text{anon}}\)}
    \State \textbf{Step-1:} update anonymizer parameters 
    \State     
    \(\begin{aligned}
        &\theta_A \leftarrow \theta_A - \alpha_A \nabla_{\theta_A} [ L_T (\theta_A, \theta_T) - L_B (\theta_A, \theta_B) \\
        &+ \lambda_P L_P (\theta_A, \theta_T)]
    \end{aligned}\)
    \State \textbf{Step-2:} update utility and budget parameters
    \State \(\theta_T \gets \theta_T - \alpha_T \nabla_{\theta_T} L_T(\theta_T, \theta_A)\)
    \State \(\theta_B \gets \theta_B - \alpha_B \nabla_{\theta_B} L_B(\theta_B, \theta_A)\)
\EndFor

\State \textbf{Privacy-Preserved Action Recognition Training:}
\For{\(e_0 \gets 1\) to \(e_{\text{action}}\)}
    \State \(\theta_T' \gets \theta_T' - \alpha_T' \nabla_{\theta_T'} L_{T}(\theta_T', \theta_A^*)\)
\EndFor

\State \textbf{Privacy Leakage Training:}
\For{\(e_0 \gets 1\) to \(e_{\text{privacy}}\)}
    \State \(\theta_B' \gets \theta_B' - \alpha_B' \nabla_{\theta_B'} L_{T}(\theta_B', \theta_A^*)\)
\EndFor

\end{algorithmic}
\end{algorithm}



