\subsubsection{Comparison with the state of the art}
\begin{figure}[t] % Use figure* for two-column wide figure
    \centering
    \begin{subfigure}{0.45\linewidth}
        \centering
        \includegraphics[width=\linewidth]{figures/alfa_beta0.2_n500.png}
        \caption{Self-transition probability $P_{ss}=0.8$.}
