\addplot[black,very thick] table[x index=0,y index=2] {images/log-without-vgpreload.dat};
\addlegendentry{$\frac{\mathrm d}{\mathrm dx} \text{{\ttfamily log}}(x)$}
\addplot[black,very thin,dashed] table[x index=0,y index=3] {images/log-without-vgpreload.dat};
