    $\Gamma,$ the \textit{glass} data structure.\;
    $\chi,$ the hash table.
}
\Begin{
    $\pi_\mathrm{thres} \longleftarrow \widehat{\infty}$\;
    $\underline{\text{glass-init}}(\Gamma)$\;
