    $\chi,$ the hash table.
}
\Begin{
    \uIf{$\pi \PriceBetter \pi_\mathrm{thres}$}{
        \uIf{$\underline{\text{glass-size}}(\Gamma) < \underline{\text{glass-max-size}}(\Gamma)$}{
            $\underline{\text{glass-insert}}(\Gamma, \pi, a)$\;
