\section{Derivation for Equation 17-19}
We will give the derivation of the equation 17-19
\begin{equation}
    p(x)  = \frac{\Gamma(\frac{v}{2} + \frac{d}{2})}{\Gamma(\frac{v}{2})} * \frac{{|\Sigma|}^{-\frac{1}{2}}}{(v * \pi)^{\frac{d}{2}}} * [1 + \frac{1}{v}*(x-\mu)^{T}\Sigma^{-1}(x-\mu)]^{-\frac{d+v}{2}}
\end{equation}

\begin{equation}
    ln[p(x)]  = ln[\frac{\Gamma(\frac{v}{2} + \frac{d}{2})}{\Gamma(\frac{v}{2})}] - \frac{1}{2}*ln(|\Sigma|) - \frac{d+v}{2}ln(1 + \frac{1}{v}*(x-\mu)^{T}\Sigma^{-1}(x-\mu))
\end{equation}
Notice:
\begin{equation}
    \frac{\partial{ln(|\Sigma|)}}{\partial{\theta}} = \frac{1}{|\Sigma|}*\sum_{i,j}{M_{i,j}\frac{\partial{\Sigma_{i,j}}}{\theta}} = \frac{1}{|\Sigma|}*tr(\frac{\partial{\Sigma}}{\partial{\theta}}*M^{T})=tr(\frac{\partial{\Sigma}}{\partial{\theta}}*\Sigma^{-1})
\end{equation}
We have:
\begin{equation}
\begin{split}
    \frac{\partial{ln[p(x)]}}{\partial{\theta}}= &-\frac{1}{2}tr(\frac{\partial{\Sigma}}{\partial{\theta}}*\Sigma^{-1})-\frac{d+v}{2}*\frac{1}{v+(x-u)^{T}\Sigma^{-1}(x-u)}* \\
    & [-2(\frac{\partial{u}}{\partial{\theta}})^{T}\Sigma^{-1}(x-u)+(x-u)^{T}\frac{\partial{\Sigma^{-1}}}{\partial{\theta}}(x-u)]
\end{split}
\end{equation}
Now we want to calculate Fisher Information Matrix $F$, where $F_{i,j}=E_{x}[\nabla ln[p(x|\theta_{i})]^{T}\nabla ln[p(x|\theta_{j})]^{T}]$, after which we can get the true gradient from $g = F^{-1}(\theta)\nabla ln[p(x|\theta)]$
With equation $(2)$, we can calculate the following thing:
\begin{equation}
\begin{split}
    F_{ij}[\theta]= & E_{x}[\frac{1}{4}tr(\frac{\partial{\Sigma}}{\partial{\theta_{i}}}*\Sigma^{-1})tr(\frac{\partial{\Sigma}}{\partial{\theta_{j}}}*\Sigma^{-1}) +
    \\ &(\frac{d+v}{v+s})^{2}(\frac{\partial{\mu}}{\partial{\theta_{i}}})^{T}\Sigma^{-1}(x-u)(\frac{\partial{\mu}}{\partial{\theta_{j}}})^{T}\Sigma^{-1}(x-u)+
    \\ & \frac{1}{4}(\frac{d+v}{v+s})^{2}(x-u)^{T}\frac{\partial{\Sigma^{-1}}}{\partial{\theta_{i}}}(x-u)(x-u)^{T}\frac{\partial{\Sigma^{-1}}}{\partial{\theta_{j}}}(x-u)+
    \\ & \frac{d+v}{2(v+s)}tr(\frac{\partial{\Sigma}}{\partial{\theta_{i}}}*\Sigma^{-1})(x-u)^{T}\frac{\partial{\Sigma^{-1}}}{\partial{\theta_{j}}}(x-u)]
\end{split}
\end{equation}
Where $s = (x-u)^{T}\Sigma^{-1}(x-u)$, and we will split the $F_{i,j}(\theta)$ into 4 parts to calculate as shown in Equation$(5)$.
\subsection{Part1}
We choose to keep the form as it is in Equation$(5)$.
\begin{equation}
    Part_{1} = \frac{1}{4}tr(\frac{\partial{\Sigma}}{\partial{\theta_{i}}}*\Sigma^{-1})tr(\frac{\partial{\Sigma}}{\partial{\theta_{j}}}*\Sigma^{-1})
\end{equation}
\subsection{Part2}
\begin{equation}
    \begin{split}
        Part_{2}= & E_{x}[(\frac{d+v}{v+s})^{2}(\frac{\partial{\mu}}{\partial{\theta_{i}}})^{T}\Sigma^{-1}(x-u)(\frac{\partial{\mu}}{\partial{\theta_{j}}})^{T}\Sigma^{-1}(x-u)]\\
        = & (\frac{d+v}{v})^{2}(\frac{\partial{\mu}}{\partial{\theta_{i}}})^T\Sigma^{-1}E_{x}[\frac{(x-u)(x-u)^{T}}{(1+\frac{s}{v})^{2}}]\Sigma^{-1}\frac{\partial{\mu}}{\partial{\theta_{j}}}
    \end{split}
\end{equation}
\begin{equation}
    \begin{split}
        E_{x}[\frac{(x-u)(x-u)^{T}}{(1+\frac{s}{v})^{2}}]
         = &\int_{x}\frac{\Gamma(\frac{v}{2} + \frac{d}{2})}{\Gamma(\frac{v}{2})} * \frac{{|\Sigma|}^{-\frac{1}{2}}}{(v * \pi)^{\frac{d}{2}}} * [1 + \frac{s}{v}]^{-\frac{d+v}{2}}*\frac{(x-u)(x-u)^{T}}{(1+\frac{s}{v})^{2}}\mathrm{d}x \\
        = &\int_{x}\frac{\Gamma(\frac{v}{2} + \frac{d}{2})}{\Gamma(\frac{v}{2})} * \frac{{|\Sigma|}^{-\frac{1}{2}}}{(v * \pi)^{\frac{d}{2}}} * [1 + \frac{s}{v}]^{-\frac{d+v+4}{2}}*(x-u)(x-u)^{T}\mathrm{d}x \\
        = &\frac{v(v+2)}{(d+v)(d+v+2)} * \int_{x} P_{t}(x|\mu, v+4,\Sigma^{'})(x-u)(x-u)^{T}\mathrm{d}x \\
        = & \frac{v^{2}}{(d+v)(d+v+2)}\Sigma \\
    \end{split}
\end{equation}
So we can get the following form:
\begin{equation}
    Part_{2}=\frac{d+v}{d+v+2}(\frac{\partial{\mu}}{\partial{\theta_{i}}})^{T}\Sigma^{-1}(\frac{\partial{\mu}}{\partial{\theta_{j}}})
\end{equation}
In CMA-ES, this equation(9) is shown below:
\begin{equation}
    Part_{2,CMAES}=(\frac{\partial{\mu}}{\partial{\theta_{i}}})^{T}\Sigma^{-1}(\frac{\partial{\mu}}{\partial{\theta_{j}}})
\end{equation}
\subsection{Part3}
\begin{equation}
    \begin{split}
    Part_{3}= &\frac{(d+v)^{2}}{v^{2}}\frac{\Gamma(\frac{v}{2} + \frac{d}{2})}{\Gamma(\frac{v}{2})} * \frac{{|\Sigma|}^{-\frac{1}{2}}}{(v * \pi)^{\frac{d}{2}}} \int_{y}y^{T}Ayy^{T}By[1+\frac{y^{T}\Sigma^{-1}y}{v}]^{-\frac{d+v+4}{2}}\mathrm{d}y\\
    = & \frac{(d+v)(v+2)}{4v(d+v+2)} * \int_{y}y^{T}Ayy^{T}ByP_{t}(0,v+4,\Sigma^{'})\mathrm{d}y
    \end{split}
\end{equation}
where $y^{T}Ay=(x-u)^{T}\frac{\partial{\Sigma^{-1}}}{\partial{\theta_{i}}}(x-u)$ and $y^{T}By=(x-u)^{T}\frac{\partial{\Sigma^{-1}}}{\partial{\theta_{j}}}(x-u)$. 
Further, we can let $(x-u)^{T}\Sigma^{-\frac{1}{2}}(x-u) = z^{T}A^{'}z$, where $A^{'}=\frac{v}{v+4}(-\Sigma^{-\frac{1}{2}}\frac{\partial{\Sigma}}{\partial{\theta_{i}}}\Sigma^{-\frac{1}{2}})$
\begin{equation}
    \begin{split}
        \int_{y}y^{T}Ayy^{T}ByP_{t}(0,v+4,\Sigma^{'})\mathrm{d}y
        = \int_{z}z^{T}A^{'}zz^{T}B^{'}zP_{t}(0,v+4,I)\mathrm{d}z 
    \end{split}
\end{equation}
\begin{equation}
    \begin{split}
        z^{T}A^{'}zz^{T}B^{'}z = \sum_{i,j,m,n}z_{i}a_{ij}z_{j}z_{m}b_{mn}z_{n}
    \end{split}
\end{equation}
According to the conclusion from \cite{c33,c34,c35,c36}, we have:
\begin{equation}
    E[\Pi_{i=1}^{p}Z_{i}^{k_{i}}]=V^{\frac{v}{2}}\frac{\Gamma(\frac{v-k}{2})}{\Gamma(\frac{v}{2})2^{k}}*\Pi_{i=1}^{p}\frac{k_{i}!}{\frac{k_{i}}{2}!}
\end{equation}
Where $k = \sum_{i}k_{i}$.
So we can get that:
\begin{equation}
\begin{split}
      E_{z}[\sum_{k}a_{kk}b_{kk}z_{k}^{4}]
    =&\sum_{k}a_{kk}b_{kk}\frac{3(v+4)^2}{v(v+2)}
\end{split}
\end{equation}
\begin{equation}
\begin{split}
      E_{z}[\sum_{i \neq j}(a_{ii}b_{jj}+a_{ij}b_{ij}+a_{ij}b_{ji})z_{i}^{2}z_{j}^{2}]
    = &(tr(A')tr(B')+tr(AB^{T})+tr(AB) - 3\sum_{i}(a_{ii}b_{ii}))\frac{(v+4)^2}{v(v+2)}
\end{split}
\end{equation}
Conclude from equation(12)~(16),we have:
\begin{equation}
\begin{split}
     Part_{3}=\frac{d+v}{4(d+v+2)}[tr(\frac{\partial \Sigma}{\partial \theta_{i}}\Sigma^{-1})tr(\frac{\partial \Sigma}{\partial \theta_{j}}\Sigma^{-1}) + 2tr(\frac{\partial \Sigma}{\partial \theta_{i}}\Sigma^{-1}\frac{\partial \Sigma}{\partial \theta_{j}}\Sigma^{-1})]
\end{split}
\end{equation}
\subsection{Part4}
\begin{equation}
\begin{split}
     E_{x}[\frac{d+v}{2(v+s)}tr(\frac{\partial{\Sigma}}{\partial{\theta_{i}}}*\Sigma^{-1})(x-u)^{T}\frac{\partial{\Sigma^{-1}}}{\partial{\theta_{j}}}(x-u)] 
    =  \frac{d+v}{2v}tr(\frac{\partial{\Sigma}}{\partial{\theta_{i}}}\Sigma^{-1})E_x[tr(\frac{(x-u)(x-u)^T}{1+\frac{s}{v}})]\frac{\partial{\Sigma^{-1}}}{\partial{\theta_{j}}}
\end{split}
\end{equation}
\begin{equation}
\begin{split}
    E_x[tr(\frac{(x-u)(x-u)^T}{1+\frac{s}{v}})]
    =&\int_{x} \frac{\Gamma(\frac{v}{2} + \frac{d}{2})}{\Gamma(\frac{v}{2})} * \frac{{|\Sigma|}^{-\frac{1}{2}}}{(v * \pi)^{\frac{d}{2}}}(1+\frac{(x-u)^{T}\Sigma^{-1}(x-u)}{v})^{-\frac{d+v+2}{2}}(x-u)(x-u)^{T}\mathrm{d}x \\  
    =& \frac{v}{d+v}\Sigma
\end{split}
\end{equation}
\begin{equation}
    Part_{4}=-\frac{1}{2}tr(\frac{\partial \Sigma}{\partial \theta_{i}}\Sigma^{-1})tr(\frac{\partial \Sigma}{\partial \theta_{j}}\Sigma^{-1})
\end{equation}
\subsection{Combine}
Now we get the expression for $F_{i,j}(\theta)$, which is shown below:
\begin{equation}
    F_{i,j}(\theta)=\frac{1}{2}\frac{d+v}{d+v+2}tr(\frac{\partial \Sigma}{\partial \theta_{i}}\Sigma^{-1}\frac{\partial \Sigma}{\partial \theta_{j}}\Sigma^{-1}) - \frac{1}{2(d+v+2)}tr(\frac{\partial \Sigma}{\partial \theta_{i}}\Sigma^{-1})tr(\frac{\partial \Sigma}{\partial \theta_{j}}\Sigma^{-1}) +
    \frac{d+v}{d+v+2}(\frac{\partial{\mu}}{\partial{\theta_{i}}})^{T}\Sigma^{-1}(\frac{\partial{\mu}}{\partial{\theta_{j}}})
\end{equation}
Note that the parameter theta of $F$ includes the mean $\mu$(we will use $m$ later) of the distribution at this point and the transformation matrix $\Sigma$ (symmetric matrix), we can think of $F$ as a matrix whose rows and columns are $d^2 + d$. At this point $F$ is a diagonal matrix, and we can simply find the inverse of its two bins. Here we make an approximation by considering the second term of $F_{i,j}$ as 0. This can be done because in general it can be assumed that the two-paradigm number of the transformation matrix is strictly bounded, so that the trace of its inverse matrix will be strictly bounded as well, and the term $d+v+2$ will be no less than $v$ (the degrees of freedom), and we can see in our experiments that $v$ will be large enough in general; and also for the convenience of the theoretical derivation.
According to equation $(4)$, we have:
\begin{equation}
    F_{m} = \frac{d+v}{d+v+2}\Sigma^{-1}
\end{equation}
\begin{equation}
    F_{m}^{-1} = \frac{d+v+2}{d+v}\Sigma
\end{equation}
\begin{equation}
    \nabla_{m}lnP(x) = \frac{d+v}{v+(x-m)^T\Sigma^{-1}(x-m)}\Sigma^{-1}(x-m)
\end{equation}
So,
\begin{equation}
    F_{m}^{-1}\nabla_{m}lnP(x)=\frac{d+v+2}{s+v}(x-m)
\end{equation}
Similarly,
\begin{equation}
    F_{\Sigma}^{-1} = -2\frac{d+v+2}{d+v}(\frac{\partial vech(\Sigma)}{\partial\Sigma^T})^{-1}(\frac{\partial vech(2\Sigma^{-1} - diag(\Sigma^{-1})}{\partial\Sigma^T})^{T}
\end{equation}
\begin{equation}
\begin{split}
    \nabla_{\Sigma}lnP(x) 
    =& -\frac{1}{2}tr(\frac{\partial{\Sigma}}{\partial{\theta}}*\Sigma^{-1}) - \frac{d+v}{2(v+s)})(x-m)^T\frac{\partial{\Sigma^{-1}}}{\partial{\theta}}(x-m) \\
    =& -\frac{1}{2}tr(\frac{\partial{\Sigma^{-1}}}{\partial{\Sigma}})(\frac{d+v}{v+s}(x-m)(x-m)^T-\Sigma) \\
    =& -\frac{1}{2}(\frac{\partial vech(2\Sigma^{-1} - diag(\Sigma^{-1})}{\partial\Sigma^T})^{T}(\frac{d+v}{v+s}(x-m)(x-m)^T-\Sigma)
\end{split}
\end{equation}
So,
\begin{equation}
    F_{\Sigma}^{-1}\nabla_{\Sigma}lnP(x)=\frac{d+v+2}{d+v}(\frac{d+v}{v+s}(x-m)(x-m)^T-\Sigma)
\end{equation}
Where, $s = (x-u)^{T}\Sigma^{-1}(x-u)$


